    const score_desc = [_]types.SortField{.{ .field = "_score", .desc = true }};
    const score_req = types.SearchRequest{
        .order_by = &score_desc,
        .full_text = .{ .match = .{ .field = "body", .text = "alpha" } },
    };

    var left = [_]types.SearchHit{
