fn parseFuzzyOptions(object: anytype, out: *FieldFuzzy) !void {
    if (object.get("max_edits")) |edits| {
        out.max_edits = jsonU8(edits) orelse return error.InvalidArgument;
        if (out.max_edits > pattern_filter_contract.max_fuzzy_edits) {
            return error.InvalidArgument;
        }
    }
    if (object.get("prefix_length")) |prefix| out.prefix_len = jsonU8(prefix) orelse return error.InvalidArgument;
    if (object.get("auto_fuzzy")) |auto| {
        if (auto != .bool) return error.InvalidArgument;
        out.auto_fuzzy = auto.bool;
        if (auto.bool) out.max_edits = autoFuzzyEdits(out.term);
    }
}

fn autoFuzzyEdits(term: []const u8) u8 {
    return if (term.len > 5) 2 else if (term.len > 2) 1 else 0;
}

fn parseScalarTerms(alloc: Allocator, value: std.json.Value) ![]const []const u8 {
    if (value != .array or value.array.items.len == 0) return error.InvalidArgument;
    const out = try alloc.alloc([]const u8, value.array.items.len);
    for (value.array.items, 0..) |item, i| {
        out[i] = try jsonScalarTermAlloc(alloc, item);
    }
    return out;
}

fn jsonScalarTermAlloc(alloc: Allocator, value: std.json.Value) ![]const u8 {
    return switch (value) {
        .string => |text| try alloc.dupe(u8, text),
        .integer => |number| try std.fmt.allocPrint(alloc, "{}", .{number}),
        .float => |number| try std.fmt.allocPrint(alloc, "{d}", .{number}),
        .number_string => |text| try alloc.dupe(u8, text),
        .bool => |boolean| try alloc.dupe(u8, if (boolean) "true" else "false"),
        .null => try alloc.dupe(u8, "null"),
        else => error.InvalidArgument,
    };
}

const JsonRangeBound = struct {
    value: std.json.Value,
    inclusive: bool,
};

fn parseStandardRangeQuery(
    value: std.json.Value,
    runtime_schema: ?runtime_schema_mod.TableSchema,
) !search_mod.SearchQuery {
    if (value != .object) return error.InvalidArgument;
    if (value.object.get("field") orelse value.object.get("path")) |field_value| {
        const field = jsonString(field_value) orelse return error.InvalidArgument;
        return try parseStandardRangeObject(field, value.object, runtime_schema);
    }

    if (value.object.count() != 1) return error.InvalidArgument;
    var it = value.object.iterator();
    const entry = it.next() orelse return error.InvalidArgument;
    if (entry.value_ptr.* != .object) return error.InvalidArgument;
    return try parseStandardRangeObject(entry.key_ptr.*, entry.value_ptr.object, runtime_schema);
}

fn parseStandardRangeObject(
    field: []const u8,
    object: anytype,
    runtime_schema: ?runtime_schema_mod.TableSchema,
) !search_mod.SearchQuery {
    const schema = runtime_schema orelse return error.InvalidArgument;
    const mapping = runtime_schema_mod.resolveDeclaredFieldType(schema, field) orelse return error.InvalidArgument;
    const lower = try standardRangeLowerBound(object);
    const upper = try standardRangeUpperBound(object);
    if (lower == null and upper == null) return error.InvalidArgument;

    return switch (mapping.field_type) {
        .numeric => .{ .numeric_range = .{
            .field = field,
            .min = if (lower) |bound| try jsonOptionalF64Strict(bound.value) else null,
            .max = if (upper) |bound| try jsonOptionalF64Strict(bound.value) else null,
            .inclusive_min = if (lower) |bound| bound.inclusive else true,
            .inclusive_max = if (upper) |bound| bound.inclusive else false,
        } },
        .datetime => .{ .date_range = .{
            .field = field,
            .start_ns = if (lower) |bound| try jsonOptionalDateOrNs(bound.value) else null,
            .end_ns = if (upper) |bound| try jsonOptionalDateOrNs(bound.value) else null,
            .inclusive_start = if (lower) |bound| bound.inclusive else true,
            .inclusive_end = if (upper) |bound| bound.inclusive else false,
        } },
        .keyword, .link => .{ .term_range = .{
            .field = field,
            .min = if (lower) |bound| try jsonOptionalStringStrict(bound.value) else null,
            .max = if (upper) |bound| try jsonOptionalStringStrict(bound.value) else null,
            .inclusive_min = if (lower) |bound| bound.inclusive else true,
            .inclusive_max = if (upper) |bound| bound.inclusive else false,
        } },
        else => error.InvalidArgument,
    };
}

fn standardRangeLowerBound(object: anytype) !?JsonRangeBound {
    var found: ?JsonRangeBound = null;
    if (object.get("gte")) |value| try setJsonRangeBound(&found, value, true);
    if (object.get("gt")) |value| try setJsonRangeBound(&found, value, false);
    if (object.get("from")) |value| try setJsonRangeBound(&found, value, (try jsonOptionalBoolStrict(object.get("include_lower"))) orelse true);
    if (object.get("min")) |value| try setJsonRangeBound(&found, value, (try jsonOptionalBoolStrict(object.get("inclusive_min"))) orelse true);
    return found;
}

fn standardRangeUpperBound(object: anytype) !?JsonRangeBound {
    var found: ?JsonRangeBound = null;
    if (object.get("lte")) |value| try setJsonRangeBound(&found, value, true);
    if (object.get("lt")) |value| try setJsonRangeBound(&found, value, false);
    if (object.get("to")) |value| try setJsonRangeBound(&found, value, (try jsonOptionalBoolStrict(object.get("include_upper"))) orelse true);
    if (object.get("max")) |value| try setJsonRangeBound(&found, value, (try jsonOptionalBoolStrict(object.get("inclusive_max"))) orelse false);
    return found;
}

fn setJsonRangeBound(found: *?JsonRangeBound, value: std.json.Value, inclusive: bool) !void {
    if (found.* != null or value == .null) return error.InvalidArgument;
    found.* = .{ .value = value, .inclusive = inclusive };
}

fn parseNumericRangeQuery(value: std.json.Value) !search_mod.NumericRangeQuery {
    if (value != .object) return error.InvalidArgument;
    const field = try requiredFieldOrPath(value.object);
    const min = try jsonOptionalF64StrictNullable(value.object.get("min"));
    const max = try jsonOptionalF64StrictNullable(value.object.get("max"));
    if (min == null and max == null) return error.InvalidArgument;
    return .{
        .field = field,
        .min = min,
        .max = max,
        .inclusive_min = (try jsonOptionalBoolStrict(value.object.get("inclusive_min"))) orelse true,
        .inclusive_max = (try jsonOptionalBoolStrict(value.object.get("inclusive_max"))) orelse false,
    };
}

fn parseDateRangeQuery(value: std.json.Value) !search_mod.DateRangeQuery {
    if (value != .object) return error.InvalidArgument;
    const field = try requiredFieldOrPath(value.object);
    const start_ns = if (value.object.get("start_ns") != null)
        try jsonOptionalU64(value.object.get("start_ns"))
    else
        try jsonOptionalDateTimeNs(value.object.get("start"));
    const end_ns = if (value.object.get("end_ns") != null)
        try jsonOptionalU64(value.object.get("end_ns"))
    else
        try jsonOptionalDateTimeNs(value.object.get("end"));
    if (start_ns == null and end_ns == null) return error.InvalidArgument;
    return .{
        .field = field,
        .start_ns = start_ns,
        .end_ns = end_ns,
        .inclusive_start = (try jsonOptionalBoolStrict(value.object.get("inclusive_start"))) orelse true,
        .inclusive_end = (try jsonOptionalBoolStrict(value.object.get("inclusive_end"))) orelse false,
    };
}

fn parseBoolFieldQuery(value: std.json.Value) !search_mod.BoolFieldQuery {
    if (value != .object) return error.InvalidArgument;
    const field = try requiredFieldOrPath(value.object);
    const bool_value = (try jsonOptionalBoolStrict(value.object.get("value"))) orelse return error.InvalidArgument;
    return .{ .field = field, .value = bool_value };
}

fn parseTermRangeQuery(value: std.json.Value) !search_mod.TermRangeQuery {
    if (value != .object) return error.InvalidArgument;
    const field = try requiredFieldOrPath(value.object);
    const min = try jsonOptionalStringStrictNullable(value.object.get("min"));
    const max = try jsonOptionalStringStrictNullable(value.object.get("max"));
    if (min == null and max == null) return error.InvalidArgument;
    return .{
        .field = field,
        .min = min,
        .max = max,
        .inclusive_min = (try jsonOptionalBoolStrict(value.object.get("inclusive_min"))) orelse true,
        .inclusive_max = (try jsonOptionalBoolStrict(value.object.get("inclusive_max"))) orelse false,
    };
}

fn parseIpRangeQuery(value: std.json.Value) !search_mod.IPRangeQuery {
    if (value != .object) return error.InvalidArgument;
    const field = try requiredFieldOrPath(value.object);
    const cidr = jsonString(value.object.get("cidr") orelse return error.InvalidArgument) orelse return error.InvalidArgument;
    return .{ .field = field, .cidr = cidr };
}

fn parseGeoDistanceQuery(value: std.json.Value) !search_mod.GeoDistanceQuery {
    if (value != .object) return error.InvalidArgument;
    const field = try requiredFieldOrPath(value.object);
    const lon = try jsonRequiredLongitude(value.object.get("lon"));
    const lat = try jsonRequiredLatitude(value.object.get("lat"));
    const radius_meters = try jsonRequiredNonNegativeFiniteF64(value.object.get("radius_meters"));
    return .{ .field = field, .center = .{ .lon = lon, .lat = lat }, .radius_meters = radius_meters };
}

fn parseGeoBBoxQuery(value: std.json.Value) !search_mod.GeoBBoxQuery {
    if (value != .object) return error.InvalidArgument;
    const field = try requiredFieldOrPath(value.object);
    const min_lat = try jsonRequiredLatitude(value.object.get("min_lat"));
    const min_lon = try jsonRequiredLongitude(value.object.get("min_lon"));
    const max_lat = try jsonRequiredLatitude(value.object.get("max_lat"));
    const max_lon = try jsonRequiredLongitude(value.object.get("max_lon"));
    if (min_lat > max_lat) return error.InvalidArgument;
    return .{
        .field = field,
        .min_lat = min_lat,
        .min_lon = min_lon,
        .max_lat = max_lat,
        .max_lon = max_lon,
    };
}

fn requiredFieldOrPath(object: anytype) ![]const u8 {
    const field_value = object.get("field");
    const path_value = object.get("path");
    if (field_value != null and path_value != null) {
        const field = jsonString(field_value.?) orelse return error.InvalidArgument;
        const path = jsonString(path_value.?) orelse return error.InvalidArgument;
        if (!std.mem.eql(u8, field, path)) return error.InvalidArgument;
        return field;
    }
    return jsonString(field_value orelse path_value orelse return error.InvalidArgument) orelse return error.InvalidArgument;
}

fn jsonRequiredLatitude(value: ?std.json.Value) !f64 {
    const parsed = try jsonRequiredFiniteF64(value);
    if (parsed < -90.0 or parsed > 90.0) return error.InvalidArgument;
    return parsed;
}

fn jsonRequiredLongitude(value: ?std.json.Value) !f64 {
    const parsed = try jsonRequiredFiniteF64(value);
    if (parsed < -180.0 or parsed > 180.0) return error.InvalidArgument;
    return parsed;
}

fn jsonRequiredNonNegativeFiniteF64(value: ?std.json.Value) !f64 {
    const parsed = try jsonRequiredFiniteF64(value);
    if (parsed < 0) return error.InvalidArgument;
    return parsed;
}

fn jsonRequiredFiniteF64(value: ?std.json.Value) !f64 {
    const parsed = jsonOptionalF64(value) orelse return error.InvalidArgument;
    if (!std.math.isFinite(parsed)) return error.InvalidArgument;
    return parsed;
}

fn jsonString(value: std.json.Value) ?[]const u8 {
    return switch (value) {
        .string => |text| text,
        .null => null,
        else => null,
    };
}

fn jsonOptionalF64(value: ?std.json.Value) ?f64 {
    const actual = value orelse return null;
    return switch (actual) {
        .integer => |number| @floatFromInt(number),
        .float => |number| number,
        .number_string => |text| std.fmt.parseFloat(f64, text) catch null,
        .null => null,
        else => null,
    };
}

fn jsonOptionalBool(value: ?std.json.Value) ?bool {
    const actual = value orelse return null;
    return switch (actual) {
        .bool => |boolean| boolean,
        .null => null,
        else => null,
    };
}

fn jsonOptionalF64Strict(value: std.json.Value) !?f64 {
    const parsed: ?f64 = switch (value) {
        .integer => |number| @floatFromInt(number),
        .float => |number| number,
        .number_string => |text| std.fmt.parseFloat(f64, text) catch return error.InvalidArgument,
        .null => null,
        else => return error.InvalidArgument,
    };
    if (parsed) |number| {
        if (!std.math.isFinite(number)) return error.InvalidArgument;
    }
    return parsed;
}

fn jsonOptionalF64StrictNullable(value: ?std.json.Value) !?f64 {
    return try jsonOptionalF64Strict(value orelse return null);
}

fn jsonOptionalStringStrict(value: std.json.Value) !?[]const u8 {
    return switch (value) {
        .string => |text| text,
        .null => null,
        else => error.InvalidArgument,
    };
}

fn jsonOptionalStringStrictNullable(value: ?std.json.Value) !?[]const u8 {
    return try jsonOptionalStringStrict(value orelse return null);
}

fn jsonOptionalBoolStrict(value: ?std.json.Value) !?bool {
    const actual = value orelse return null;
    return switch (actual) {
        .bool => |boolean| boolean,
        .null => null,
        else => error.InvalidArgument,
    };
}

fn jsonOptionalU64(value: ?std.json.Value) !?u64 {
    const actual = value orelse return null;
    return switch (actual) {
        .integer => |number| if (number >= 0) @intCast(number) else error.InvalidArgument,
        .null => null,
        else => error.InvalidArgument,
    };
}

fn jsonOptionalDateOrNs(value: std.json.Value) !?u64 {
    return switch (value) {
        .integer => |number| if (number >= 0) @intCast(number) else error.InvalidArgument,
        .number_string => |text| std.fmt.parseInt(u64, text, 10) catch {
            return runtime_schema_mod.parseDateTimeToNs(text) orelse error.InvalidArgument;
        },
        .string => |text| runtime_schema_mod.parseDateTimeToNs(text) orelse std.fmt.parseInt(u64, text, 10) catch return error.InvalidArgument,
        .null => null,
        else => error.InvalidArgument,
    };
}

fn jsonOptionalDateTimeNs(value: ?std.json.Value) !?u64 {
    const actual = value orelse return null;
    return switch (actual) {
        .string => |text| runtime_schema_mod.parseDateTimeToNs(text) orelse error.InvalidArgument,
        .null => null,
        else => error.InvalidArgument,
    };
}

fn jsonU8(value: std.json.Value) ?u8 {
    return switch (value) {
        .integer => |number| std.math.cast(u8, number),
        .float => |number| blk: {
            if (!std.math.isFinite(number) or @round(number) != number) break :blk null;
            const parsed: i64 = @intFromFloat(number);
            break :blk std.math.cast(u8, parsed);
        },
        else => null,
    };
}

fn jsonU32(value: std.json.Value) ?u32 {
    return switch (value) {
        .integer => |number| std.math.cast(u32, number),
        .float => |number| blk: {
            if (!std.math.isFinite(number) or @round(number) != number) break :blk null;
            if (number < 0 or number > @as(f64, @floatFromInt(std.math.maxInt(u32)))) {
                break :blk null;
            }
            break :blk @intFromFloat(number);
        },
        else => null,
    };
}

fn deriveNativeDenseConstraintsAlloc(
    alloc: Allocator,
    req: types.SearchRequest,
    executor: DenseSearchExecutor,
    index_name: []const u8,
    apply_live_all_docs: bool,
) !NativeDenseConstraints {
    const bench_profile = getenv("ANTFLY_BENCH_QUERY_PROFILE") != null;
    const total_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
    var doc_constraints_ns: u64 = 0;
    var filter_doc_nums_ns: u64 = 0;
    var filter_doc_ids_ns: u64 = 0;
    var filter_intersect_ns: u64 = 0;
    var exclude_doc_nums_ns: u64 = 0;
    var exclude_doc_ids_ns: u64 = 0;
    var out = NativeDenseConstraints{};
    errdefer out.deinit(alloc);

    if (req.filter_ids.len > 0) {
        out.positive_filter = true;
        out.filter_ids = req.filter_ids;
    }

    const apply_broad_live_docs = apply_live_all_docs and
        !(try canSkipBroadLiveDenseConstraint(req, executor));
    const doc_constraints_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
    var doc_constraints = try deriveNativeDocIdConstraintsAlloc(alloc, req, .{
        .ctx = executor.ctx,
        .text_index_entry = executor.text_index_entry,
        .resolve_doc_set_doc_ids = executor.resolve_doc_set_doc_ids,
        .resolve_doc_ids_to_doc_set = executor.resolve_doc_ids_to_doc_set,
        .live_filter_doc_set = executor.live_filter_doc_set,
        .nonvisible_doc_set = executor.nonvisible_doc_set,
        .project_ordinals_to_doc_ids = false,
        .apply_live_all_docs = apply_broad_live_docs,
    });
    if (bench_profile) doc_constraints_ns = platform_time.monotonicNs() - doc_constraints_start_ns;
    defer doc_constraints.deinit(alloc);

    if (doc_constraints.positive_filter) {
        var mapped: []u64 = &.{};
        var mapped_owned = false;
        if (doc_constraints.filter_doc_nums.len > 0) {
            const phase_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
            mapped = try denseVectorIdsForDocNumsAlloc(alloc, doc_constraints.filter_doc_nums, executor, index_name);
            if (bench_profile) filter_doc_nums_ns += platform_time.monotonicNs() - phase_start_ns;
            mapped_owned = true;
        }
        if (doc_constraints.filter_doc_ids.len > 0) {
            const phase_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
            const mapped_doc_ids = try denseVectorIdsForDocIdsAlloc(alloc, doc_constraints.filter_doc_ids, executor, index_name);
            if (bench_profile) filter_doc_ids_ns += platform_time.monotonicNs() - phase_start_ns;
            if (mapped_owned) {
                const intersect_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
                const intersected = try intersectVectorIdsAlloc(alloc, mapped, mapped_doc_ids);
                if (bench_profile) filter_intersect_ns += platform_time.monotonicNs() - intersect_start_ns;
                alloc.free(mapped);
                alloc.free(mapped_doc_ids);
                mapped = intersected;
            } else {
                mapped = mapped_doc_ids;
            }
            mapped_owned = true;
        }
        if (out.positive_filter) {
            const intersect_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
            const intersected = try intersectVectorIdsAlloc(alloc, out.filter_ids, mapped);
            if (bench_profile) filter_intersect_ns += platform_time.monotonicNs() - intersect_start_ns;
            if (mapped_owned) alloc.free(mapped);
            if (out.filter_ids_owned and out.filter_ids.len > 0) alloc.free(@constCast(out.filter_ids));
            out.filter_ids = intersected;
            out.filter_ids_owned = true;
        } else {
            out.filter_ids = mapped;
            out.filter_ids_owned = mapped_owned;
            out.positive_filter = true;
        }
    }

    if (doc_constraints.exclude_doc_nums.len > 0) {
        const phase_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        const mapped_excludes = try denseVectorIdsForDocNumsAlloc(alloc, doc_constraints.exclude_doc_nums, executor, index_name);
        if (bench_profile) exclude_doc_nums_ns += platform_time.monotonicNs() - phase_start_ns;
        try mergeNativeExcludeIds(alloc, &out, mapped_excludes, req.exclude_ids);
    }
    if (doc_constraints.broad_live_exclude_doc_nums.len > 0) {
        out.broad_live_exclude_ids = try denseVectorIdsForDocNumsAlloc(
            alloc,
            doc_constraints.broad_live_exclude_doc_nums,
            executor,
            index_name,
        );
        out.broad_live_exclude_ids_owned = true;
    }
    if (doc_constraints.exclude_doc_ids.len > 0) {
        const phase_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        const mapped_excludes = try denseVectorIdsForDocIdsAlloc(alloc, doc_constraints.exclude_doc_ids, executor, index_name);
        if (bench_profile) exclude_doc_ids_ns += platform_time.monotonicNs() - phase_start_ns;
        try mergeNativeExcludeIds(alloc, &out, mapped_excludes, req.exclude_ids);
    }
    if (out.exclude_ids.len == 0 and req.exclude_ids.len > 0) {
        out.exclude_ids = req.exclude_ids;
    }
    out.resolved_stored_filters = doc_constraints.resolved_stored_filters;
    out.filter_query_json_resolved = doc_constraints.filter_query_json_resolved;
    out.exclusion_query_json_resolved = doc_constraints.exclusion_query_json_resolved;
    if (bench_profile) {
        std.log.info(
            "antfly_bench_dense_constraints total_us={d} doc_constraints_us={d} filter_doc_nums_us={d} filter_doc_ids_us={d} filter_intersect_us={d} exclude_doc_nums_us={d} exclude_doc_ids_us={d} positive_filter={} filter_doc_nums={d} filter_doc_ids={d} out_filter_ids={d} exclude_doc_nums={d} exclude_doc_ids={d} out_exclude_ids={d}",
            .{
                nsToUs(platform_time.monotonicNs() - total_start_ns),
                nsToUs(doc_constraints_ns),
                nsToUs(filter_doc_nums_ns),
                nsToUs(filter_doc_ids_ns),
                nsToUs(filter_intersect_ns),
                nsToUs(exclude_doc_nums_ns),
                nsToUs(exclude_doc_ids_ns),
                doc_constraints.positive_filter,
                doc_constraints.filter_doc_nums.len,
                doc_constraints.filter_doc_ids.len,
                out.filter_ids.len,
                doc_constraints.exclude_doc_nums.len,
                doc_constraints.exclude_doc_ids.len,
                out.exclude_ids.len,
            },
        );
    }
    return out;
}

fn canSkipBroadLiveDenseConstraint(req: types.SearchRequest, executor: DenseSearchExecutor) !bool {
    if (req.filter_query_json.len != 0 or req.exclusion_query_json.len != 0) return false;
    if (req.resolved_doc_filter != null) return false;
    if (req.filter_doc_ids.len != 0 or req.exclude_doc_ids.len != 0) return false;
    if (req.filter_ids.len != 0 or req.exclude_ids.len != 0 or req.filter_doc_ids_positive) return false;
    const visible = executor.all_docs_visible_fast orelse return false;
    return try visible(executor.ctx, req.identity_read_generation);
}

fn mergeNativeExcludeIds(
    alloc: Allocator,
    out: *NativeDenseConstraints,
    mapped_excludes: []u64,
    request_excludes: []const u64,
) !void {
    defer alloc.free(mapped_excludes);
    const base = if (out.exclude_ids.len > 0) out.exclude_ids else request_excludes;
    const merged = try unionVectorIdsAlloc(alloc, base, mapped_excludes);
    if (out.exclude_ids_owned and out.exclude_ids.len > 0) alloc.free(@constCast(out.exclude_ids));
    out.exclude_ids = merged;
    out.exclude_ids_owned = true;
}

fn collectPositiveDocIdSuperset(
    alloc: Allocator,
    filter: graph_exec.CompiledPatternFilter,
    out: *std.ArrayListUnmanaged([]const u8),
) !bool {
    return switch (filter) {
        .match_none => true,
        .doc_id => |ids| {
            try appendDocIds(alloc, out, ids);
            return true;
        },
        .conjuncts => |items| blk: {
            for (items) |item| {
                if (try collectPositiveDocIdSuperset(alloc, item, out)) break :blk true;
            }
            break :blk false;
        },
        .disjuncts => try collectExactDocIds(alloc, filter, out),
        .bool_query => |bool_query| blk: {
            for (bool_query.must) |item| {
                if (try collectPositiveDocIdSuperset(alloc, item, out)) break :blk true;
            }
            if (bool_query.must.len == 0 and bool_query.must_not.len == 0 and bool_query.should.len > 0) {
                break :blk try collectAllExactDocIds(alloc, bool_query.should, out);
            }
            break :blk false;
        },
        else => false,
    };
}

fn collectExactDocIds(
    alloc: Allocator,
    filter: graph_exec.CompiledPatternFilter,
    out: *std.ArrayListUnmanaged([]const u8),
) anyerror!bool {
    return switch (filter) {
        .match_none => true,
        .doc_id => |ids| {
            try appendDocIds(alloc, out, ids);
            return true;
        },
        .disjuncts => |items| try collectAllExactDocIds(alloc, items, out),
        else => false,
    };
}

fn collectAllExactDocIds(
    alloc: Allocator,
    items: []const graph_exec.CompiledPatternFilter,
    out: *std.ArrayListUnmanaged([]const u8),
) anyerror!bool {
    const start = out.items.len;
    for (items) |item| {
        if (!(try collectExactDocIds(alloc, item, out))) {
            out.shrinkRetainingCapacity(start);
            return false;
        }
    }
    return true;
}

fn collectBoolMustNotExactDocIds(
    alloc: Allocator,
    filter: graph_exec.CompiledPatternFilter,
    out: *std.ArrayListUnmanaged([]const u8),
) !void {
    switch (filter) {
        .bool_query => |bool_query| {
            for (bool_query.must_not) |item| {
                _ = try collectExactDocIds(alloc, item, out);
            }
            for (bool_query.must) |item| try collectBoolMustNotExactDocIds(alloc, item, out);
        },
        .conjuncts => |items| for (items) |item| try collectBoolMustNotExactDocIds(alloc, item, out),
        else => {},
    }
}

fn appendDocIds(
    alloc: Allocator,
    out: *std.ArrayListUnmanaged([]const u8),
    ids: []const []const u8,
) !void {
    for (ids) |id| {
        var exists = false;
        for (out.items) |existing| {
            if (std.mem.eql(u8, existing, id)) {
                exists = true;
                break;
            }
        }
        if (!exists) try out.append(alloc, id);
    }
}

fn denseVectorIdsForDocIdsAlloc(
    alloc: Allocator,
    doc_ids: []const []const u8,
    executor: DenseSearchExecutor,
    index_name: []const u8,
) ![]u64 {
    var out = std.ArrayListUnmanaged(u64).empty;
    errdefer out.deinit(alloc);
    for (doc_ids) |doc_id| {
        const vector_id = (try executor.lookup_vector_id(executor.ctx, index_name, doc_id)) orelse continue;
        if (!containsVectorId(out.items, vector_id)) try out.append(alloc, vector_id);
    }
    return try out.toOwnedSlice(alloc);
}

fn denseVectorIdsForDocNumsAlloc(
    alloc: Allocator,
    doc_nums: []const u32,
    executor: DenseSearchExecutor,
    index_name: []const u8,
) ![]u64 {
    if (executor.lookup_vector_ids_for_ordinals) |lookup| {
        return try lookup(executor.ctx, alloc, index_name, doc_nums);
    }
    return error.UnsupportedQueryRequest;
}

fn intersectVectorIdsAlloc(alloc: Allocator, left: []const u64, right: []const u64) ![]u64 {
    if (left.len == 0 or right.len == 0) return try alloc.alloc(u64, 0);
    var sorted_right = try alloc.dupe(u64, right);
    defer alloc.free(sorted_right);
    std.mem.sort(u64, sorted_right, {}, u64LessThan);
    const unique_right = sorted_right[0..uniqueSortedU64(sorted_right)];

    var sorted_left = try alloc.dupe(u64, left);
    defer alloc.free(sorted_left);
    std.mem.sort(u64, sorted_left, {}, u64LessThan);
    const unique_left = sorted_left[0..uniqueSortedU64(sorted_left)];

    var out = std.ArrayListUnmanaged(u64).empty;
    errdefer out.deinit(alloc);
    for (unique_left) |id| {
        if (containsSortedU64(unique_right, id)) try out.append(alloc, id);
    }
    return try out.toOwnedSlice(alloc);
}

fn unionVectorIdsAlloc(alloc: Allocator, left: []const u64, right: []const u64) ![]u64 {
    var out = try alloc.alloc(u64, left.len + right.len);
    errdefer alloc.free(out);
    @memcpy(out[0..left.len], left);
    @memcpy(out[left.len..], right);
    std.mem.sort(u64, out, {}, u64LessThan);
    const unique_len = uniqueSortedU64(out);
    return try alloc.realloc(out, unique_len);
}

fn containsVectorId(items: []const u64, id: u64) bool {
    for (items) |item| if (item == id) return true;
    return false;
}

fn u64LessThan(_: void, left: u64, right: u64) bool {
    return left < right;
}

fn uniqueSortedU64(values: []u64) usize {
    if (values.len == 0) return 0;
    var out: usize = 1;
    for (values[1..]) |value| {
        if (value == values[out - 1]) continue;
        values[out] = value;
        out += 1;
    }
    return out;
}

fn containsSortedU64(values: []const u64, expected: u64) bool {
    return std.sort.binarySearch(u64, values, expected, compareU64) != null;
}

fn compareU64(expected: u64, item: u64) std.math.Order {
    return std.math.order(expected, item);
}

pub fn shouldGroupChunkParents(req: types.SearchRequest, is_chunk_backed: bool) bool {
    return is_chunk_backed and req.return_mode != .chunk;
}

pub fn searchText(
    alloc: Allocator,
    req: types.SearchRequest,
    dispatcher: SearchTextDispatcher,
) !types.SearchResult {
    resetLastSortRejectionDiagnostic();
    return switch (req.query) {
        .match_none => try dispatcher.func(dispatcher.ctx, alloc, req, .{ .match_none = {} }),
        .match_all => try dispatcher.func(dispatcher.ctx, alloc, req, .{ .match_all = {} }),
        .phrase => |phrase| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .phrase = .{
            .field = phrase.field,
            .terms = phrase.terms,
            .max_edits = phrase.max_edits,
            .auto_fuzzy = phrase.auto_fuzzy,
            .boost = phrase.boost,
        } }),
        .multi_phrase => |phrase| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .multi_phrase = .{
            .field = phrase.field,
            .terms = phrase.terms,
            .max_edits = phrase.max_edits,
            .auto_fuzzy = phrase.auto_fuzzy,
            .boost = phrase.boost,
        } }),
        .term => |term| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .term = .{
            .field = term.field,
            .term = term.term,
            .boost = term.boost,
        } }),
        .fuzzy => |fuzzy| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .fuzzy = .{
            .field = fuzzy.field,
            .term = fuzzy.term,
            .max_edits = fuzzy.max_edits,
            .prefix_len = fuzzy.prefix_len,
            .auto_fuzzy = fuzzy.auto_fuzzy,
            .boost = fuzzy.boost,
        } }),
        .numeric_range => |range_query| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .numeric_range = .{
            .field = range_query.field,
            .min = range_query.min,
            .max = range_query.max,
            .inclusive_min = range_query.inclusive_min,
            .inclusive_max = range_query.inclusive_max,
            .boost = range_query.boost,
        } }),
        .date_range => |range_query| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .date_range = .{
            .field = range_query.field,
            .start_ns = range_query.start_ns,
            .end_ns = range_query.end_ns,
            .inclusive_start = range_query.inclusive_start,
            .inclusive_end = range_query.inclusive_end,
            .boost = range_query.boost,
        } }),
        .doc_id => |doc_id| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .doc_id = .{
            .ids = doc_id.ids,
            .boost = doc_id.boost,
        } }),
        .bool_field => |bool_field| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .bool_field = .{
            .field = bool_field.field,
            .value = bool_field.value,
            .boost = bool_field.boost,
        } }),
        .geo_distance => |geo_distance| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .geo_distance = .{
            .field = geo_distance.field,
            .lon = geo_distance.lon,
            .lat = geo_distance.lat,
            .radius_meters = geo_distance.radius_meters,
            .boost = geo_distance.boost,
        } }),
        .geo_bbox => |geo_bbox| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .geo_bbox = .{
            .field = geo_bbox.field,
            .min_lat = geo_bbox.min_lat,
            .min_lon = geo_bbox.min_lon,
            .max_lat = geo_bbox.max_lat,
            .max_lon = geo_bbox.max_lon,
            .boost = geo_bbox.boost,
        } }),
        .term_range => |range_query| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .term_range = .{
            .field = range_query.field,
            .min = range_query.min,
            .max = range_query.max,
            .inclusive_min = range_query.inclusive_min,
            .inclusive_max = range_query.inclusive_max,
            .boost = range_query.boost,
        } }),
        .ip_range => |ip_range| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .ip_range = .{
            .field = ip_range.field,
            .cidr = ip_range.cidr,
            .boost = ip_range.boost,
        } }),
        .geo_shape => |geo_shape| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .geo_shape = .{
            .field = geo_shape.field,
            .relation = geo_shape.relation,
            .polygons = geo_shape.polygons,
            .boost = geo_shape.boost,
        } }),
        .match => |match| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .match = .{
            .field = match.field,
            .text = match.text,
            .analyzer = match.analyzer,
            .boost = match.boost,
        } }),
        .match_phrase => |phrase| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .match_phrase = .{
            .field = phrase.field,
            .text = phrase.text,
            .analyzer = phrase.analyzer,
            .max_edits = phrase.max_edits,
            .auto_fuzzy = phrase.auto_fuzzy,
            .boost = phrase.boost,
        } }),
        .prefix => |prefix| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .prefix = .{
            .field = prefix.field,
            .prefix = prefix.prefix,
            .boost = prefix.boost,
        } }),
        .wildcard => |wildcard| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .wildcard = .{
            .field = wildcard.field,
            .pattern = wildcard.pattern,
            .boost = wildcard.boost,
        } }),
        .regexp => |regexp| try dispatcher.func(dispatcher.ctx, alloc, req, .{ .regexp = .{
            .field = regexp.field,
            .pattern = regexp.pattern,
            .boost = regexp.boost,
        } }),
        else => unreachable,
    };
}

fn sortAndPageTextDocValueFilterAlloc(
    alloc: Allocator,
    req: types.SearchRequest,
    snapshot: *const index_mod.IndexSnapshot,
    filter: query_mod.Filter,
    executor: SearchTextQueryExecutor,
    plan: SortExecutionPlan,
) !types.SearchResult {
    const doc_nums = try snapshot.executeFilter(alloc, filter);
    defer alloc.free(doc_nums);
    return try sortAndPageTextDocValueDocNumsAlloc(alloc, req, snapshot, doc_nums, executor, plan);
}

fn sortAndPageTextDocValueDocNumsAlloc(
    alloc: Allocator,
    req: types.SearchRequest,
    snapshot: *const index_mod.IndexSnapshot,
    doc_nums: []const u32,
    executor: SearchTextQueryExecutor,
    plan: SortExecutionPlan,
) !types.SearchResult {
    var effective = try effectiveSortRequestAlloc(alloc, req);
    defer effective.deinit(alloc);
    const effective_req = effective.req;

    try validateSortPageOptions(effective_req);
    if (effective_req.order_by.len == 0) return error.InvalidQueryRequest;
    try validateSortExecutionPlanForRuntime(effective_req, plan, .{
        .require_native = plan.require_native,
        .load = loadTextDocValueSortValue,
    });
    try checkSearchRequestDeadline(effective_req);

    const bench_query_profile = shouldLogBenchQueryProfile();
    const collect_sort_profile = bench_query_profile or effective_req.profile;
    if (effective_req.limit == 0) {
        const zero_start_ns = if (collect_sort_profile) platform_time.monotonicNs() else 0;
        var profile = SortCollectorProfile{};
        observeSortCandidateSource(if (collect_sort_profile) &profile else null, "text_postings");
        const visible_total = if (activeSortCursor(effective_req).len > 0)
            try visibleTextDocNumCountAfterCursorAlloc(
                alloc,
                effective_req,
                snapshot,
                doc_nums,
                executor,
                plan,
                if (collect_sort_profile) &profile else null,
            )
        else
            try visibleTextDocNumCount(alloc, effective_req, snapshot, doc_nums, executor);
        if (collect_sort_profile and activeSortCursor(effective_req).len == 0) {
            profile.candidate_count = @intCast(@min(visible_total, @as(usize, std.math.maxInt(u64))));
        }
        if (collect_sort_profile) {
            profile.window_capacity = 0;
            profile.window_len = 0;
            profile.total_ns = platform_time.monotonicNs() - zero_start_ns;
        }
        if (bench_query_profile) {
            logBenchSortCollectorProfile(effective_req, plan, true, profile);
        }
        return .{
            .alloc = alloc,
            .hits = &.{},
            .total_hits = boundedU32(visible_total),
            .total_hits_relation = if (visible_total > std.math.maxInt(u32)) .gte else .exact,
            .sort_profile = if (collect_sort_profile) sortResultProfile(effective_req, plan, true, profile) else null,
            .graph_results = &.{},
        };
    }

    const exact_candidate_budget = lateVisibilityExactCandidateBudget();
    const candidate_count = boundedU32(doc_nums.len);
    enforceLateVisibilityExactCandidateBudget(candidate_count, exact_candidate_budget) catch |err| {
        logExactSortBudgetRejection(
            "text",
            .text_field_sort_candidate_window,
            effective_req.index_name,
            candidate_count,
            exact_candidate_budget,
            plan,
        );
        return err;
    };

    const sort_start_ns = if (collect_sort_profile) platform_time.monotonicNs() else 0;
    var profile = SortCollectorProfile{};
    observeSortCandidateSource(if (collect_sort_profile) &profile else null, "text_postings");
    const window_capacity = sortWindowCapacity(effective_req);
    if (collect_sort_profile) profile.window_capacity = window_capacity;
    const keep_previous_page = effective_req.search_before.len > 0;
    var window: []DecoratedSortHit = if (window_capacity > 0)
        try alloc.alloc(DecoratedSortHit, window_capacity)
    else
        &.{};
    var window_len: usize = 0;
    var window_drained_prefix: usize = 0;
    errdefer {
        for (window[window_drained_prefix..window_len]) |*item| item.deinit(alloc);
        if (window.len > 0) alloc.free(window);
    }

    const native_sort_ctx = TextDocValueSortContext{ .snapshot = snapshot };
    const native_loader = NativeSortValueLoader{
        .ctx = @constCast(&native_sort_ctx),
        .require_native = plan.require_native,
        .load = loadTextDocValueSortValue,
    };
    var visible_candidate_count: usize = 0;
    for (doc_nums, 0..) |doc_num, i| {
        if (i % 1024 == 0) try checkSearchRequestDeadline(effective_req);
        const stored = (try snapshot.storedDoc(doc_num)) orelse return error.StoredDocMissing;
        if (executor.is_expired_key) |is_expired| {
            if (try is_expired(executor.ctx, alloc, stored.id)) continue;
        }
        visible_candidate_count += 1;
        if (collect_sort_profile) profile.candidate_count += 1;
        const raw_hit = types.SearchHit{
            .id = try alloc.dupe(u8, stored.id),
            .doc_ordinal = try snapshot.docOrdinal(doc_num),
            .native_text_doc_id = doc_num,
            .score = 1.0,
            .stored_data = null,
        };
        const decorate_start_ns = if (collect_sort_profile) platform_time.monotonicNs() else 0;
        var decorated = try decorateSortHitAlloc(
            alloc,
            effective_req,
            plan,
            raw_hit,
            executor.ctx,
            executor.load_stored,
            native_loader,
            if (collect_sort_profile) &profile else null,
        );
        var decorated_owned = true;
        errdefer if (decorated_owned) decorated.deinit(alloc);
        if (collect_sort_profile) profile.decorate_ns += platform_time.monotonicNs() - decorate_start_ns;

        const allowed_by_cursor = try decoratedHitAllowedByCursor(effective_req, plan, decorated);
        admitDecoratedSortHitIntoWindow(
            alloc,
            effective_req,
            window,
            &window_len,
            keep_previous_page,
            if (collect_sort_profile) &profile else null,
            decorated,
            allowed_by_cursor,
        );
        decorated_owned = false;
    }

    try checkSearchRequestDeadline(effective_req);
    const final_sort_start_ns = if (collect_sort_profile) platform_time.monotonicNs() else 0;
    std.sort.pdq(DecoratedSortHit, window[0..window_len], effective_req, decoratedLessThan);
    if (collect_sort_profile) profile.final_sort_ns = platform_time.monotonicNs() - final_sort_start_ns;
    try checkSearchRequestDeadline(effective_req);

    var start: usize = 0;
    var end: usize = window_len;
    if (effective_req.search_after.len == 0 and effective_req.search_before.len == 0) {
        start = @min(@as(usize, @intCast(effective_req.offset)), window_len);
        end = @min(start + @as(usize, @intCast(effective_req.limit)), window_len);
    }

    const selected = try alloc.alloc(types.SearchHit, end - start);
    var selected_initialized: usize = 0;
    errdefer {
        for (selected[0..selected_initialized]) |*hit| hit.deinit(alloc);
        if (selected.len > 0) alloc.free(selected);
    }
    for (window[0..window_len], 0..) |*item, i| {
        if (i % 1024 == 0) try checkSearchRequestDeadline(effective_req);
        if (i >= start and i < end) {
            selected[selected_initialized] = item.hit;
            item.hit = undefined;
            selected_initialized += 1;
            if (collect_sort_profile) profile.selected_count += 1;
        } else {
            item.hit.deinit(alloc);
        }
        freeSortValues(alloc, item.keys);
        window_drained_prefix = i + 1;
    }
    if (window.len > 0) alloc.free(window);
    if (collect_sort_profile) {
        profile.window_len = window_len;
        profile.total_ns = platform_time.monotonicNs() - sort_start_ns;
    }
    if (bench_query_profile) {
        logBenchSortCollectorProfile(effective_req, plan, true, profile);
    }

    var out = types.SearchResult{
        .alloc = alloc,
        .hits = selected,
        .total_hits = boundedU32(visible_candidate_count),
        .total_hits_relation = if (visible_candidate_count > std.math.maxInt(u32)) .gte else .exact,
        .sort_profile = if (collect_sort_profile) sortResultProfile(effective_req, plan, true, profile) else null,
        .graph_results = &.{},
    };
    errdefer out.deinit();

    if (effective_req.include_stored) {
        const source_profile = try loadMissingProjectedTextHitDocuments(alloc, effective_req, executor, out.hits);
        applyProjectedSourceLoadProfileToSortProfile(&out, source_profile);
        logBenchProjectedSourceLoadProfile(effective_req, plan, "text", source_profile);
    }
    return out;
}

fn visibleTextDocNumCountAfterCursorAlloc(
    alloc: Allocator,
    req: types.SearchRequest,
    snapshot: *const index_mod.IndexSnapshot,
    doc_nums: []const u32,
    executor: SearchTextQueryExecutor,
    plan: SortExecutionPlan,
    profile: ?*SortCollectorProfile,
) !usize {
    var native_sort_ctx = TextDocValueSortContext{ .snapshot = snapshot };
    const native_loader = NativeSortValueLoader{
        .ctx = &native_sort_ctx,
        .require_native = plan.require_native,
        .load = loadTextDocValueSortValue,
    };

    var visible_count: usize = 0;
    for (doc_nums, 0..) |doc_num, i| {
        if (i % 1024 == 0) try checkSearchRequestDeadline(req);
        const stored = (try snapshot.storedDoc(doc_num)) orelse return error.StoredDocMissing;
        if (executor.is_expired_key) |is_expired| {
            if (try is_expired(executor.ctx, alloc, stored.id)) continue;
        }
        if (profile) |p| p.candidate_count += 1;
        const raw_hit = types.SearchHit{
            .id = try alloc.dupe(u8, stored.id),
            .doc_ordinal = try snapshot.docOrdinal(doc_num),
            .native_text_doc_id = doc_num,
            .score = 1.0,
            .stored_data = null,
        };
        const decorate_start_ns = if (profile != null) platform_time.monotonicNs() else 0;
        var decorated = try decorateSortHitAlloc(
            alloc,
            req,
            plan,
            raw_hit,
            executor.ctx,
            executor.load_stored,
            native_loader,
            profile,
        );
        defer decorated.deinit(alloc);
        if (profile) |p| p.decorate_ns += platform_time.monotonicNs() - decorate_start_ns;

        if (try decoratedHitAllowedByCursor(req, plan, decorated)) {
            visible_count += 1;
        } else if (profile) |p| {
            p.cursor_rejected_count += 1;
        }
    }
    return visible_count;
}

fn visibleTextDocNumCount(
    alloc: Allocator,
    req: types.SearchRequest,
    snapshot: *const index_mod.IndexSnapshot,
    doc_nums: []const u32,
    executor: SearchTextQueryExecutor,
) !usize {
    if (executor.is_expired_key == null) return doc_nums.len;

    var visible_count: usize = 0;
    for (doc_nums, 0..) |doc_num, i| {
        if (i % 1024 == 0) try checkSearchRequestDeadline(req);
        const stored = (try snapshot.storedDoc(doc_num)) orelse return error.StoredDocMissing;
        if (try executor.is_expired_key.?(executor.ctx, alloc, stored.id)) continue;
        visible_count += 1;
    }
    return visible_count;
}

pub fn searchTextQuery(
    alloc: Allocator,
    req: types.SearchRequest,
    text_query: types.TextQuery,
    executor: SearchTextQueryExecutor,
) !types.SearchResult {
    resetLastSortRejectionDiagnostic();
    try checkSearchRequestDeadline(req);
    var effective_sort_request = if (requestHasSortPageOptions(req))
        try effectiveSortRequestAlloc(alloc, req)
    else
        EffectiveSortRequest{ .req = req };
    defer effective_sort_request.deinit(alloc);
    var effective_req = effective_sort_request.req;

    const bench_query_profile = shouldLogBenchQueryProfile();
    const collect_sort_profile = bench_query_profile or effective_req.profile;
    const collect_score_profile = collect_sort_profile and textQueryIsScoreBearing(text_query);
    const collect_score_timing = bench_query_profile or collect_score_profile;
    const total_start_ns = if (bench_query_profile or collect_score_profile) platform_time.monotonicNs() else 0;
    const text_entry = (try executor.text_index_entry(executor.ctx, effective_req.index_name)) orelse return switch (text_query) {
        .match_all => executor.search_match_all(executor.ctx, alloc, effective_req),
        else => error.IndexNotFound,
    };
    text_entry.lockAnalysisShared();
    defer text_entry.unlockAnalysisShared();
    if (effective_req.index_name == null) effective_req.index_name = text_entry.config.name;
    const text_index = &text_entry.persistent;
    const chunk_backed = try executor.text_index_is_chunk_backed(executor.ctx, alloc, effective_req.index_name);
    const group_chunk_parents = shouldGroupChunkParents(effective_req, chunk_backed);
    const paging = componentPaging(effective_req);
    effective_req.full_text = text_query;

    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const arena_alloc = arena.allocator();
    const base_search_query = try textQueryToSearchQuery(arena_alloc, text_query, text_entry.text_analysis, text_entry.runtime_schema);
    // Full-text projection publishes replacement snapshots independently of
    // query execution. Pin this generation for the entire request: a borrowed
    // snapshot can otherwise reach refcount zero while a concurrent write is
    // still scoring it (observed as allocator corruption in termDocFreq()).
    const snapshot = text_index.acquireSnapshot();
    defer snapshot.release();
    const can_apply_live_all_docs = !chunk_backed or (try snapshot.hasDocOrdinalCoverage());
    const constraints_start_ns = if (bench_query_profile) platform_time.monotonicNs() else 0;
    var constraint_req = effective_req;
    constraint_req.resolved_doc_filter = null;
    constraint_req.full_text = null;
    var native_constraints = try deriveNativeDocIdConstraintsAlloc(alloc, constraint_req, .{
        .ctx = executor.ctx,
        .text_index_entry = executor.text_index_entry,
        .resolve_doc_set_doc_ids = executor.resolve_doc_set_doc_ids,
        .resolve_doc_ids_to_doc_set = executor.resolve_doc_ids_to_doc_set,
        .live_filter_doc_set = executor.live_filter_doc_set,
        .nonvisible_doc_set = executor.nonvisible_doc_set,
        .project_ordinals_to_doc_ids = false,
        .text_snapshot_for_doc_num_projection = snapshot,
        .apply_live_all_docs = can_apply_live_all_docs,
    });
    defer native_constraints.deinit(alloc);
    const derive_constraints_ns = if (bench_query_profile) platform_time.monotonicNs() - constraints_start_ns else 0;

    const resolved_filter_start_ns = if (bench_query_profile) platform_time.monotonicNs() else 0;
    if (resolvedTextDocNumFilterFromRequest(effective_req)) |filter| {
        try applyResolvedTextDocNumFilterAlloc(alloc, &native_constraints, filter);
    } else if (resolvedDocFilterFromRequest(effective_req)) |filter| {
        try applyResolvedDocFilterToTextDocNumsAlloc(alloc, snapshot, &native_constraints, filter, .{
            .ctx = executor.ctx,
            .text_index_entry = executor.text_index_entry,
            .resolve_doc_set_doc_ids = executor.resolve_doc_set_doc_ids,
            .resolve_doc_ids_to_doc_set = executor.resolve_doc_ids_to_doc_set,
            .live_filter_doc_set = executor.live_filter_doc_set,
            .nonvisible_doc_set = executor.nonvisible_doc_set,
            .project_ordinals_to_doc_ids = false,
            .identity_read_generation = effective_req.identity_read_generation,
        });
    }
    const resolved_filter_ns = if (bench_query_profile) platform_time.monotonicNs() - resolved_filter_start_ns else 0;
    const convert_start_ns = if (bench_query_profile) platform_time.monotonicNs() else 0;
    try convertNativeDocIdsToTextDocNumsAlloc(alloc, effective_req, snapshot, &native_constraints);
    try normalizeNativeDocNumConstraintsAlloc(alloc, &native_constraints);
    const convert_constraints_ns = if (bench_query_profile) platform_time.monotonicNs() - convert_start_ns else 0;
    const unresolved_stored_filters =
        (effective_req.filter_query_json.len > 0 and !native_constraints.filter_query_json_resolved) or
        (effective_req.exclusion_query_json.len > 0 and !native_constraints.exclusion_query_json_resolved);
    try rejectSortedQueryWithUnresolvedStoredFilters(
        effective_req,
        native_constraints.filter_query_json_resolved,
        native_constraints.exclusion_query_json_resolved,
    );

    if (native_constraints.positive_filter and native_constraints.filter_doc_ids.len == 0 and native_constraints.filter_doc_nums.len == 0) {
        const score_profile = if (collect_score_profile) sortResultProfile(effective_req, .{
            .kind = .score_top_k,
        }, false, .{
            .candidate_source = "native_filter",
            .window_capacity = @intCast(paging.limit),
            .window_len = 0,
            .total_ns = platform_time.monotonicNs() - total_start_ns,
        }) else null;
        return executor.postprocess(executor.ctx, alloc, effective_req, .{
            .alloc = alloc,
            .hits = &.{},
            .total_hits = 0,
            .sort_profile = score_profile,
            .graph_results = &.{},
        }, chunk_backed);
    }
    const late_visibility_paginate = try searchTextNeedsLateVisibilityFilter(
        executor,
        can_apply_live_all_docs,
        native_constraints.positive_filter,
        effective_req.identity_read_generation,
    );
    const full_candidate_limit = effectiveTextCandidateLimit(snapshot.liveDocCount(), native_constraints);
    const requires_field_sort = effective_req.order_by.len > 0;
    const search_query = try textSearchQueryWithNativeDocIdsAlloc(arena_alloc, base_search_query, native_constraints, effective_req.count_only);
    // The primary document store is the source of truth. Production text
    // segments retain compact keys for hit identity, but no longer duplicate
    // source bodies merely to project a result page.
    const load_stored_in_search_engine = false;
    var field_sort_plan = SortExecutionPlan{ .kind = .none };
    if (requires_field_sort) field_sort_plan = try planTextNativeSortFields(effective_req, snapshot, text_entry.runtime_schema);
    if (requires_field_sort and
        field_sort_plan.sorted_segment_executor_available and
        !chunk_backed and
        !group_chunk_parents and
        !late_visibility_paginate and
        !unresolved_stored_filters and
        !effective_req.count_only and
        !requestHasPostprocessPageTransforms(effective_req) and
        effective_req.aggregations_json.len == 0 and
        effective_req.graph_queries.len == 0 and
        effective_req.full_text_queries.len == 0)
    {
        const sorted_membership_query = try textSearchQueryWithNativeDocIdsAlloc(arena_alloc, base_search_query, native_constraints, true);
        const membership_filter = search_mod.searchQueryToFilterArena(arena_alloc, sorted_membership_query) catch |err| switch (err) {
            error.InvalidArgument => null,
            else => return err,
        };
        if (membership_filter) |filter| {
            var membership = try buildSortedSegmentDocMembershipAlloc(alloc, snapshot, filter);
            defer membership.deinit(alloc);

            const cost_decision = sortedSegmentSelectiveCandidateDocValuesDecision(effective_req, membership.candidate_count, snapshot);
            if (cost_decision.prefer_doc_values) {
                const doc_nums = try sortedSegmentDocMembershipDocNumsAlloc(alloc, snapshot, &membership);
                defer alloc.free(doc_nums);
                var doc_values_plan = docValuesCollectorPlanForSelectiveFilter(field_sort_plan);
                applySortCostModelDecision(&doc_values_plan, cost_decision);
                return try sortAndPageTextDocValueDocNumsAlloc(
                    alloc,
                    effective_req,
                    snapshot,
                    doc_nums,
                    executor,
                    doc_values_plan,
                );
            }

            var sorted_plan = field_sort_plan;
            applySortCostModelDecision(&sorted_plan, cost_decision);
            sorted_plan.kind = .sorted_segment_seek;
            sorted_plan.exactness = .bounded_exact;
            sorted_plan.source = .sorted_segment_scan;
            sorted_plan.cursor_support = .segment_seek;
            sorted_plan.source_load = .projected_source_after_page;
            sorted_plan.distributed_behavior = .shard_local_only;

            var sorted_req = effective_req;
            sorted_req.include_stored = false;
            const native_sort_ctx = TextDocValueSortContext{ .snapshot = snapshot };
            const native_sort_loader = NativeSortValueLoader{
                .ctx = @constCast(&native_sort_ctx),
                .require_native = true,
                .load = loadTextDocValueSortValue,
            };
            const sorted_executor = MatchAllExecutor{
                .ctx = executor.ctx,
                .collect_candidates = undefined,
                .text_index_entry = undefined,
                .load_projected_document = undefined,
                .load_stored = executor.load_stored,
                .is_expired_key = executor.is_expired_key,
            };
            const empty_constraints = NativeDocIdConstraints{};
            var out = try sortAndPageMatchAllSortedSegmentsAlloc(
                alloc,
                sorted_req,
                sorted_executor,
                &empty_constraints,
                text_entry,
                sorted_plan,
                native_sort_loader,
                &membership,
            );
            errdefer out.deinit();
            if (effective_req.include_stored) {
                const source_profile = try loadMissingProjectedTextHitDocuments(alloc, effective_req, executor, out.hits);
                applyProjectedSourceLoadProfileToSortProfile(&out, source_profile);
                logBenchProjectedSourceLoadProfile(effective_req, sorted_plan, "text", source_profile);
            }
            return out;
        }
    }
    if (requires_field_sort and
        field_sort_plan.kind == .native_doc_values_top_n and
        !requestHasScoreSort(effective_req) and
        !chunk_backed and
        !group_chunk_parents and
        !late_visibility_paginate and
        !unresolved_stored_filters and
        !effective_req.count_only and
        !requestHasPostprocessPageTransforms(effective_req) and
        effective_req.aggregations_json.len == 0 and
        effective_req.graph_queries.len == 0 and
        effective_req.full_text_queries.len == 0)
    {
        const doc_value_filter_query = try textSearchQueryWithNativeDocIdsAlloc(arena_alloc, base_search_query, native_constraints, true);
        const doc_value_filter = search_mod.searchQueryToFilterArena(arena_alloc, doc_value_filter_query) catch |err| switch (err) {
            error.InvalidArgument => null,
            else => return err,
        };
        if (doc_value_filter) |filter| {
            return try sortAndPageTextDocValueFilterAlloc(
                alloc,
                effective_req,
                snapshot,
                filter,
                executor,
                field_sort_plan,
            );
        }
    }
    const exact_late_visibility_totals = late_visibility_paginate and
        (effective_req.count_only or
            effective_req.limit == 0 or
            effective_req.aggregations_json.len != 0 or
            effective_req.graph_queries.len != 0);
    const exact_candidate_budget = lateVisibilityExactCandidateBudget();
    if (exact_late_visibility_totals) {
        enforceLateVisibilityExactCandidateBudget(full_candidate_limit, exact_candidate_budget) catch |err| {
            logExactSortBudgetRejection(
                "text",
                .text_exact_late_visibility_totals,
                effective_req.index_name,
                full_candidate_limit,
                exact_candidate_budget,
                if (requires_field_sort) field_sort_plan else null,
            );
            return err;
        };
    }
    const adaptive_late_visibility = late_visibility_paginate and !exact_late_visibility_totals;
    const requested_visible_end = effective_req.offset +| effective_req.limit;
    const collect_window_candidates = group_chunk_parents or late_visibility_paginate or requires_field_sort;
    const grouped_requires_full_window = group_chunk_parents and
        (effective_req.count_only or
            effective_req.limit == 0 or
            effective_req.aggregations_json.len != 0 or
            effective_req.graph_queries.len != 0);
    const candidate_ceiling = if (group_chunk_parents)
        @min(full_candidate_limit, groupedCandidateBudget())
    else
        full_candidate_limit;
    var candidate_limit: u32 = if (collect_window_candidates)
        if (requires_field_sort)
            @min(candidate_ceiling, exact_candidate_budget)
        else if (grouped_requires_full_window)
            candidate_ceiling
        else if (group_chunk_parents)
            initialAdaptiveCandidateWindow(candidate_ceiling, paging)
        else if (adaptive_late_visibility)
            @min(candidate_ceiling, @max(@as(u32, 1), @max(paging.limit, requested_visible_end)))
        else
            candidate_ceiling
    else
        paging.limit;
    var candidate_iterations: u32 = 0;
    var execute_ns: u64 = 0;
    var hits_ns: u64 = 0;
    var postprocess_ns: u64 = 0;

    while (true) {
        try checkSearchRequestDeadline(effective_req);
        candidate_iterations += 1;
        var postprocess_req = effective_req;
        if (late_visibility_paginate or requires_field_sort or group_chunk_parents) {
            postprocess_req.offset = 0;
            postprocess_req.limit = candidate_limit;
        }
        // Explicit document-ID constraints have already been resolved against
        // this exact text snapshot and enforced by its native collector. Do
        // not apply them a second time to derived artifact hit IDs in the
        // stored-pattern layer, where source and artifact IDs intentionally
        // use different representations of the same document.
        postprocess_req.filter_doc_ids = &.{};
        postprocess_req.filter_doc_ids_positive = false;
        postprocess_req.exclude_doc_ids = &.{};

        const execute_start_ns = if (collect_score_timing) platform_time.monotonicNs() else 0;
        var result = if (effective_req.count_only)
            try search_mod.executeCountCandidates(alloc, snapshot, search_query)
        else
            try search_mod.execute(alloc, snapshot, .{
                .query = search_query,
                .k = if (collect_window_candidates) candidate_limit else paging.limit,
                .offset = if (collect_window_candidates) 0 else paging.offset,
                .include_stored = load_stored_in_search_engine,
                .distributed_text_stats = effective_req.distributed_text_stats,
                .filter_doc_nums = native_constraints.filter_doc_nums,
                .filter_doc_nums_positive = native_constraints.positive_filter,
                .exclude_doc_nums = native_constraints.exclude_doc_nums,
            });
        defer result.deinit();
        if (collect_score_timing) execute_ns += platform_time.monotonicNs() - execute_start_ns;

        const candidates_exhausted = !collect_window_candidates or
            candidate_limit >= full_candidate_limit or
            (result.total_hits_relation == .exact and result.total_hits <= candidate_limit);
        const candidate_ceiling_reached = candidate_limit >= candidate_ceiling;
        const candidate_tail_score: ?f32 = if (result.hits.len > 0)
            result.hits[result.hits.len - 1].score
        else
            null;

        const hits_start_ns = if (collect_score_timing) platform_time.monotonicNs() else 0;
        var hits = try alloc.alloc(types.SearchHit, result.hits.len);
        var initialized: usize = 0;
        var owns_hits = true;
        errdefer {
            if (owns_hits) {
                for (hits[0..initialized]) |*hit| hit.deinit(alloc);
                alloc.free(hits);
            }
        }

        for (result.hits, 0..) |hit, i| {
            if (i % 1024 == 0) try checkSearchRequestDeadline(effective_req);
            const doc_ordinal = try snapshot.docOrdinal(hit.doc_id);
            const id = hit.id orelse {
                const stored = (try snapshot.storedDoc(hit.doc_id)) orelse return error.StoredDocMissing;
                var materialized = types.SearchHit{
                    .id = try alloc.dupe(u8, stored.id),
                    .doc_ordinal = doc_ordinal,
                    .native_text_doc_id = hit.doc_id,
                    .score = hit.score,
                    .stored_data = null,
                };
                var assigned = false;
                errdefer if (!assigned) materialized.deinit(alloc);
                materialized.index_scores = try types.cloneIndexScores(alloc, hit.index_scores);
                hits[i] = materialized;
                assigned = true;
                initialized += 1;
                continue;
            };

            var materialized = types.SearchHit{
                .id = try alloc.dupe(u8, id),
                .doc_ordinal = doc_ordinal,
                .native_text_doc_id = hit.doc_id,
                .score = hit.score,
                .stored_data = null,
            };
            var assigned = false;
            errdefer if (!assigned) materialized.deinit(alloc);
            materialized.index_scores = try types.cloneIndexScores(alloc, hit.index_scores);
            materialized.stored_data = if (load_stored_in_search_engine and hit.stored_data != null)
                try executor.project_stored_search(executor.ctx, alloc, effective_req, id, hit.stored_data.?)
            else
                null;
            hits[i] = materialized;
            assigned = true;
            initialized += 1;
        }
        if (collect_score_timing) hits_ns += platform_time.monotonicNs() - hits_start_ns;

        owns_hits = false;
        const postprocess_start_ns = if (collect_score_timing) platform_time.monotonicNs() else 0;
        const exhaustive_candidate_window = candidate_limit >= full_candidate_limit and
            result.hits.len == @as(usize, result.total_hits);
        var out = try executor.postprocess(executor.ctx, alloc, postprocess_req, .{
            .alloc = alloc,
            .hits = hits,
            .total_hits = result.total_hits,
            // The scorer may conservatively label a top-k count as `gte`.
            // When k covers the complete candidate upper bound and every
            // reported match was returned, the query layer has a stronger
            // exactness proof. Limited pages keep the scorer's relation.
            .total_hits_relation = if (exhaustive_candidate_window) .exact else switch (result.total_hits_relation) {
                .exact => .exact,
                .gte => .gte,
            },
            .graph_results = &.{},
        }, chunk_backed);
        errdefer out.deinit();
        if (collect_score_timing) postprocess_ns += platform_time.monotonicNs() - postprocess_start_ns;

        const visible_candidate_count: u32 = @intCast(@min(out.hits.len, @as(usize, std.math.maxInt(u32))));
        const grouped_page_is_stable = group_chunk_parents and groupedResultHasStableRequestedPage(
            paging,
            out,
            candidate_tail_score,
            candidates_exhausted,
        );
        if (group_chunk_parents and
            !grouped_requires_full_window and
            !candidates_exhausted and
            !candidate_ceiling_reached and
            !grouped_page_is_stable)
        {
            out.deinit();
            const grown_limit = growAdaptiveCandidateWindow(candidate_limit, candidate_ceiling, requested_visible_end);
            if (grown_limit == candidate_limit) return error.InvalidQueryRequest;
            candidate_limit = grown_limit;
            continue;
        }
        if (group_chunk_parents and !grouped_requires_full_window) {
            try enforceGroupedPageBoundaryAtCandidateCeiling(
                paging,
                out,
                candidate_tail_score,
                candidates_exhausted,
                candidate_ceiling_reached,
            );
        }
        if (adaptive_late_visibility and !candidates_exhausted and !candidate_ceiling_reached and visible_candidate_count < requested_visible_end) {
            out.deinit();
            const grown_limit = growAdaptiveCandidateWindow(candidate_limit, candidate_ceiling, requested_visible_end);
            if (grown_limit == candidate_limit) return error.InvalidQueryRequest;
            candidate_limit = grown_limit;
            continue;
        }
        if ((adaptive_late_visibility or group_chunk_parents) and !candidates_exhausted) {
            out.total_hits = visible_candidate_count;
            out.total_hits_relation = .gte;
        }
        if (requires_field_sort and !candidates_exhausted) {
            logExactSortBudgetRejection(
                "text",
                .text_field_sort_candidate_window,
                effective_req.index_name,
                result.total_hits,
                candidate_limit,
                field_sort_plan,
            );
            return error.QueryCandidateBudgetExceeded;
        }
        try checkSearchRequestDeadline(effective_req);
        if (requires_field_sort) {
            if (field_sort_plan.kind == .native_doc_values_top_n) {
                const native_sort_ctx = TextDocValueSortContext{ .snapshot = snapshot };
                try sortAndPageSearchResultInPlace(&out, effective_req, executor.ctx, executor.load_stored, field_sort_plan, .{
                    .ctx = @constCast(&native_sort_ctx),
                    .require_native = field_sort_plan.require_native,
                    .load = loadTextDocValueSortValue,
                });
            } else {
                try sortAndPageSearchResultInPlace(&out, effective_req, executor.ctx, executor.load_stored, field_sort_plan, null);
            }
        } else if ((late_visibility_paginate or group_chunk_parents) and !effective_req.count_only) {
            try paginateSearchResultInPlace(&out, effective_req.offset, effective_req.limit);
        }
        if (!requires_field_sort and !effective_req.count_only and collect_score_profile) {
            out.sort_profile = sortResultProfile(effective_req, .{ .kind = .score_top_k }, false, .{
                .candidate_source = "text_postings",
                .candidate_count = @intCast(result.hits.len),
                .admitted_count = @intCast(result.hits.len),
                .selected_count = @intCast(out.hits.len),
                .window_capacity = @intCast(paging.limit),
                .window_len = out.hits.len,
                .total_ns = execute_ns + hits_ns + postprocess_ns,
            });
        }
        if (effective_req.include_stored and !chunk_backed) {
            const source_profile = try loadMissingProjectedTextHitDocuments(alloc, effective_req, executor, out.hits);
            applyProjectedSourceLoadProfileToSortProfile(&out, source_profile);
            logBenchProjectedSourceLoadProfile(effective_req, if (requires_field_sort) field_sort_plan else .{ .kind = .score_top_k }, "text", source_profile);
        }
        if (bench_query_profile) {
            std.log.info(
                "antfly_bench_text_query index={s} total_us={d} derive_constraints_us={d} apply_resolved_us={d} convert_constraints_us={d} execute_us={d} hits_us={d} postprocess_us={d} positive_filter={} filter_doc_nums={d} filter_doc_ids={d} exclude_doc_nums={d} exclude_doc_ids={d} snapshot_docs={d} candidate_window={d} candidate_iterations={d} late_visibility={} hits={d} total_hits={d}",
                .{
                    effective_req.index_name orelse "",
                    nsToUs(platform_time.monotonicNs() - total_start_ns),
                    nsToUs(derive_constraints_ns),
                    nsToUs(resolved_filter_ns),
                    nsToUs(convert_constraints_ns),
                    nsToUs(execute_ns),
                    nsToUs(hits_ns),
                    nsToUs(postprocess_ns),
                    native_constraints.positive_filter,
                    native_constraints.filter_doc_nums.len,
                    native_constraints.filter_doc_ids.len,
                    native_constraints.exclude_doc_nums.len,
                    native_constraints.exclude_doc_ids.len,
                    snapshot.liveDocCount(),
                    candidate_limit,
                    candidate_iterations,
                    late_visibility_paginate,
                    out.hits.len,
                    out.total_hits,
                },
            );
        }
        return out;
    }
}

fn textSearchQueryWithNativeDocIdsAlloc(
    alloc: Allocator,
    base: search_mod.SearchQuery,
    constraints: NativeDocIdConstraints,
    include_doc_nums: bool,
) !search_mod.SearchQuery {
    const has_include_doc_ids = constraints.positive_filter and constraints.filter_doc_ids.len > 0;
    const has_include_doc_nums = include_doc_nums and constraints.positive_filter and constraints.filter_doc_nums.len > 0;
    const has_exclude_doc_ids = constraints.exclude_doc_ids.len > 0;
    const has_exclude_doc_nums = include_doc_nums and constraints.exclude_doc_nums.len > 0;
    const has_native_doc_nums = !include_doc_nums and
        ((constraints.positive_filter and constraints.filter_doc_nums.len > 0) or constraints.exclude_doc_nums.len > 0);
    const has_include = has_include_doc_ids or has_include_doc_nums;
    const has_exclude = has_exclude_doc_ids or has_exclude_doc_nums;
    if (!has_include and !has_exclude and !has_native_doc_nums) return base;

    const must_len: usize = 1 +
        @as(usize, if (has_include_doc_ids) 1 else 0) +
        @as(usize, if (has_include_doc_nums) 1 else 0);
    const must = try alloc.alloc(search_mod.SearchQuery, must_len);
    must[0] = base;
    var must_i: usize = 1;
    if (has_include_doc_ids) {
        must[must_i] = .{ .doc_id = .{ .ids = constraints.filter_doc_ids } };
        must_i += 1;
    }
    if (has_include_doc_nums) {
        must[must_i] = .{ .doc_num = .{ .ids = constraints.filter_doc_nums } };
        must_i += 1;
    }

    const must_not = if (has_exclude) blk: {
        const items_len: usize =
            @as(usize, if (has_exclude_doc_ids) 1 else 0) +
            @as(usize, if (has_exclude_doc_nums) 1 else 0);
        const items = try alloc.alloc(search_mod.SearchQuery, items_len);
        var i: usize = 0;
        if (has_exclude_doc_ids) {
            items[i] = .{ .doc_id = .{ .ids = constraints.exclude_doc_ids } };
            i += 1;
        }
        if (has_exclude_doc_nums) {
            items[i] = .{ .doc_num = .{ .ids = constraints.exclude_doc_nums } };
            i += 1;
        }
        break :blk items;
    } else &.{};

    return .{ .bool_query = .{
        .must = must,
        .must_not = must_not,
        .min_should = 0,
    } };
}

fn convertNativeDocIdsToTextDocNumsAlloc(
    alloc: Allocator,
    req: types.SearchRequest,
    snapshot: *const index_mod.IndexSnapshot,
    constraints: *NativeDocIdConstraints,
) !void {
    if (constraints.filter_doc_ids.len > 0) {
        const mapped = try textDocNumsForDocIdsAlloc(alloc, req, snapshot, constraints.filter_doc_ids);
        if (constraints.filter_doc_nums.len > 0) {
            const intersected = try intersectDocNumsAlloc(alloc, constraints.filter_doc_nums, mapped);
            if (constraints.filter_doc_nums_owned and constraints.filter_doc_nums.len > 0) alloc.free(@constCast(constraints.filter_doc_nums));
            alloc.free(mapped);
            constraints.filter_doc_nums = intersected;
        } else {
            constraints.filter_doc_nums = mapped;
        }
        constraints.filter_doc_nums_owned = true;
        if (constraints.filter_doc_ids_owned) freeDocIdSlice(alloc, constraints.filter_doc_ids);
        constraints.filter_doc_ids = &.{};
        constraints.filter_doc_ids_owned = false;
    }

    if (constraints.exclude_doc_ids.len > 0) {
        const mapped = try textDocNumsForDocIdsAlloc(alloc, req, snapshot, constraints.exclude_doc_ids);
        if (constraints.exclude_doc_nums.len > 0) {
            const merged = try unionDocNumsAlloc(alloc, constraints.exclude_doc_nums, mapped);
            if (constraints.exclude_doc_nums_owned and constraints.exclude_doc_nums.len > 0) alloc.free(@constCast(constraints.exclude_doc_nums));
            alloc.free(mapped);
            constraints.exclude_doc_nums = merged;
        } else {
            constraints.exclude_doc_nums = mapped;
        }
        constraints.exclude_doc_nums_owned = true;
        if (constraints.exclude_doc_ids_owned) freeDocIdSlice(alloc, constraints.exclude_doc_ids);
        constraints.exclude_doc_ids = &.{};
        constraints.exclude_doc_ids_owned = false;
    }
}

fn normalizeNativeDocNumConstraintsAlloc(
    alloc: Allocator,
    constraints: *NativeDocIdConstraints,
) !void {
    try normalizeNativeDocNumSliceAlloc(alloc, &constraints.filter_doc_nums, &constraints.filter_doc_nums_owned);
    try normalizeNativeDocNumSliceAlloc(alloc, &constraints.exclude_doc_nums, &constraints.exclude_doc_nums_owned);
}

fn normalizeNativeDocNumSliceAlloc(
    alloc: Allocator,
    items: *[]const u32,
    owned: *bool,
) !void {
    if (items.*.len == 0) return;
    const mutable = if (owned.*)
        @constCast(items.*)
    else blk: {
        const copy = try alloc.dupe(u32, items.*);
        items.* = copy;
        owned.* = true;
        break :blk copy;
    };
    std.mem.sort(u32, mutable, {}, u32LessThan);
    const unique_len = uniqueSortedU32(mutable);
    if (unique_len != mutable.len) {
        items.* = try alloc.realloc(mutable, unique_len);
    }
}

fn textDocNumsForDocIdsAlloc(
    alloc: Allocator,
    req: types.SearchRequest,
    snapshot: *const index_mod.IndexSnapshot,
    doc_ids: []const []const u8,
) ![]const u32 {
    var doc_id_set = try BorrowedDocIdSet.initAlloc(alloc, doc_ids);
    defer doc_id_set.deinit(alloc);
    var doc_num_set = std.AutoHashMapUnmanaged(u32, void).empty;
    defer doc_num_set.deinit(alloc);

    var out = std.ArrayListUnmanaged(u32).empty;
    errdefer out.deinit(alloc);
    var doc_offset: u32 = 0;
    var scanned_count: u64 = 0;
    for (snapshot.segments) |*seg| {
        {
            seg.shared.lockDeletionShared();
            defer seg.shared.unlockDeletionShared();
            for (0..seg.reader.doc_count) |local_doc_usize| {
                scanned_count +|= 1;
                if (scanned_count == 1 or scanned_count % 1024 == 0) try checkSearchRequestDeadline(req);
                const local_doc: u32 = @intCast(local_doc_usize);
                if (seg.shared.deleted) |deleted| {
                    if (deleted.contains(local_doc)) continue;
                }
                const stored = (try seg.reader.storedDoc(local_doc)) orelse continue;
                if (!(try storedDocumentMatchesPublicDocIdFilterAlloc(alloc, stored.id, &doc_id_set))) continue;
                const doc_num = doc_offset + local_doc;
                const gop = try doc_num_set.getOrPut(alloc, doc_num);
                if (gop.found_existing) continue;
                try out.append(alloc, doc_num);
            }
        }
        doc_offset += seg.reader.doc_count;
    }
    return try out.toOwnedSlice(alloc);
}

/// A public document-id filter targets both the primary document and records
/// derived from it. Chunk-backed text indexes store canonical artifact IDs, so
/// exact ID comparison alone would make a source-level filter silently empty.
/// Keep artifact identity decoding here at the shared text-ID boundary rather
/// than teaching hierarchy grouping about a particular index representation.
fn storedDocumentMatchesPublicDocIdFilterAlloc(
    alloc: Allocator,
    stored_id: []const u8,
    doc_ids: *const BorrowedDocIdSet,
) !bool {
    if (doc_ids.contains(stored_id)) return true;
    if (try artifact_ids.decodeArtifactRefAlloc(alloc, stored_id)) |decoded| {
        var artifact_ref = decoded;
        defer artifact_ref.deinit(alloc);
        return doc_ids.contains(artifact_ref.document_id);
    }
    if (try artifact_ids.decodeArtifactPublicIdAlloc(alloc, stored_id)) |decoded| {
        var artifact_ref = decoded;
        defer artifact_ref.deinit(alloc);
        return doc_ids.contains(artifact_ref.document_id);
    }
    return false;
}

test "text doc id conversion checks deadline while scanning" {
    const alloc = std.testing.allocator;

    var seg_writer = segment_mod.SegmentWriter.init(alloc);
    defer seg_writer.deinit();
    try seg_writer.addStoredDoc("doc:a", "{\"title\":\"alpha\"}");
    const seg_bytes = try seg_writer.build();
    defer alloc.free(seg_bytes);

    var writer = try index_mod.IndexWriter.init(alloc);
    defer writer.deinit();
    try writer.addSegment(seg_bytes);
    const snapshot = writer.snapshot();

    try std.testing.expectError(error.Timeout, textDocNumsForDocIdsAlloc(alloc, .{
        .execution_deadline_ns = 0,
    }, snapshot, &.{"doc:a"}));
}

test "text doc id conversion resolves source ids to derived artifacts" {
    const alloc = std.testing.allocator;

    const artifact_id = try artifact_ids.internalKeyForArtifactRefAlloc(alloc, .{
        .document_id = @constCast("doc:a"),
        .name = @constCast("body_chunks_v1"),
        .kind = .chunk,
        .chunk_id = 0,
    });
    defer alloc.free(artifact_id);

    var seg_writer = segment_mod.SegmentWriter.init(alloc);
    defer seg_writer.deinit();
    try seg_writer.addStoredDoc(artifact_id, "{\"text\":\"alpha\"}");
    try seg_writer.addStoredDoc("doc:b", "{\"text\":\"beta\"}");
    const seg_bytes = try seg_writer.build();
    defer alloc.free(seg_bytes);

    var writer = try index_mod.IndexWriter.init(alloc);
    defer writer.deinit();
    try writer.addSegment(seg_bytes);
    const snapshot = writer.snapshot();

    const mapped = try textDocNumsForDocIdsAlloc(alloc, .{}, snapshot, &.{"doc:a"});
    defer alloc.free(mapped);
    try std.testing.expectEqualSlices(u32, &.{0}, mapped);
}

pub fn collectSearchRequestTextStats(
    alloc: Allocator,
    req: types.SearchRequest,
    executor: SearchTextStatsExecutor,
) ![]const distributed_stats_mod.TextFieldStats {
    var stats_map = std.StringHashMapUnmanaged(SearchRequestTextStatEntry){};
    defer {
        var it = stats_map.iterator();
        while (it.next()) |entry| {
            var term_it = entry.value_ptr.terms.keyIterator();
            while (term_it.next()) |term| alloc.free(term.*);
            entry.value_ptr.terms.deinit(alloc);
            alloc.free(entry.value_ptr.field);
            alloc.free(entry.key_ptr.*);
        }
        stats_map.deinit(alloc);
    }

    if (req.full_text_queries.len == 0) {
        if (req.full_text) |text_query| {
            const text_entry = (try executor.text_index_entry(executor.ctx, req.index_name)) orelse return &.{};
            {
                text_entry.lockAnalysisShared();
                defer text_entry.unlockAnalysisShared();
                try collectTextQueryTerms(alloc, &stats_map, req.index_name, text_query, text_entry.text_analysis, text_entry.runtime_schema);
            }
        } else if (isTextQuery(req.query) and !isDefaultMatchAll(req.query)) {
            const text_entry = (try executor.text_index_entry(executor.ctx, req.index_name)) orelse return &.{};
            {
                text_entry.lockAnalysisShared();
                defer text_entry.unlockAnalysisShared();
                try collectQueryTerms(alloc, &stats_map, req.index_name, req.query, text_entry.text_analysis, text_entry.runtime_schema);
            }
        }
    } else {
        for (req.full_text_queries) |item| {
            const text_entry = (try executor.text_index_entry(executor.ctx, item.index_name)) orelse continue;
            {
                text_entry.lockAnalysisShared();
                defer text_entry.unlockAnalysisShared();
                try collectTextQueryTerms(alloc, &stats_map, item.index_name, item.query, text_entry.text_analysis, text_entry.runtime_schema);
            }
        }
    }

    if (req.filter_query_json.len > 0 or req.exclusion_query_json.len > 0) {
        const filter_index_name = req.primary_text_index_name orelse req.index_name;
        const text_entry = (try executor.text_index_entry(executor.ctx, filter_index_name)) orelse return &.{};
        {
            text_entry.lockAnalysisShared();
            defer text_entry.unlockAnalysisShared();
            if (req.filter_query_json.len > 0) {
                try collectPatternFilterQueryTerms(alloc, &stats_map, filter_index_name, req.filter_query_json, text_entry.text_analysis, text_entry.runtime_schema);
            }
            if (req.exclusion_query_json.len > 0) {
                try collectPatternFilterQueryTerms(alloc, &stats_map, filter_index_name, req.exclusion_query_json, text_entry.text_analysis, text_entry.runtime_schema);
            }
        }
    }

    if (stats_map.count() == 0) return &.{};

    var requests = try alloc.alloc(ExplicitTextStatRequest, stats_map.count());
    defer {
        for (requests) |request| {
            for (request.terms) |term| alloc.free(term);
            if (request.terms.len > 0) alloc.free(request.terms);
        }
        alloc.free(requests);
    }

    var request_index: usize = 0;
    var it = stats_map.iterator();
    while (it.next()) |entry| {
        const terms = try alloc.alloc([]const u8, entry.value_ptr.terms.count());
        var term_index: usize = 0;
        var term_it = entry.value_ptr.terms.keyIterator();
        while (term_it.next()) |term| {
            terms[term_index] = try alloc.dupe(u8, term.*);
            term_index += 1;
        }
        requests[request_index] = .{
            .index_name = entry.value_ptr.index_name,
            .field = entry.value_ptr.field,
            .terms = terms,
        };
        request_index += 1;
    }

    return try collectExplicitTextStats(alloc, requests, executor);
}

pub fn collectExplicitTextStats(
    alloc: Allocator,
    requests: []const ExplicitTextStatRequest,
    executor: SearchTextStatsExecutor,
) ![]const distributed_stats_mod.TextFieldStats {
    if (requests.len == 0) return &.{};
    const out = try alloc.alloc(distributed_stats_mod.TextFieldStats, requests.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |*item| item.deinit(alloc);
        if (out.len > 0) alloc.free(out);
    }

    for (requests, 0..) |request, i| {
        const text_entry = (try executor.text_index_entry(executor.ctx, request.index_name)) orelse return error.IndexNotFound;
        const snapshot = text_entry.persistent.acquireSnapshot();
        defer snapshot.release();
        if (request.resolved_doc_filter) |filter| {
            out[i] = try collectFilteredExplicitTextStats(alloc, snapshot, request, filter, executor);
            initialized += 1;
            continue;
        }
        const term_doc_freqs = try alloc.alloc(distributed_stats_mod.TermDocFreq, request.terms.len);
        var initialized_terms: usize = 0;
        errdefer {
            for (term_doc_freqs[0..initialized_terms]) |*item| item.deinit(alloc);
            if (term_doc_freqs.len > 0) alloc.free(term_doc_freqs);
        }
        for (request.terms, 0..) |term, term_index| {
            term_doc_freqs[term_index] = .{
                .term = try alloc.dupe(u8, term),
                .doc_freq = try snapshot.termDocFreq(alloc, request.field, term),
            };
            initialized_terms += 1;
        }
        out[i] = .{
            .field = try alloc.dupe(u8, request.field),
            .global_doc_count = snapshot.scoringDocCount(),
            .global_total_field_len = snapshot.liveTotalFieldLen(request.field),
            .term_doc_freqs = term_doc_freqs,
        };
        initialized += 1;
    }
    return out;
}

fn collectFilteredExplicitTextStats(
    alloc: Allocator,
    snapshot: *const index_mod.IndexSnapshot,
    request: ExplicitTextStatRequest,
    filter: *const doc_set.ResolvedDocFilter,
    executor: SearchTextStatsExecutor,
) !distributed_stats_mod.TextFieldStats {
    const term_doc_freqs = try alloc.alloc(distributed_stats_mod.TermDocFreq, request.terms.len);
    var initialized_terms: usize = 0;
    errdefer {
        for (term_doc_freqs[0..initialized_terms]) |*item| item.deinit(alloc);
        if (term_doc_freqs.len > 0) alloc.free(term_doc_freqs);
    }
    for (request.terms, 0..) |term, term_index| {
        term_doc_freqs[term_index] = .{
            .term = try alloc.dupe(u8, term),
            .doc_freq = 0,
        };
        initialized_terms += 1;
    }

    var global_doc_count: u32 = 0;
    var global_total_field_len: u64 = 0;
    var selected_doc_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer selected_doc_keys.deinit(alloc);
    var doc_offset: u32 = 0;
    for (snapshot.segments) |*seg| {
        {
            seg.shared.lockDeletionShared();
            defer seg.shared.unlockDeletionShared();
            for (0..seg.reader.doc_count) |local_doc_usize| {
                const local_doc: u32 = @intCast(local_doc_usize);
                if (seg.shared.deleted) |deleted| {
                    if (deleted.contains(local_doc)) continue;
                }
                const doc_id = doc_offset + local_doc;
                if (!(try docAllowedByResolvedFilter(snapshot, doc_id, filter))) continue;
                global_doc_count += 1;
                const stored = (try snapshot.storedDoc(doc_id)) orelse continue;
                try selected_doc_keys.append(alloc, stored.id);
            }
        }
        doc_offset += seg.reader.doc_count;
    }

    // Product text segments retain document IDs but intentionally omit the
    // duplicated source JSON. Hydrate only the filtered documents from the
    // primary store, preserving exact projection without a full-index postings
    // scan or restoring the duplicate text-segment copy.
    if (executor.load_many_stored) |load_many| {
        const loaded = try load_many(executor.ctx, alloc, selected_doc_keys.items);
        defer freeOptionalOwnedBytes(alloc, loaded);
        if (loaded.len != selected_doc_keys.items.len) return error.InvalidData;
        for (loaded) |maybe_stored| {
            const stored = maybe_stored orelse continue;
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, stored, .{}) catch continue;
            defer parsed.deinit();
            const value = extractJsonValueAtPath(parsed.value, request.field) orelse continue;
            global_total_field_len +|= try countAnalyzedTokensInJsonValue(alloc, value);

            var seen_terms = std.StringHashMap(void).init(alloc);
            defer {
                var it = seen_terms.keyIterator();
                while (it.next()) |key| alloc.free(key.*);
                seen_terms.deinit();
            }
            try collectSignificantTermsFromJsonValue(alloc, value, &seen_terms);
            for (term_doc_freqs) |*item| {
                if (seen_terms.contains(item.term)) item.doc_freq +|= 1;
            }
        }
    } else {
        // Index-only adapters have no primary document store. Retain an exact
        // fallback by summing native term frequencies for allowed documents.
        doc_offset = 0;
        for (snapshot.segments) |*seg| {
            var allowed_local_docs = roaring.RoaringBitmap.init(alloc);
            defer allowed_local_docs.deinit();
            {
                seg.shared.lockDeletionShared();
                defer seg.shared.unlockDeletionShared();
                for (0..seg.reader.doc_count) |local_doc_usize| {
                    const local_doc: u32 = @intCast(local_doc_usize);
                    if (seg.shared.deleted) |deleted| {
                        if (deleted.contains(local_doc)) continue;
                    }
                    if (try docAllowedByResolvedFilter(snapshot, doc_offset + local_doc, filter)) {
                        try allowed_local_docs.add(local_doc);
                    }
                }
            }
            if (try seg.reader.invertedIndex(request.field)) |inv_reader| {
                var terms = try inv_reader.termIterator();
                defer terms.deinit();
                while (try terms.next()) |entry| {
                    var postings = try entry.result.iterator(alloc);
                    defer postings.deinit();
                    postings.decode_positions = false;
                    while (try postings.next()) |hit| {
                        if (!allowed_local_docs.contains(hit.doc_id)) continue;
                        global_total_field_len +|= hit.freq;
                        for (term_doc_freqs) |*item| {
                            if (std.mem.eql(u8, item.term, entry.term)) item.doc_freq +|= 1;
                        }
                    }
                }
            }
            doc_offset += seg.reader.doc_count;
        }
    }

    return .{
        .field = try alloc.dupe(u8, request.field),
        .global_doc_count = global_doc_count,
        .global_total_field_len = global_total_field_len,
        .term_doc_freqs = term_doc_freqs,
    };
}

fn docAllowedByResolvedFilter(
    snapshot: *const index_mod.IndexSnapshot,
    doc_id: u32,
    filter: *const doc_set.ResolvedDocFilter,
) !bool {
    return (try docSetContainsSnapshotDoc(snapshot, &filter.include, doc_id)) and
        !(try docSetContainsSnapshotDoc(snapshot, &filter.exclude, doc_id));
}

fn docSetContainsSnapshotDoc(
    snapshot: *const index_mod.IndexSnapshot,
    set: *const doc_set.ResolvedDocSet,
    doc_id: u32,
) !bool {
    return switch (set.*) {
        .all => true,
        .none => false,
        .ordinals, .ordinal_bitmap => blk: {
            const ordinal = (try snapshot.docOrdinal(doc_id)) orelse break :blk false;
            break :blk set.containsOrdinal(ordinal);
        },
        .doc_keys => |keys| blk: {
            const stored = (try snapshot.storedDoc(doc_id)) orelse break :blk false;
            for (keys) |key| {
                if (std.mem.eql(u8, key, stored.id)) break :blk true;
            }
            break :blk false;
        },
    };
}

pub fn collectExplicitBackgroundTextStats(
    alloc: Allocator,
    requests: []const ExplicitBackgroundTextStatRequest,
    executor: SearchTextStatsExecutor,
) ![]const aggregations_mod.DistributedBackgroundTextStats {
    if (requests.len == 0) return &.{};
    const out = try alloc.alloc(aggregations_mod.DistributedBackgroundTextStats, requests.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |*item| item.deinit(alloc);
        if (out.len > 0) alloc.free(out);
    }

    for (requests, 0..) |request, i| {
        const text_entry = (try executor.text_index_entry(executor.ctx, request.index_name)) orelse return error.IndexNotFound;
        const snapshot = text_entry.persistent.acquireSnapshot();
        defer snapshot.release();
        var background_result = try executeBackgroundQuery(alloc, snapshot, request.background_query);
        defer background_result.deinit();

        const term_doc_freqs = try alloc.alloc(distributed_stats_mod.TermDocFreq, request.terms.len);
        var initialized_terms: usize = 0;
        errdefer {
            for (term_doc_freqs[0..initialized_terms]) |*item| item.deinit(alloc);
            if (term_doc_freqs.len > 0) alloc.free(term_doc_freqs);
        }
        for (request.terms, 0..) |term, term_index| {
            term_doc_freqs[term_index] = .{
                .term = try alloc.dupe(u8, term),
                .doc_freq = 0,
            };
            initialized_terms += 1;
        }

        const term_doc_sets = try alloc.alloc(roaring.RoaringBitmap, request.terms.len);
        var initialized_sets: usize = 0;
        defer {
            for (term_doc_sets[0..initialized_sets]) |*set| set.deinit();
            if (term_doc_sets.len > 0) alloc.free(term_doc_sets);
        }
        for (request.terms, 0..) |term, term_index| {
            term_doc_sets[term_index] = roaring.RoaringBitmap.init(alloc);
            initialized_sets += 1;
            const doc_nums = try snapshot.executeFilter(alloc, .{ .term = .{
                .field = request.field,
                .term = term,
            } });
            defer alloc.free(doc_nums);
            for (doc_nums) |doc_num| try term_doc_sets[term_index].add(doc_num);
        }

        var background_doc_count: u32 = 0;
        for (background_result.hits) |hit| {
            if (request.resolved_doc_filter) |filter| {
                if (!(try docAllowedByResolvedFilter(snapshot, hit.doc_id, filter))) continue;
            }
            background_doc_count += 1;
            for (term_doc_freqs, 0..) |*item, term_index| {
                if (term_doc_sets[term_index].contains(hit.doc_id)) item.doc_freq +|= 1;
            }
        }

        out[i] = .{
            .aggregation_name = try alloc.dupe(u8, request.aggregation_name),
            .field = try alloc.dupe(u8, request.field),
            .background_doc_count = if (request.resolved_doc_filter != null) background_doc_count else background_result.total_hits,
            .term_doc_freqs = term_doc_freqs,
        };
        initialized += 1;
    }
    return out;
}

pub fn executeBackgroundQuery(
    alloc: Allocator,
    snapshot: *const @import("../../../index.zig").IndexSnapshot,
    query: aggregations_mod.BackgroundQuery,
) !search_mod.SearchResult {
    const request: search_mod.SearchRequest = .{
        .query = switch (query) {
            .match_all => .{ .match_all = {} },
            .match => |match| .{ .match = .{
                .field = match.field,
                .text = match.text,
            } },
            .term => |term| .{ .term = .{
                .field = term.field,
                .term = term.term,
            } },
        },
        .k = snapshot.liveDocCount(),
        .include_stored = false,
    };
    return search_mod.execute(alloc, snapshot, request);
}

test "text stats use postings when segment source is omitted" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/background-postings", .{tmp.sub_path});
    defer alloc.free(path);
    const path_z = try alloc.dupeZ(u8, path);
    defer alloc.free(path_z);

    var persistent = try persistent_mod.PersistentIndex.open(alloc, .{
        .path = path_z.ptr,
        .main_backend = .lsm_memory,
    });
    var persistent_owned = true;
    errdefer if (persistent_owned) persistent.close();

    const segment = try introducer_mod.buildSegmentFromTextWithAnalysisOptions(
        alloc,
        &.{
            .{
                .id = "doc:a",
                .stored_data = "{\"body\":\"alpha\"}",
                .text_fields = &.{.{ .field_name = "body", .text = "alpha" }},
            },
            .{
                .id = "doc:b",
                .stored_data = "{\"body\":\"alpha beta\"}",
                .text_fields = &.{.{ .field_name = "body", .text = "alpha beta" }},
            },
        },
        &analysis_mod.default_analyzer,
        .{},
        .{ .store_document_source = false },
    );
    defer alloc.free(segment);
    try persistent.writer.addSegment(segment);

    var apply_mutex = std.atomic.Mutex.unlocked;
    var text_entry = index_manager_mod.IndexManager.TextIndex{
        .apply_mutex = &apply_mutex,
        .config = .{ .name = "ft", .kind = .full_text, .config_json = "{}" },
        .chunk_name = null,
        .text_analysis = .{},
        .runtime_schema = null,
        .rebuild_root_path = "",
        .persistent = persistent,
    };
    persistent_owned = false;
    defer text_entry.persistent.close();

    const Harness = struct {
        entry: *index_manager_mod.IndexManager.TextIndex,

        fn textIndexEntry(ctx: ?*anyopaque, _: ?[]const u8) anyerror!?*index_manager_mod.IndexManager.TextIndex {
            const self: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
            return self.entry;
        }
    };
    var harness = Harness{ .entry = &text_entry };
    const stats = try collectExplicitBackgroundTextStats(alloc, &.{.{
        .aggregation_name = "sig",
        .index_name = "ft",
        .field = "body",
        .terms = &.{ "alpha", "beta" },
        .background_query = .{ .match_all = {} },
    }}, .{
        .ctx = &harness,
        .text_index_entry = Harness.textIndexEntry,
    });
    defer aggregations_mod.deinitDistributedBackgroundTextStats(alloc, stats);

    try std.testing.expectEqual(@as(usize, 1), stats.len);
    try std.testing.expectEqual(@as(u32, 2), stats[0].background_doc_count);
    try std.testing.expectEqual(@as(u32, 2), stats[0].term_doc_freqs[0].doc_freq);
    try std.testing.expectEqual(@as(u32, 1), stats[0].term_doc_freqs[1].doc_freq);

    var filter = doc_set.ResolvedDocFilter{
        .include = try doc_set.cloneDocKeysAlloc(alloc, &.{"doc:b"}),
    };
    defer filter.deinit(alloc);
    const explicit_stats = try collectExplicitTextStats(alloc, &.{.{
        .index_name = "ft",
        .field = "body",
        .terms = &.{ "alpha", "beta" },
        .resolved_doc_filter = &filter,
    }}, .{
        .ctx = &harness,
        .text_index_entry = Harness.textIndexEntry,
    });
    defer distributed_stats_mod.deinitTextFieldStats(alloc, explicit_stats);

    try std.testing.expectEqual(@as(usize, 1), explicit_stats.len);
    try std.testing.expectEqual(@as(u32, 1), explicit_stats[0].global_doc_count);
    try std.testing.expectEqual(@as(u64, 2), explicit_stats[0].global_total_field_len);
    try std.testing.expectEqual(@as(u32, 1), explicit_stats[0].term_doc_freqs[0].doc_freq);
    try std.testing.expectEqual(@as(u32, 1), explicit_stats[0].term_doc_freqs[1].doc_freq);
}

fn collectQueryTerms(
    alloc: Allocator,
    stats_map: *std.StringHashMapUnmanaged(SearchRequestTextStatEntry),
    index_name: ?[]const u8,
    query: types.Query,
    text_analysis: introducer_mod.TextAnalysisConfig,
    runtime_schema: ?runtime_schema_mod.TableSchema,
) !void {
    return switch (query) {
        .term => |term| try appendFieldTerm(alloc, stats_map, index_name, term.field, term.term),
        .match => |match| try appendAnalyzedTerms(alloc, stats_map, index_name, match.field, match.text, match.analyzer, text_analysis, runtime_schema),
        else => {},
    };
}

fn collectTextQueryTerms(
    alloc: Allocator,
    stats_map: *std.StringHashMapUnmanaged(SearchRequestTextStatEntry),
    index_name: ?[]const u8,
    query: types.TextQuery,
    text_analysis: introducer_mod.TextAnalysisConfig,
    runtime_schema: ?runtime_schema_mod.TableSchema,
) !void {
    return switch (query) {
        .term => |term| try appendFieldTerm(alloc, stats_map, index_name, term.field, term.term),
        .match => |match| try appendAnalyzedTerms(alloc, stats_map, index_name, match.field, match.text, match.analyzer, text_analysis, runtime_schema),
        .bool_query => |bool_query| {
            for (bool_query.must) |child| try collectTextQueryTerms(alloc, stats_map, index_name, child, text_analysis, runtime_schema);
            for (bool_query.should) |child| try collectTextQueryTerms(alloc, stats_map, index_name, child, text_analysis, runtime_schema);
            for (bool_query.must_not) |child| try collectTextQueryTerms(alloc, stats_map, index_name, child, text_analysis, runtime_schema);
        },
        else => {},
    };
}

fn appendAnalyzedTerms(
    alloc: Allocator,
    stats_map: *std.StringHashMapUnmanaged(SearchRequestTextStatEntry),
    index_name: ?[]const u8,
    field: []const u8,
    text: []const u8,
    analyzer_name: ?[]const u8,
    text_analysis: introducer_mod.TextAnalysisConfig,
    runtime_schema: ?runtime_schema_mod.TableSchema,
) !void {
    const analyzer = (try resolveQueryAnalyzer(field, analyzer_name, text_analysis, runtime_schema)) orelse &analysis_mod.default_analyzer;
    const tokens = try analyzer.analyze(alloc, text);
    defer analysis_mod.Analyzer.freeTokens(alloc, tokens);
    for (tokens) |token| {
        try appendFieldTerm(alloc, stats_map, index_name, field, token.term);
    }
}

fn appendFieldTerm(
    alloc: Allocator,
    stats_map: *std.StringHashMapUnmanaged(SearchRequestTextStatEntry),
    index_name: ?[]const u8,
    field: []const u8,
    term: []const u8,
) !void {
    const map_key = try textStatsMapKeyAlloc(alloc, index_name, field);
    errdefer alloc.free(map_key);

    const gop = try stats_map.getOrPut(alloc, map_key);
    if (!gop.found_existing) {
        gop.key_ptr.* = map_key;
        gop.value_ptr.* = .{
            .field = try alloc.dupe(u8, field),
            .index_name = index_name,
        };
    } else {
        alloc.free(map_key);
    }
    const term_gop = try gop.value_ptr.terms.getOrPut(alloc, term);
    if (!term_gop.found_existing) {
        term_gop.key_ptr.* = try alloc.dupe(u8, term);
    }
}

fn textStatsMapKeyAlloc(alloc: Allocator, index_name: ?[]const u8, field: []const u8) ![]u8 {
    if (index_name) |bound_index_name| {
        return try textStatsTupleKeyAlloc(alloc, &.{ "index", bound_index_name, field });
    }
    return try textStatsTupleKeyAlloc(alloc, &.{ "field", field });
}

fn textStatsTupleKeyAlloc(alloc: Allocator, components: []const []const u8) ![]u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);

    for (components) |component| {
        if (component.len > std.math.maxInt(u32)) return error.KeyComponentTooLarge;
        var len_buf: [@sizeOf(u32)]u8 = undefined;
        std.mem.writeInt(u32, &len_buf, @intCast(component.len), .big);
        try out.appendSlice(alloc, &len_buf);
        try out.appendSlice(alloc, component);
    }

    return try out.toOwnedSlice(alloc);
}

test "search request text stats keys preserve embedded separators" {
    const alloc = std.testing.allocator;

    var stats_map = std.StringHashMapUnmanaged(SearchRequestTextStatEntry){};
    defer {
        var it = stats_map.iterator();
        while (it.next()) |entry| {
            alloc.free(entry.key_ptr.*);
            alloc.free(entry.value_ptr.field);
            var term_it = entry.value_ptr.terms.keyIterator();
            while (term_it.next()) |term| alloc.free(term.*);
            entry.value_ptr.terms.deinit(alloc);
        }
        stats_map.deinit(alloc);
    }

    try appendFieldTerm(alloc, &stats_map, "idx\x1ffield", "name", "alpha");
    try appendFieldTerm(alloc, &stats_map, "idx", "field\x1fname", "beta");

    try std.testing.expectEqual(@as(u32, 2), stats_map.count());
}

fn collectPatternFilterQueryTerms(
    alloc: Allocator,
    stats_map: *std.StringHashMapUnmanaged(SearchRequestTextStatEntry),
    index_name: ?[]const u8,
    filter_query_json: []const u8,
    text_analysis: introducer_mod.TextAnalysisConfig,
    runtime_schema: ?runtime_schema_mod.TableSchema,
) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, filter_query_json, .{}) catch return;
    defer parsed.deinit();
    try collectPatternFilterValueTerms(alloc, stats_map, index_name, parsed.value, text_analysis, runtime_schema);
}

fn collectPatternFilterValueTerms(
    alloc: Allocator,
    stats_map: *std.StringHashMapUnmanaged(SearchRequestTextStatEntry),
    index_name: ?[]const u8,
    value: std.json.Value,
    text_analysis: introducer_mod.TextAnalysisConfig,
    runtime_schema: ?runtime_schema_mod.TableSchema,
) !void {
    const object = switch (value) {
        .object => |object| object,
        else => return,
    };

    if (object.get("term")) |term_value| {
        try collectPatternFilterFieldStringTerms(alloc, stats_map, index_name, term_value, false, text_analysis, runtime_schema);
    }
    if (object.get("match")) |match_value| {
        try collectPatternFilterFieldStringTerms(alloc, stats_map, index_name, match_value, true, text_analysis, runtime_schema);
    }
    if (object.get("bool")) |bool_value| {
        const bool_object = switch (bool_value) {
            .object => |inner| inner,
            else => return,
        };
        for ([_][]const u8{ "must", "filter", "should", "must_not" }) |key| {
            const items = bool_object.get(key) orelse continue;
            const array = switch (items) {
                .array => |array| array,
                else => continue,
            };
            for (array.items) |item| {
                try collectPatternFilterValueTerms(alloc, stats_map, index_name, item, text_analysis, runtime_schema);
            }
        }
    }
}

fn collectPatternFilterFieldStringTerms(
    alloc: Allocator,
    stats_map: *std.StringHashMapUnmanaged(SearchRequestTextStatEntry),
    index_name: ?[]const u8,
    value: std.json.Value,
    analyze: bool,
    text_analysis: introducer_mod.TextAnalysisConfig,
    runtime_schema: ?runtime_schema_mod.TableSchema,
) !void {
    const object = switch (value) {
        .object => |object| object,
        else => return,
    };
    if (object.count() != 1) return;
    var it = object.iterator();
    const entry = it.next() orelse return;
    const text = switch (entry.value_ptr.*) {
        .string => |text| text,
        else => return,
    };
    if (analyze) {
        try appendAnalyzedTerms(alloc, stats_map, index_name, entry.key_ptr.*, text, null, text_analysis, runtime_schema);
    } else {
        try appendFieldTerm(alloc, stats_map, index_name, entry.key_ptr.*, text);
    }
}

fn extractJsonValueAtPath(root: std.json.Value, field_path: []const u8) ?std.json.Value {
    var current = root;
    var parts = std.mem.splitScalar(u8, field_path, '.');
    while (parts.next()) |part| {
        switch (current) {
            .object => |obj| current = obj.get(part) orelse return null,
            else => return null,
        }
    }
    return current;
}

fn collectSignificantTermsFromJsonValue(
    alloc: Allocator,
    value: std.json.Value,
    seen_terms: *std.StringHashMap(void),
) !void {
    switch (value) {
        .array => |arr| for (arr.items) |item| try collectSignificantTermsFromJsonValue(alloc, item, seen_terms),
        .string => {
            const tokens = try analysis_mod.default_analyzer.analyze(alloc, value.string);
            defer analysis_mod.Analyzer.freeTokens(alloc, tokens);
            for (tokens) |tok| {
                const entry = try seen_terms.getOrPut(tok.term);
                if (entry.found_existing) continue;
                entry.key_ptr.* = try alloc.dupe(u8, tok.term);
                entry.value_ptr.* = {};
            }
        },
        else => {},
    }
}

fn countAnalyzedTokensInJsonValue(alloc: Allocator, value: std.json.Value) !u64 {
    return switch (value) {
        .array => |arr| blk: {
            var total: u64 = 0;
            for (arr.items) |item| total += try countAnalyzedTokensInJsonValue(alloc, item);
            break :blk total;
        },
        .string => blk: {
            const tokens = try analysis_mod.default_analyzer.analyze(alloc, value.string);
            defer analysis_mod.Analyzer.freeTokens(alloc, tokens);
            break :blk @as(u64, @intCast(tokens.len));
        },
        else => 0,
    };
}

pub fn searchDense(
    alloc: Allocator,
    req: types.SearchRequest,
    dense: types.DenseKnnQuery,
    executor: DenseSearchExecutor,
) !types.SearchResult {
    var profile = DenseSearchProfile{};
    return try searchDenseInternal(alloc, req, dense, executor, &profile, false);
}

pub fn searchDenseProfiled(
    alloc: Allocator,
    req: types.SearchRequest,
    dense: types.DenseKnnQuery,
    executor: DenseSearchExecutor,
) !ProfiledDenseSearchResult {
    var profile = DenseSearchProfile{};
    return .{
        .result = try searchDenseInternal(alloc, req, dense, executor, &profile, true),
        .profile = profile,
    };
}

fn searchDenseInternal(
    alloc: Allocator,
    req: types.SearchRequest,
    dense: types.DenseKnnQuery,
    executor: DenseSearchExecutor,
    profile: *DenseSearchProfile,
    include_hbc_profile: bool,
) !types.SearchResult {
    resetLastSortRejectionDiagnostic();
    try rejectApproximateSortPageOptions(req);
    const total_start = platform_time.monotonicNs();

    const index_lookup_start = total_start;
    const entry = (try executor.dense_index(executor.ctx, req.index_name)) orelse return error.IndexNotFound;
    profile.index_lookup_ns = platform_time.monotonicNs() - index_lookup_start;

    const chunk_backed = entry.chunk_name != null;
    const group_chunk_parents = shouldGroupChunkParents(req, chunk_backed);
    const paging = componentPaging(req);
    const index_stats = entry.index.stats();
    const constraint_start = platform_time.monotonicNs();
    var native_constraints = try deriveNativeDenseConstraintsAlloc(alloc, req, executor, req.index_name orelse entry.config.name, true);
    profile.constraint_ns = platform_time.monotonicNs() - constraint_start;
    defer native_constraints.deinit(alloc);
    const unresolved_stored_filters =
        (req.filter_query_json.len > 0 and !native_constraints.filter_query_json_resolved) or
        (req.exclusion_query_json.len > 0 and !native_constraints.exclusion_query_json_resolved);
    const postprocess_req = requestWithoutResolvedStoredFilters(
        req,
        native_constraints.filter_query_json_resolved,
        native_constraints.exclusion_query_json_resolved,
    );
    const full_candidate_window = group_chunk_parents or unresolved_stored_filters;
    const page_candidate_window = pagingCandidateWindow(paging);
    const score_order_k = scoreOrderCandidateWindowK(dense.k, paging);
    const effort = resolvedSearchEffort(req.search_effort);
    const resolved_epsilon = resolveSearchEpsilon(effort);
    profile.resolved_epsilon = resolved_epsilon;
    const bench_query_profile = shouldLogBenchQueryProfile();
    const collect_sort_profile = bench_query_profile or req.profile;
    const collect_hbc_profile = include_hbc_profile or bench_query_profile;

    const effective_filter_ids = if (native_constraints.positive_filter) native_constraints.filter_ids else req.filter_ids;
    profile.native_filter_candidate_count = @intCast(effective_filter_ids.len);
    const effective_exclude_ids = if (native_constraints.exclude_ids.len > 0) native_constraints.exclude_ids else req.exclude_ids;
    const effective_native_filter_candidate_count = if (native_constraints.positive_filter)
        if (native_constraints.exclude_ids_owned)
            dense_exact.differenceCandidateUpperBoundNormalizedExclusions(effective_filter_ids, effective_exclude_ids)
        else
            dense_exact.differenceCandidateUpperBound(effective_filter_ids, effective_exclude_ids) orelse effective_filter_ids.len
    else
        effective_filter_ids.len;
    if (native_constraints.positive_filter and effective_native_filter_candidate_count == 0) {
        profile.search_route = "empty_result";
        profile.route_reason = "empty_native_filter";
        profile.returned_hit_count = 0;
        profile.total_ns = platform_time.monotonicNs() - total_start;
        return .{
            .alloc = alloc,
            .hits = &.{},
            .total_hits = 0,
            .sort_profile = vectorScoreTopKSortProfile(req, collect_sort_profile, .exact, 0, 0, profile.total_ns),
            .graph_results = &.{},
        };
    }
    var bounded_full_candidate_count: u32 = if (native_constraints.positive_filter)
        @intCast(@min(effective_native_filter_candidate_count, std.math.maxInt(u32)))
    else
        @intCast(index_stats.active_count);
    if (!native_constraints.positive_filter and native_constraints.broad_live_exclude_ids.len > 0) {
        const coarse_excluded: u32 = @intCast(@min(
            native_constraints.broad_live_exclude_ids.len,
            @as(usize, bounded_full_candidate_count),
        ));
        // Only pay for active-membership verification when the broad exclusion
        // could make this candidate window exhaustive. The common large-table
        // top-k path remains an O(tombstones) mapping plus the normal HBC query.
        if (!full_candidate_window and score_order_k >= bounded_full_candidate_count - coarse_excluded) {
            const active_excluded = try countActiveDenseVectorIdsAlloc(
                alloc,
                entry,
                native_constraints.broad_live_exclude_ids,
            );
            bounded_full_candidate_count -|= active_excluded;
        }
    }
    const candidate_ceiling = if (group_chunk_parents)
        @min(bounded_full_candidate_count, groupedCandidateBudget())
    else
        bounded_full_candidate_count;
    var candidate_window: u32 = if (full_candidate_window)
        initialAdaptiveCandidateWindow(candidate_ceiling, paging)
    else
        score_order_k;

    while (true) {
        var score_exactness = SortPlanExactness.approximate;
        var projected_source_profile = ProjectedSourceLoadProfile{};
        const hbc_effective_k: u32 = if (full_candidate_window) candidate_window else score_order_k;
        // Adaptive hierarchy grouping can grow k well beyond the original
        // query page. Calibrate recall for the window actually sent to HBC on
        // every iteration; otherwise a larger k repeatedly searches the same
        // too-small leaf budget and can miss additional source groups.
        const resolved_search_width = resolveSearchWidth(hbc_effective_k, effort, index_stats);
        profile.resolved_search_width = resolved_search_width;
        const exhaustive_broad_live_window = !full_candidate_window and
            native_constraints.broad_live_exclude_ids.len > 0 and
            hbc_effective_k >= bounded_full_candidate_count;
        const hbc_req: vectorindex_mod.SearchRequest = .{
            .query = dense.vector,
            .k = hbc_effective_k,
            .rerank_k = if (full_candidate_window)
                @as(usize, @intCast(@min(paging.offset +| paging.limit, hbc_effective_k)))
            else if (exhaustive_broad_live_window)
                @as(usize, @intCast(bounded_full_candidate_count))
            else
                null,
            .search_width = resolved_search_width,
            .epsilon = resolved_epsilon,
            .rerank_factor = resolveRerankFactor(effort),
            .filter_prefix = req.filter_prefix,
            .distance_over = req.distance_over,
            .distance_under = req.distance_under,
            .filter_ids = effective_filter_ids,
            .exclude_ids = effective_exclude_ids,
            .cancellation = if (req.cancellation) |token|
                vectorindex_mod.CancellationToken.fromCallback(token.ptr, token.is_cancelled_fn)
            else
                null,
        };

        const hbc_search_start = platform_time.monotonicNs();
        const route_costs = entry.index.denseRouteCostSnapshot();
        const hbc_cache_pressured = if (entry.index.resource_manager) |manager|
            manager.sliceStats(.hbc_node_metadata_cache).pressure != .normal
        else
            false;
        const hbc_cache_residency_permille: u64 = if (entry.index.resource_manager) |manager| blk: {
            const cache_slice = manager.sliceStats(.hbc_node_metadata_cache);
            const target = if (cache_slice.soft_limit_bytes > 0) cache_slice.soft_limit_bytes else cache_slice.hard_limit_bytes;
            if (target == 0) break :blk 1000;
            break :blk @min(@as(u64, 1000), cache_slice.used_bytes *| 1000 / target);
        } else 1000;
        const route = denseSearchRouteWithCosts(
            native_constraints.positive_filter,
            effective_native_filter_candidate_count,
            index_stats.active_count,
            entry.dims,
            hbc_effective_k,
            resolved_search_width,
            index_stats.leaf_size,
            entry.index.hasExternalVectorLoader(),
            executor.exact_dense_search != null,
            route_costs,
            hbc_cache_pressured,
            hbc_cache_residency_permille,
        );
        entry.index.noteDenseRouteChoice(if (route.exact_native_filter) .exact else .hbc);
        profile.search_route = route.name;
        profile.route_reason = route.reason;
        profile.route_estimated_exact_storage_bytes = route.estimated_exact_storage_bytes;
        profile.route_estimated_hbc_storage_bytes = route.estimated_hbc_storage_bytes;
        profile.route_estimated_exact_work_ns = route.estimated_exact_work_ns;
        profile.route_estimated_hbc_work_ns = route.estimated_hbc_work_ns;
        var results = if (route.exact_native_filter) blk: {
            // The callback is an optional executor override, not an exact-route
            // capability gate. Preserve the built-in exact scorer fallback.
            const exact = if (executor.exact_dense_search) |exact_search|
                try exact_search(executor.ctx, entry, hbc_req)
            else
                try exactScoreNativeDenseFilter(alloc, entry, hbc_req);
            profile.hbc_exact_vectors_scored = exact.vectors_scored;
            profile.exact_candidate_count = exact.profile.candidate_count;
            profile.exact_batch_count = exact.profile.batch_count;
            profile.exact_max_batch_size = exact.profile.max_batch_size;
            profile.exact_workspace_bytes = exact.profile.workspace_bytes;
            profile.exact_request_vector_cache_entries = exact.profile.request_vector_cache_entries;
            profile.exact_raw_batch_reads = exact.profile.raw_batch_reads;
            profile.exact_raw_scalar_reads = exact.profile.raw_scalar_reads;
            profile.exact_missing_vectors = exact.profile.missing_vectors;
            profile.exact_candidate_prepare_ns = exact.profile.candidate_prepare_ns;
            profile.exact_metadata_lookup_ns = exact.profile.metadata_lookup_ns;
            profile.exact_artifact_key_ns = exact.profile.artifact_key_ns;
            profile.exact_artifact_read_ns = exact.profile.artifact_read_ns;
            profile.exact_artifact_decode_ns = exact.profile.artifact_decode_ns;
            profile.exact_distance_ns = exact.profile.distance_ns;
            profile.exact_lsm_cache_hits = exact.profile.lsm_cache_hits;
            profile.exact_lsm_cache_misses = exact.profile.lsm_cache_misses;
            profile.exact_artifact_cache_hits = exact.profile.artifact_cache_hits;
            profile.exact_artifact_vectors_loaded = exact.profile.artifact_vectors_loaded;
            entry.index.observeExactDenseRouteCost(.{
                .candidates = exact.profile.candidate_count,
                .metadata_ns = exact.profile.metadata_lookup_ns,
                .artifact_read_decode_ns = exact.profile.artifact_read_ns +| exact.profile.artifact_decode_ns,
                .distance_ns = exact.profile.distance_ns,
                .artifact_cache_hits = exact.profile.artifact_cache_hits,
                .artifact_vectors_loaded = exact.profile.artifact_vectors_loaded,
            });
            score_exactness = .exact;
            break :blk exact.results;
        } else if (collect_hbc_profile) blk: {
            const profiled = executor.hbc_search_profiled(executor.ctx, entry, hbc_req) catch |err| switch (err) {
                error.NotFound => {
                    profile.returned_hit_count = 0;
                    profile.total_ns = platform_time.monotonicNs() - total_start;
                    return .{
                        .alloc = alloc,
                        .hits = &.{},
                        .total_hits = 0,
                        .sort_profile = vectorScoreTopKSortProfile(req, collect_sort_profile, .approximate, 0, 0, profile.total_ns),
                        .graph_results = &.{},
                    };
                },
                else => return err,
            };
            profile.hbc_runtime_txn_ns = profiled.profile.runtime_txn_ns;
            profile.hbc_scratch_acquire_ns = profiled.profile.scratch_acquire_ns;
            profile.hbc_node_cache_lookup_ns = profiled.profile.node_cache_lookup_ns;
            profile.hbc_quantized_cache_lookup_ns = profiled.profile.quantized_cache_lookup_ns;
            profile.hbc_child_expand_ns = profiled.profile.child_expand_ns;
            profile.hbc_leaf_score_ns = profiled.profile.leaf_score_ns;
            profile.hbc_filter_candidates = profiled.profile.filter_candidates;
            profile.hbc_filter_rejected = profiled.profile.filter_rejected;
            profile.hbc_filter_metadata_batches = profiled.profile.filter_metadata_batches;
            profile.hbc_filter_metadata_batch_ns = profiled.profile.filter_metadata_batch_ns;
            profile.hbc_traversal_waves = profiled.profile.traversal_waves;
            profile.hbc_traversal_initial_wave_leaves = profiled.profile.traversal_initial_wave_leaves;
            profile.hbc_traversal_max_wave_leaves = profiled.profile.traversal_max_wave_leaves;
            profile.hbc_traversal_bound_resolutions = profiled.profile.traversal_bound_resolutions;
            profile.hbc_traversal_bound_fallbacks = profiled.profile.traversal_bound_fallbacks;
            profile.hbc_traversal_bound_stops = profiled.profile.traversal_bound_stops;
            profile.hbc_traversal_frontier_remaining = profiled.profile.traversal_frontier_remaining;
            profile.hbc_traversal_eligible_vectors = profiled.profile.traversal_eligible_vectors;
            profile.hbc_traversal_stop_lower_bound = profiled.profile.traversal_stop_lower_bound;
            profile.hbc_traversal_stop_result_upper_bound = profiled.profile.traversal_stop_result_upper_bound;
            profile.hbc_nodes_visited = profiled.profile.nodes_visited;
            profile.hbc_leaves_explored = profiled.profile.leaves_explored;
            profile.hbc_approx_vectors_scored = profiled.profile.approx_vectors_scored;
            profile.hbc_exact_vectors_scored = profiled.profile.exact_vectors_scored;
            profile.hbc_leaf_payload_stale = profiled.profile.leaf_payload_stale;
            profile.hbc_leaf_payload_missing = profiled.profile.leaf_payload_missing;
            profile.hbc_reranked_vectors = profiled.profile.reranked_vectors;
            profile.hbc_approx_candidate_count = profiled.profile.approx_candidate_count;
            profile.hbc_rerank_candidate_count = profiled.profile.rerank_candidate_count;
            profile.hbc_rerank_batches = profiled.profile.rerank_batches;
            profile.hbc_rerank_max_batch_size = profiled.profile.rerank_max_batch_size;
            profile.hbc_rerank_candidates_skipped_by_bound = profiled.profile.rerank_candidates_skipped_by_bound;
            profile.hbc_ambiguous_top_k_pairs = profiled.profile.ambiguous_top_k_pairs;
            profile.hbc_ambiguous_boundary_pairs = profiled.profile.ambiguous_boundary_pairs;
            profile.hbc_ambiguous_distance_over_hits = profiled.profile.ambiguous_distance_over_hits;
            profile.hbc_ambiguous_distance_under_hits = profiled.profile.ambiguous_distance_under_hits;
            profile.hbc_full_rerank_due_to_threshold = profiled.profile.full_rerank_due_to_threshold;
            profile.hbc_top_k_count = profiled.profile.top_k_count;
            profile.hbc_min_distance_gap_top_k = profiled.profile.min_distance_gap_top_k;
            profile.hbc_min_interval_gap_top_k = profiled.profile.min_interval_gap_top_k;
            profile.hbc_closest_pair_top_k = if (profiled.profile.closest_pair_top_k) |pair| mapDebugPair(pair) else null;
            profile.hbc_boundary_pair = if (profiled.profile.boundary_pair) |pair| mapDebugPair(pair) else null;
            profile.hbc_boundary_tail_error_avg = profiled.profile.boundary_tail_error_avg;
            profile.hbc_boundary_tail_error_max = profiled.profile.boundary_tail_error_max;
            profile.hbc_boundary_tail_distance_gap_avg = profiled.profile.boundary_tail_distance_gap_avg;
            profile.hbc_boundary_tail_distance_gap_min = profiled.profile.boundary_tail_distance_gap_min;
            profile.hbc_boundary_tail_distance_gap_max = profiled.profile.boundary_tail_distance_gap_max;
            profile.hbc_boundary_tail_interval_gap_avg = profiled.profile.boundary_tail_interval_gap_avg;
            profile.hbc_boundary_tail_interval_gap_min = profiled.profile.boundary_tail_interval_gap_min;
            profile.hbc_boundary_tail_interval_gap_max = profiled.profile.boundary_tail_interval_gap_max;
            profile.hbc_approx_top_count = profiled.profile.approx_top_count;
            for (profiled.profile.approx_top, 0..) |hit, i| {
                profile.hbc_approx_top[i] = mapDebugHit(hit);
            }
            profile.hbc_rerank_external_score_ns = profiled.profile.rerank_vector_load_ns;
            profile.hbc_rerank_vector_load_ns = profiled.profile.rerank_vector_load_ns;
            profile.hbc_rerank_metadata_lookup_ns = profiled.profile.rerank_metadata_lookup_ns;
            profile.hbc_rerank_metadata_vectors_loaded = profiled.profile.rerank_metadata_vectors_loaded;
            profile.hbc_rerank_artifact_key_ns = profiled.profile.rerank_artifact_key_ns;
            profile.hbc_rerank_artifact_read_ns = profiled.profile.rerank_artifact_read_ns;
            profile.hbc_rerank_artifact_decode_ns = profiled.profile.rerank_artifact_decode_ns;
            profile.hbc_rerank_artifact_distance_ns = profiled.profile.rerank_artifact_distance_ns;
            profile.hbc_rerank_lsm_cache_hits = profiled.profile.rerank_lsm_cache_hits;
            profile.hbc_rerank_lsm_cache_misses = profiled.profile.rerank_lsm_cache_misses;
            profile.hbc_rerank_vector_block_hits = profiled.profile.rerank_vector_block_hits;
            profile.hbc_rerank_vector_block_misses = profiled.profile.rerank_vector_block_misses;
            profile.hbc_rerank_vector_block_fallbacks = profiled.profile.rerank_vector_block_fallbacks;
            profile.hbc_rerank_artifact_cache_hits = profiled.profile.rerank_artifact_cache_hits;
            profile.hbc_rerank_artifact_vectors_loaded = profiled.profile.rerank_artifact_vectors_loaded;
            profile.hbc_rerank_distance_ns = profiled.profile.rerank_distance_ns;
            break :blk profiled.results;
        } else executor.hbc_search(executor.ctx, entry, hbc_req) catch |err| switch (err) {
            error.NotFound => {
                profile.returned_hit_count = 0;
                profile.total_ns = platform_time.monotonicNs() - total_start;
                return .{
                    .alloc = alloc,
                    .hits = &.{},
                    .total_hits = 0,
                    .sort_profile = vectorScoreTopKSortProfile(req, collect_sort_profile, .approximate, 0, 0, profile.total_ns),
                    .graph_results = &.{},
                };
            },
            else => return err,
        };
        profile.hbc_search_ns += platform_time.monotonicNs() - hbc_search_start;
        defer results.deinit();

        const raw_hits = results.getHits();
        profile.raw_hit_count = @intCast(raw_hits.len);
        const candidate_tail_score: ?f32 = if (raw_hits.len > 0)
            vector_mod.similarityFromDistance(raw_hits[raw_hits.len - 1].distance, entry.metric)
        else
            null;
        const candidate_window_incomplete = candidateWindowIncomplete(hbc_effective_k, bounded_full_candidate_count);
        const candidate_ceiling_reached = candidate_window >= candidate_ceiling;
        if (!candidate_window_incomplete and exhaustive_broad_live_window) {
            score_exactness = .exact;
        }
        const start: u32 = if (full_candidate_window) 0 else @min(paging.offset, @as(u32, @intCast(raw_hits.len)));
        const end: u32 = if (full_candidate_window) @intCast(raw_hits.len) else @min(start + paging.limit, @as(u32, @intCast(raw_hits.len)));

        var hits = std.ArrayListUnmanaged(types.SearchHit).empty;
        var hit_vector_ids = std.ArrayListUnmanaged(u64).empty;
        defer hit_vector_ids.deinit(alloc);
        errdefer {
            for (hits.items) |*hit| hit.deinit(alloc);
            hits.deinit(alloc);
        }

        for (raw_hits[@intCast(start)..@intCast(end)], 0..) |hit, i| {
            const result_index: usize = @as(usize, @intCast(start)) + i;
            const resolve_start = platform_time.monotonicNs();
            const doc_key = if (results.takeMetadata(result_index)) |metadata| blk: {
                profile.inline_metadata_hits += 1;
                break :blk metadata;
            } else blk: {
                if (try entry.index.getMetadata(hit.vector_id)) |metadata| {
                    profile.fetched_metadata_hits += 1;
                    break :blk metadata;
                }
                const looked_up = (try executor.lookup_doc_key(
                    executor.ctx,
                    req.index_name orelse entry.config.name,
                    hit.vector_id,
                )) orelse {
                    profile.doc_key_resolve_ns += platform_time.monotonicNs() - resolve_start;
                    continue;
                };
                profile.lookup_doc_key_hits += 1;
                break :blk looked_up;
            };
            profile.doc_key_resolve_ns += platform_time.monotonicNs() - resolve_start;
            var doc_key_owned = true;
            errdefer if (doc_key_owned) alloc.free(doc_key);

            var stored_data: ?[]u8 = null;
            var stored_data_owned = false;
            errdefer if (stored_data_owned) {
                if (stored_data) |data| alloc.free(data);
            };
            const load_stored_before_postprocess = postprocess_req.include_stored and
                !(chunk_backed and group_chunk_parents) and
                !unresolved_stored_filters;
            if (load_stored_before_postprocess) {
                const load_profile_total_before = projected_source_profile.total_ns;
                stored_data = try loadProjectedDenseDocumentWithProfile(alloc, postprocess_req, executor, doc_key, &projected_source_profile);
                stored_data_owned = true;
                profile.load_projected_document_ns += projected_source_profile.total_ns - load_profile_total_before;
            }
            try hit_vector_ids.append(alloc, hit.vector_id);
            try hits.append(alloc, .{
                .id = doc_key,
                .doc_ordinal = null,
                .score = vector_mod.similarityFromDistance(hit.distance, entry.metric),
                .distance = hit.distance,
                .stored_data = stored_data,
            });
            doc_key_owned = false;
            stored_data_owned = false;
        }
        const ordinal_lookup_start = platform_time.monotonicNs();
        try lookupDenseHitDocOrdinals(alloc, postprocess_req, executor, hit_vector_ids.items, hits.items);
        profile.doc_ordinal_lookup_ns += platform_time.monotonicNs() - ordinal_lookup_start;

        const postprocess_start = platform_time.monotonicNs();
        var candidate_postprocess_req = postprocess_req;
        if (full_candidate_window) {
            candidate_postprocess_req.offset = 0;
            candidate_postprocess_req.limit = candidate_window;
        }
        const dense_hits_total: u32 = @intCast(@min(raw_hits.len, @as(usize, std.math.maxInt(u32))));
        const dense_hits = try hits.toOwnedSlice(alloc);
        var result = try executor.postprocess(executor.ctx, alloc, candidate_postprocess_req, .{
            .alloc = alloc,
            .hits = dense_hits,
            .total_hits = dense_hits_total,
            .total_hits_relation = if (candidate_window_incomplete) .gte else .exact,
            .graph_results = &.{},
        }, chunk_backed);
        errdefer result.deinit();

        const visible_candidate_count: u32 = @intCast(@min(result.hits.len, @as(usize, std.math.maxInt(u32))));
        const needs_more_grouped_candidates = group_chunk_parents and !groupedResultHasStableRequestedPage(
            paging,
            result,
            candidate_tail_score,
            !candidate_window_incomplete,
        );
        const needs_more_visible_candidates = unresolved_stored_filters and visible_candidate_count < page_candidate_window;
        if (full_candidate_window and
            candidate_window_incomplete and
            !candidate_ceiling_reached and
            (needs_more_grouped_candidates or needs_more_visible_candidates))
        {
            result.deinit();
            const grown_window = growAdaptiveCandidateWindow(candidate_window, candidate_ceiling, page_candidate_window);
            if (grown_window == candidate_window) return error.InvalidQueryRequest;
            candidate_window = grown_window;
            continue;
        }
        if (group_chunk_parents) {
            try enforceGroupedPageBoundaryAtCandidateCeiling(
                paging,
                result,
                candidate_tail_score,
                !candidate_window_incomplete,
                candidate_ceiling_reached,
            );
        }
        if (candidate_window_incomplete) result.total_hits_relation = .gte;
        if (full_candidate_window) {
            result = try pageSearchResultInPlace(alloc, result, paging);
        }
        profile.postprocess_ns += platform_time.monotonicNs() - postprocess_start;
        if (postprocess_req.include_stored and !(chunk_backed and group_chunk_parents)) {
            const source_profile = try loadMissingProjectedDenseHitDocuments(alloc, postprocess_req, executor, result.hits);
            profile.load_projected_document_ns += source_profile.total_ns;
            projected_source_profile.requested_count += source_profile.requested_count;
            projected_source_profile.loaded_count += source_profile.loaded_count;
            projected_source_profile.batch_count += source_profile.batch_count;
            projected_source_profile.total_ns +|= source_profile.total_ns;
        }
        profile.returned_hit_count = result.total_hits;
        profile.total_ns = platform_time.monotonicNs() - total_start;
        result.sort_profile = vectorScoreTopKSortProfile(req, collect_sort_profile, score_exactness, raw_hits.len, result.hits.len, profile.total_ns);
        applyProjectedSourceLoadProfileToSortProfile(&result, projected_source_profile);
        try decorateVectorScoreOrderIfRequested(&result, req);
        if (bench_query_profile) logBenchDenseQueryProfile(req, dense, index_stats, profile);
        return result;
    }
}

fn shouldLogBenchQueryProfile() bool {
    const every = benchQueryProfileEvery() orelse return false;
    if (every == 0) return false;
    const current = bench_query_profile_counter.fetchAdd(1, .monotonic) + 1;
    return current % every == 0;
}

const DenseSearchRoute = struct {
    exact_native_filter: bool,
    name: []const u8,
    reason: []const u8,
    estimated_exact_storage_bytes: u64 = 0,
    estimated_hbc_storage_bytes: u64 = 0,
    estimated_exact_work_ns: u64 = 0,
    estimated_hbc_work_ns: u64 = 0,
};

const DenseRouteResolvedCosts = struct {
    filter_scan_ns_per_candidate: u64,
    quantized_score_ns_per_candidate: u64,
    artifact_miss_read_decode_ns_per_vector: u64,
    exact_distance_ns_per_vector: u64,
};

fn denseRouteCostOrPrior(measured: u64, prior: u64) u64 {
    return if (measured > 0) measured else prior;
}

fn resolveDenseRouteCosts(
    cost: hbc_mod.HBCIndex.DenseRouteCostSnapshot,
    vector_dims: usize,
    external_vector_storage: bool,
) DenseRouteResolvedCosts {
    const dimensions: u64 = @intCast(@max(vector_dims, 1));
    // Priors are deliberately conservative and dimension-aware. They make a
    // fresh index cost-routable immediately; each individual component is
    // replaced independently as either route supplies real observations.
    const filter_prior_ns: u64 = 64;
    const quantized_prior_ns = @max(@as(u64, 32), dimensions / 8);
    const artifact_miss_prior_ns = if (external_vector_storage)
        @max(@as(u64, 1_000), dimensions *| 8)
    else
        @max(@as(u64, 64), dimensions / 2);
    const exact_distance_prior_ns = @max(@as(u64, 32), dimensions / 4);
    const artifact_miss_permille = 1000 -| @min(cost.rerank_cache_hit_permille, 1000);
    return .{
        .filter_scan_ns_per_candidate = denseRouteCostOrPrior(cost.filter_scan_ns_per_candidate, filter_prior_ns),
        .quantized_score_ns_per_candidate = denseRouteCostOrPrior(cost.quantized_score_ns_per_candidate, quantized_prior_ns),
        .artifact_miss_read_decode_ns_per_vector = denseRouteCostOrPrior(
            cost.artifact_read_decode_ns_per_vector,
            artifact_miss_prior_ns,
        ) *| artifact_miss_permille / 1000,
        .exact_distance_ns_per_vector = denseRouteCostOrPrior(cost.exact_distance_ns_per_vector, exact_distance_prior_ns),
    };
}

fn denseSearchRoute(
    positive_filter: bool,
    effective_candidate_count: usize,
    active_count: u64,
    vector_dims: usize,
    requested_results: u32,
    search_width: u32,
    leaf_size: u32,
    external_vector_storage: bool,
    exact_executor_available: bool,
) DenseSearchRoute {
    return denseSearchRouteWithCosts(
        positive_filter,
        effective_candidate_count,
        active_count,
        vector_dims,
        requested_results,
        search_width,
        leaf_size,
        external_vector_storage,
        exact_executor_available,
        null,
        false,
        1000,
    );
}

fn denseSearchRouteWithCosts(
    positive_filter: bool,
    effective_candidate_count: usize,
    active_count: u64,
    vector_dims: usize,
    requested_results: u32,
    search_width: u32,
    leaf_size: u32,
    external_vector_storage: bool,
    exact_executor_available: bool,
    measured: ?hbc_mod.HBCIndex.DenseRouteCostSnapshot,
    hbc_cache_pressured: bool,
    hbc_cache_residency_permille: u64,
) DenseSearchRoute {
    if (!positive_filter) return .{
        .exact_native_filter = false,
        .name = "hbc",
        .reason = "no_native_filter",
    };
    if (effective_candidate_count == 0) return .{
        .exact_native_filter = false,
        .name = "hbc",
        .reason = "empty_native_filter",
    };
    const work_budget = selectiveExactCandidateWorkBudget(vector_dims);
    const dimensions: u64 = @intCast(@max(vector_dims, 1));
    const candidate_count: u64 = @intCast(effective_candidate_count);
    // External exact scoring reads one f32 artifact plus its lookup/key
    // overhead. The built-in scorer reads the HBC-resident f32 payload.
    const exact_lookup_overhead: u64 = if (external_vector_storage) 64 else 8;
    const exact_bytes_per_candidate = dimensions *| @sizeOf(f32) +| exact_lookup_overhead;
    const exact_storage_bytes = candidate_count *| exact_bytes_per_candidate;

    // Estimate how many approximate candidates HBC must inspect to obtain k
    // eligible hits. This expresses filter selectivity as storage work rather
    // than a discontinuous active_count/100 policy threshold.
    const population_per_eligible = std.math.divCeil(u64, active_count, candidate_count) catch std.math.maxInt(u64);
    const filter_adjusted_candidates = @as(u64, requested_results) *| population_per_eligible;
    const width_candidates = @as(u64, search_width) *| @as(u64, @max(leaf_size, 1));
    const hbc_candidates = @min(active_count, @max(filter_adjusted_candidates, width_candidates));
    const quantized_bytes_per_candidate = dimensions +| 24;
    const quantized_memory_bytes = hbc_candidates *| quantized_bytes_per_candidate;
    // Normalize resident routing bandwidth only when exact scoring crosses
    // into the external artifact store. Built-in indexes keep both their
    // exact and quantized payloads in HBC, so their comparison stays in raw
    // resident bytes.
    const quantized_storage_work_bytes = if (external_vector_storage)
        std.math.divCeil(
            u64,
            quantized_memory_bytes,
            hbc_quantized_memory_to_storage_work_ratio,
        ) catch std.math.maxInt(u64)
    else
        quantized_memory_bytes;
    const rerank_candidates = @min(hbc_candidates, @as(u64, requested_results) *| 4);
    const hbc_storage_bytes = quantized_storage_work_bytes +|
        rerank_candidates *| (dimensions *| @sizeOf(f32) +| 64);

    if (measured) |cost| {
        const resolved_cost = resolveDenseRouteCosts(cost, vector_dims, external_vector_storage);
        const filter_ns = resolved_cost.filter_scan_ns_per_candidate;
        const artifact_ns = resolved_cost.artifact_miss_read_decode_ns_per_vector;
        const exact_work_ns = candidate_count *|
            (filter_ns +| artifact_ns +| resolved_cost.exact_distance_ns_per_vector);
        var hbc_work_ns = hbc_candidates *|
            (filter_ns +| resolved_cost.quantized_score_ns_per_candidate) +|
            rerank_candidates *| (artifact_ns +| resolved_cost.exact_distance_ns_per_vector);
        if (hbc_cache_pressured) hbc_work_ns +|= hbc_work_ns / 4;
        if (hbc_cache_residency_permille < 250) hbc_work_ns +|= hbc_work_ns / 10;

        const exact_allowed = effective_candidate_count <= work_budget;
        var choose_exact = exact_allowed and exact_work_ns <= hbc_work_ns;
        switch (cost.last_route) {
            .exact => if (exact_allowed and hbc_work_ns *| 5 >= exact_work_ns *| 4) {
                choose_exact = true;
            },
            .hbc => if (exact_allowed and exact_work_ns != hbc_work_ns and exact_work_ns *| 5 > hbc_work_ns *| 4) {
                choose_exact = false;
            },
            .unknown => {},
        }
        const has_observations = cost.exact_observations > 0 or cost.hbc_observations > 0;
        return .{
            .exact_native_filter = choose_exact,
            .name = if (choose_exact) "exact_native_filter" else "hbc",
            .reason = if (!exact_allowed)
                if (has_observations) "exact_measured_work_budget_exceeded" else "exact_prior_work_budget_exceeded"
            else if (choose_exact)
                if (has_observations) "exact_measured_work_lower" else "exact_prior_work_lower"
            else if (has_observations)
                "hbc_measured_work_lower"
            else
                "hbc_prior_work_lower",
            .estimated_exact_storage_bytes = exact_storage_bytes,
            .estimated_hbc_storage_bytes = hbc_storage_bytes,
            .estimated_exact_work_ns = exact_work_ns,
            .estimated_hbc_work_ns = hbc_work_ns,
        };
    }

    if (effective_candidate_count <= work_budget and exact_storage_bytes <= hbc_storage_bytes) {
        return .{
            .exact_native_filter = true,
            .name = "exact_native_filter",
            .reason = if (exact_executor_available)
                "exact_storage_work_lower"
            else
                "exact_storage_work_lower_builtin",
            .estimated_exact_storage_bytes = exact_storage_bytes,
            .estimated_hbc_storage_bytes = hbc_storage_bytes,
        };
    }
    if (effective_candidate_count > work_budget) {
        return .{
            .exact_native_filter = false,
            .name = "hbc",
            .reason = "exact_storage_work_budget_exceeded",
            .estimated_exact_storage_bytes = exact_storage_bytes,
            .estimated_hbc_storage_bytes = hbc_storage_bytes,
        };
    }
    return .{
        .exact_native_filter = false,
        .name = "hbc",
        .reason = "hbc_storage_work_lower",
        .estimated_exact_storage_bytes = exact_storage_bytes,
        .estimated_hbc_storage_bytes = hbc_storage_bytes,
    };
}

fn selectiveExactCandidateWorkBudget(vector_dims: usize) usize {
    const dimensions = @max(vector_dims, 1);
    const component_limited = @max(default_selective_exact_component_budget / dimensions, 1);
    return @min(default_selective_exact_candidate_budget, component_limited);
}

test "dense search route reports exact native filter budget decisions" {
    const no_filter = denseSearchRoute(false, 0, 1_000_000, 768, 100, 8, 128, true, false);
    try std.testing.expect(!no_filter.exact_native_filter);
    try std.testing.expectEqualStrings("hbc", no_filter.name);
    try std.testing.expectEqualStrings("no_native_filter", no_filter.reason);

    // At 50k/1%, exact reads substantially less full-vector storage than HBC
    // must inspect after filter rejection.
    const within_budget = denseSearchRoute(true, 500, 50_000, 768, 100, 8, 128, true, true);
    try std.testing.expect(within_budget.exact_native_filter);
    try std.testing.expectEqualStrings("exact_native_filter", within_budget.name);
    try std.testing.expectEqualStrings("exact_storage_work_lower", within_budget.reason);
    try std.testing.expect(within_budget.estimated_exact_storage_bytes < within_budget.estimated_hbc_storage_bytes);

    const builtin_fallback = denseSearchRoute(true, 500, 50_000, 768, 100, 8, 128, false, false);
    try std.testing.expect(builtin_fallback.exact_native_filter);
    try std.testing.expectEqualStrings("exact_storage_work_lower_builtin", builtin_fallback.reason);

    // At 700k/1%, the full-vector artifact work is now higher, so the same
    // percentage does not force exact scoring through a policy cliff.
    const large_one_percent = denseSearchRoute(true, 7_000, 700_000, 768, 100, 8, 128, true, true);
    try std.testing.expect(!large_one_percent.exact_native_filter);
    try std.testing.expectEqualStrings("hbc_storage_work_lower", large_one_percent.reason);
    try std.testing.expect(large_one_percent.estimated_hbc_storage_bytes < large_one_percent.estimated_exact_storage_bytes);

    // Production hybrid planning widens HBC with corpus scale. Resident
    // quantized inspection must not be priced like 274 MB of external reads;
    // at 1M/1%, ten bounded exact artifact batches are costlier than HBC.
    const production_million_one_percent = denseSearchRoute(true, 10_000, 1_000_000, 768, 100, 336, 1024, true, true);
    try std.testing.expect(!production_million_one_percent.exact_native_filter);
    try std.testing.expectEqualStrings("hbc_storage_work_lower", production_million_one_percent.reason);
    try std.testing.expect(production_million_one_percent.estimated_hbc_storage_bytes < production_million_one_percent.estimated_exact_storage_bytes);

    const ten_percent = denseSearchRoute(true, 5_000, 50_000, 768, 100, 8, 128, true, true);
    try std.testing.expect(!ten_percent.exact_native_filter);
    try std.testing.expectEqualStrings("hbc_storage_work_lower", ten_percent.reason);

    const oversized_one_percent = denseSearchRoute(true, 1_000_000, 100_000_000, 768, 100, 8, 128, true, true);
    try std.testing.expect(!oversized_one_percent.exact_native_filter);
    try std.testing.expectEqualStrings("exact_storage_work_budget_exceeded", oversized_one_percent.reason);

    try std.testing.expectEqual(@as(usize, 32 * 1024), selectiveExactCandidateWorkBudget(2));
    try std.testing.expectEqual(@as(usize, 16 * 1024), selectiveExactCandidateWorkBudget(1024));
    try std.testing.expectEqual(@as(usize, 1), selectiveExactCandidateWorkBudget(std.math.maxInt(usize)));
}

test "dense search route uses measured per-index costs pressure and hysteresis" {
    const cold_50k = denseSearchRouteWithCosts(true, 500, 50_000, 768, 100, 8, 128, true, true, .{}, false, 1000);
    try std.testing.expect(cold_50k.exact_native_filter);
    try std.testing.expectEqualStrings("exact_prior_work_lower", cold_50k.reason);
    try std.testing.expect(cold_50k.estimated_exact_work_ns > 0);
    try std.testing.expect(cold_50k.estimated_hbc_work_ns > 0);

    const cold_1m = denseSearchRouteWithCosts(true, 10_000, 1_000_000, 768, 100, 336, 1024, true, true, .{}, false, 1000);
    try std.testing.expect(!cold_1m.exact_native_filter);
    try std.testing.expectEqualStrings("hbc_prior_work_lower", cold_1m.reason);

    var costs = hbc_mod.HBCIndex.DenseRouteCostSnapshot{
        .filter_scan_ns_per_candidate = 1,
        .quantized_score_ns_per_candidate = 100,
        .artifact_read_decode_ns_per_vector = 10,
        .exact_distance_ns_per_vector = 10,
        .rerank_cache_hit_permille = 0,
        .exact_observations = 2,
        .hbc_observations = 2,
        .last_route = .unknown,
    };
    const exact = denseSearchRouteWithCosts(true, 500, 50_000, 768, 100, 8, 128, true, true, costs, false, 1000);
    try std.testing.expect(exact.exact_native_filter);
    try std.testing.expectEqualStrings("exact_measured_work_lower", exact.reason);
    try std.testing.expect(exact.estimated_exact_work_ns < exact.estimated_hbc_work_ns);

    costs.quantized_score_ns_per_candidate = 1;
    costs.artifact_read_decode_ns_per_vector = 1000;
    costs.exact_distance_ns_per_vector = 100;
    const hbc = denseSearchRouteWithCosts(true, 500, 50_000, 768, 100, 8, 128, true, true, costs, false, 1000);
    try std.testing.expect(!hbc.exact_native_filter);
    try std.testing.expectEqualStrings("hbc_measured_work_lower", hbc.reason);

    const pressured = denseSearchRouteWithCosts(true, 500, 50_000, 768, 100, 8, 128, true, true, costs, true, 1000);
    try std.testing.expect(pressured.estimated_hbc_work_ns > hbc.estimated_hbc_work_ns);

    costs.last_route = .exact;
    costs.artifact_read_decode_ns_per_vector = 50;
    costs.exact_distance_ns_per_vector = 10;
    const sticky_exact = denseSearchRouteWithCosts(true, 500, 50_000, 768, 100, 8, 128, true, true, costs, false, 1000);
    try std.testing.expect(sticky_exact.exact_native_filter);
}

fn pagingCandidateWindow(paging: ComponentPaging) u32 {
    return paging.offset +| paging.limit;
}

fn scoreOrderCandidateWindowK(requested_k: u32, paging: ComponentPaging) u32 {
    return @max(requested_k, pagingCandidateWindow(paging));
}

fn scoreOrderWindowTotalHitsRelation(effective_k: u32, bounded_candidate_count: u64, raw_hit_count: usize) types.TotalHitsRelation {
    if (@as(u64, effective_k) < bounded_candidate_count and raw_hit_count >= @as(usize, @intCast(effective_k))) return .gte;
    return .exact;
}

fn initialAdaptiveCandidateWindow(candidate_ceiling: u32, paging: ComponentPaging) u32 {
    if (candidate_ceiling == 0) return 0;
    const overfetch_window = @max(paging.limit *| 32, @as(u32, 1024));
    return @min(candidate_ceiling, @max(overfetch_window, pagingCandidateWindow(paging)));
}

fn growAdaptiveCandidateWindow(current: u32, candidate_ceiling: u32, requested_visible_end: u32) u32 {
    if (current >= candidate_ceiling) return current;
    const grown = @max(current +| 1, @max(current *| 2, requested_visible_end));
    return @min(candidate_ceiling, grown);
}

fn candidateWindowIncomplete(candidate_window: u32, bounded_full_candidate_count: u32) bool {
    return candidate_window < bounded_full_candidate_count;
}

/// Return whether adaptive collection has discovered the requested component
/// page of groups. Nested `max_chunks_per_parent` is an output cap, not a fill
/// target: a group may legitimately have fewer matching descendants, and
/// requiring every group to reach the cap would force collection to exhaust
/// the index.
fn groupedResultHasRequestedPage(paging: ComponentPaging, result: types.SearchResult) bool {
    if (paging.limit == 0) return true;
    const available: u32 = @intCast(@min(result.hits.len, @as(usize, std.math.maxInt(u32))));
    const start = @min(paging.offset, available);
    const end = @min(start +| paging.limit, available);
    return end - start == paging.limit;
}

/// Prove that unseen candidates cannot change the requested grouped page.
/// Raw text/vector streams use implementation-specific tie breakers, while
/// grouped source hits use their public IDs. A full-looking page is therefore
/// not stable until the raw candidate score has moved strictly below its last
/// visible group, or until the candidate stream is exhausted.
fn groupedResultHasStableRequestedPage(
    paging: ComponentPaging,
    result: types.SearchResult,
    candidate_tail_score: ?f32,
    candidates_exhausted: bool,
) bool {
    if (!groupedResultHasRequestedPage(paging, result)) return false;
    if (candidates_exhausted or paging.limit == 0) return true;

    const boundary_index: usize = @intCast((paging.offset +| paging.limit) - 1);
    if (boundary_index >= result.hits.len) return false;
    const boundary_score = result.hits[boundary_index].score orelse return false;
    const tail_score = candidate_tail_score orelse return false;
    return tail_score < boundary_score;
}

/// A bounded adaptive query may return an explicitly inexact short page, but
/// it must never return a full page whose deterministic public-ID tie order is
/// still unknown. Fail closed when the safety budget prevents that proof.
fn enforceGroupedPageBoundaryAtCandidateCeiling(
    paging: ComponentPaging,
    result: types.SearchResult,
    candidate_tail_score: ?f32,
    candidates_exhausted: bool,
    candidate_ceiling_reached: bool,
) !void {
    if (!candidate_ceiling_reached or candidates_exhausted) return;
    if (!groupedResultHasRequestedPage(paging, result)) return;
    if (groupedResultHasStableRequestedPage(paging, result, candidate_tail_score, false)) return;
    return error.QueryCandidateBudgetExceeded;
}

test "adaptive candidate window covers requested offset page and grows bounded" {
    const paging = ComponentPaging{ .offset = 1024, .limit = 1 };
    try std.testing.expectEqual(@as(u32, 1025), scoreOrderCandidateWindowK(10, paging));
    try std.testing.expectEqual(@as(u32, 4096), scoreOrderCandidateWindowK(4096, paging));
    try std.testing.expectEqual(std.math.maxInt(u32), scoreOrderCandidateWindowK(10, .{
        .offset = std.math.maxInt(u32),
        .limit = 1,
    }));
    try std.testing.expectEqual(types.TotalHitsRelation.gte, scoreOrderWindowTotalHitsRelation(2, 3, 2));
    try std.testing.expectEqual(types.TotalHitsRelation.exact, scoreOrderWindowTotalHitsRelation(2, 3, 1));
    try std.testing.expectEqual(types.TotalHitsRelation.exact, scoreOrderWindowTotalHitsRelation(3, 3, 3));
    try std.testing.expectEqual(@as(u32, 1025), initialAdaptiveCandidateWindow(2000, paging));
    try std.testing.expectEqual(@as(u32, 2000), growAdaptiveCandidateWindow(1025, 2000, 1025));
    try std.testing.expect(candidateWindowIncomplete(1025, 2000));
    try std.testing.expect(!candidateWindowIncomplete(2000, 2000));
    try std.testing.expectEqual(@as(u32, 7), initialAdaptiveCandidateWindow(7, paging));

    // Group collection starts with an overfetch window and may grow it again.
    // Search width must be resolved from each effective HBC k, not the much
    // smaller user-visible page size.
    const stats = testIndexStats(1_000_000, 17_591, 128);
    const initial_k = initialAdaptiveCandidateWindow(10_000, .{ .offset = 0, .limit = 1 });
    const grown_k = growAdaptiveCandidateWindow(initial_k, 10_000, 1);
    const page_width = resolveSearchWidth(1, 0.0, stats);
    const initial_width = resolveSearchWidth(initial_k, 0.0, stats);
    const grown_width = resolveSearchWidth(grown_k, 0.0, stats);
    try std.testing.expect(page_width < initial_width);
    try std.testing.expect(initial_width < grown_width);
}

test "grouped result page satisfaction treats nested match count as a maximum" {
    var first_chunks = [_]types.ChunkHit{
        .{ .id = @constCast("chunk-1") },
        .{ .id = @constCast("chunk-2") },
    };
    var second_chunks = [_]types.ChunkHit{
        .{ .id = @constCast("chunk-3") },
    };
    var hits = [_]types.SearchHit{
        .{ .id = @constCast("source-1"), .score = 2, .chunk_hits = &first_chunks },
        .{ .id = @constCast("source-2"), .score = 1, .chunk_hits = &second_chunks },
    };
    const result = types.SearchResult{
        .alloc = std.testing.allocator,
        .hits = &hits,
        .total_hits = 2,
        .graph_results = &.{},
    };
    try std.testing.expect(groupedResultHasRequestedPage(.{ .offset = 0, .limit = 2 }, result));
    try std.testing.expect(groupedResultHasRequestedPage(.{ .offset = 0, .limit = 1 }, result));
    try std.testing.expect(!groupedResultHasRequestedPage(.{ .offset = 1, .limit = 2 }, result));

    try std.testing.expect(groupedResultHasStableRequestedPage(.{ .offset = 0, .limit = 2 }, result, 0.5, false));
    try std.testing.expect(!groupedResultHasStableRequestedPage(.{ .offset = 0, .limit = 2 }, result, 1, false));
    try std.testing.expect(groupedResultHasStableRequestedPage(.{ .offset = 0, .limit = 2 }, result, 1, true));
    try std.testing.expect(!groupedResultHasStableRequestedPage(.{ .offset = 1, .limit = 2 }, result, 0.5, false));

    try std.testing.expectError(error.QueryCandidateBudgetExceeded, enforceGroupedPageBoundaryAtCandidateCeiling(
        .{ .offset = 0, .limit = 2 },
        result,
        1,
        false,
        true,
    ));
    try enforceGroupedPageBoundaryAtCandidateCeiling(.{ .offset = 0, .limit = 2 }, result, 0.5, false, true);
    try enforceGroupedPageBoundaryAtCandidateCeiling(.{ .offset = 0, .limit = 2 }, result, 1, true, true);
}

fn exactScoreNativeDenseFilter(
    alloc: Allocator,
    entry: *index_manager_mod.IndexManager.DenseIndex,
    req: vectorindex_mod.SearchRequest,
) !dense_exact.SearchOutcome {
    try checkVectorSearchCancelled(req);
    const prepare_start_ns = platform_time.monotonicNs();
    var candidates = try dense_exact.CandidateDifference.init(alloc, req.filter_ids, req.exclude_ids);
    defer candidates.deinit();
    const unique_candidate_ids = candidates.values;
    var exact_profile: dense_exact.SearchOutcome.Profile = .{
        .candidate_count = @intCast(unique_candidate_ids.len),
        .candidate_prepare_ns = platform_time.monotonicNs() - prepare_start_ns,
        .batch_count = if (unique_candidate_ids.len == 0) 0 else 1,
        .max_batch_size = @intCast(unique_candidate_ids.len),
        .workspace_bytes = @as(u64, entry.dims) *| @sizeOf(f32),
    };

    var results = try vectorindex_mod.SearchResults.initCapacity(
        alloc,
        req.k,
        req.k,
        @min(req.k, unique_candidate_ids.len),
    );
    errdefer results.deinit();

    var txn = try entry.index.beginReadTxn();
    defer txn.abort();
    var vector_cursor = entry.index.openNamespacedCursor(alloc, &txn, .vecs) catch |err| switch (err) {
        error.Unsupported => null,
        else => return err,
    };
    defer if (vector_cursor) |*cursor| cursor.close();

    const candidate_metadata = try alloc.alloc(
        ?[]const u8,
        if (req.filter_prefix.len > 0) unique_candidate_ids.len else 0,
    );
    defer alloc.free(candidate_metadata);
    if (candidate_metadata.len > 0) {
        const metadata_start_ns = platform_time.monotonicNs();
        @memset(candidate_metadata, null);
        var metadata_start: usize = 0;
        while (metadata_start < unique_candidate_ids.len) {
            try checkVectorSearchCancelled(req);
            const metadata_end = @min(metadata_start + exact_native_filter_metadata_batch_size, unique_candidate_ids.len);
            try entry.index.getMetadataManySortedInTxn(
                &txn,
                unique_candidate_ids[metadata_start..metadata_end],
                candidate_metadata[metadata_start..metadata_end],
            );
            metadata_start = metadata_end;
        }
        try checkVectorSearchCancelled(req);
        exact_profile.metadata_lookup_ns = platform_time.monotonicNs() - metadata_start_ns;
    }

    const vector_scratch = try alloc.alloc(f32, entry.dims);
    defer alloc.free(vector_scratch);
    const query_measure = vector_mod.norm(req.query);
    var vectors_scored: u64 = 0;

    for (unique_candidate_ids, 0..) |vector_id, i| {
        if (i % exact_native_filter_cancellation_stride == 0) try checkVectorSearchCancelled(req);
        if (req.filter_prefix.len > 0) {
            const metadata = candidate_metadata[i] orelse continue;
            if (!std.mem.startsWith(u8, metadata, req.filter_prefix)) continue;
        }
        const vector = (if (vector_cursor) |*cursor|
            entry.index.getVectorViewOrScratchWithCursor(cursor, vector_id, vector_scratch)
        else
            entry.index.getVectorViewOrScratch(&txn, vector_id, vector_scratch)) catch |err| switch (err) {
            error.NotFound => continue,
            else => return err,
        };
        if (vector.len != req.query.len) return error.DimensionMismatch;

        vectors_scored += 1;
        const distance_start_ns = platform_time.monotonicNs();
        const distance = vector_mod.distanceToQuery(req.query, query_measure, vector, entry.metric);
        exact_profile.distance_ns += platform_time.monotonicNs() - distance_start_ns;
        if (!std.math.isFinite(distance)) continue;
        if (req.distance_over) |threshold| {
            if (distance <= threshold) continue;
        }
        if (req.distance_under) |threshold| {
            if (distance >= threshold) continue;
        }
        results.addResult(vector_id, distance, 0);
    }
    results.sort();
    return .{
        .results = results,
        .vectors_scored = vectors_scored,
        .profile = exact_profile,
    };
}

inline fn checkVectorSearchCancelled(req: vectorindex_mod.SearchRequest) !void {
    if (req.cancellation) |cancellation| {
        if (cancellation.isCancelled()) return error.Cancelled;
    }
}

test "built-in exact dense scorer filters metadata before vector reads" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/builtin-exact-prefix", .{tmp.sub_path});
    defer alloc.free(path);
    const path_z = try alloc.dupeZ(u8, path);
    defer alloc.free(path_z);

    var index = try hbc_mod.HBCIndex.open(alloc, path_z.ptr, .{
        .dims = 2,
        .leaf_size = 2,
        .branching_factor = 2,
    });
    var index_owned = true;
    defer if (index_owned) index.close();
    try index.bulkBuildWithMetadata(&.{
        .{ .vector_id = 1, .vector = &.{ 0.0, 0.0 }, .metadata = "doc:keep:a" },
        .{ .vector_id = 2, .vector = &.{ 1.0, 0.0 }, .metadata = "doc:keep:b" },
        .{ .vector_id = 3, .vector = &.{ 2.0, 0.0 }, .metadata = "doc:drop:a" },
        .{ .vector_id = 4, .vector = &.{ 3.0, 0.0 }, .metadata = "doc:drop:b" },
    });

    var apply_mutex = std.atomic.Mutex.unlocked;
    var entry = index_manager_mod.IndexManager.DenseIndex{
        .apply_mutex = &apply_mutex,
        .config = .{ .name = "dense", .kind = .dense_vector, .config_json = "{}" },
        .field_name = @constCast("embedding"),
        .dims = 2,
        .metric = .l2_squared,
        .external = false,
        .chunk_name = null,
        .embedding_name = null,
        .index = index,
    };
    index_owned = false;
    defer entry.index.close();

    const VectorLoadCounter = struct {
        count: usize = 0,

        fn onLoad(ctx_ptr: ?*anyopaque, _: *hbc_mod.HBCIndex, _: u64) void {
            const self: *@This() = @ptrCast(@alignCast(ctx_ptr.?));
            self.count += 1;
        }
    };
    var counter = VectorLoadCounter{};
    hbc_mod.setTestGetVectorViewOrScratchHook(&counter, VectorLoadCounter.onLoad);
    defer hbc_mod.setTestGetVectorViewOrScratchHook(null, null);

    var outcome = try exactScoreNativeDenseFilter(alloc, &entry, .{
        .query = &.{ 0.0, 0.0 },
        .k = 4,
        .filter_prefix = "doc:keep:",
        .filter_ids = &.{ 4, 2, 3, 1 },
    });
    defer outcome.results.deinit();

    try std.testing.expectEqual(@as(u64, 2), outcome.vectors_scored);
    try std.testing.expectEqual(@as(usize, 2), counter.count);
    const hits = outcome.results.getHits();
    try std.testing.expectEqual(@as(usize, 2), hits.len);
    try std.testing.expectEqual(@as(u64, 1), hits[0].vector_id);
    try std.testing.expectEqual(@as(u64, 2), hits[1].vector_id);
}

test "one percent filtered route preserves exact recall with candidate-linear IO" {
    const alloc = std.testing.allocator;
    const candidate_count: usize = 1100;
    const dims: usize = 8;
    const result_count: usize = 10;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/selective-exact-recall", .{tmp.sub_path});
    defer alloc.free(path);
    const path_z = try alloc.dupeZ(u8, path);
    defer alloc.free(path_z);

    var index = try hbc_mod.HBCIndex.open(alloc, path_z.ptr, .{
        .dims = dims,
        .leaf_size = 64,
        .branching_factor = 8,
    });
    var index_owned = true;
    defer if (index_owned) index.close();

    const vectors = try alloc.alloc(f32, candidate_count * dims);
    defer alloc.free(vectors);
    @memset(vectors, 0);
    const items = try alloc.alloc(hbc_mod.BatchInsertItem, candidate_count);
    defer alloc.free(items);
    const filter_ids = try alloc.alloc(u64, candidate_count);
    defer alloc.free(filter_ids);
    for (items, 0..) |*item, i| {
        const vector_id: u64 = @intCast(i + 1);
        const vector = vectors[i * dims ..][0..dims];
        vector[0] = @floatFromInt(vector_id);
        item.* = .{ .vector_id = vector_id, .vector = vector };
        filter_ids[i] = vector_id;
    }
    try index.bulkBuildWithMetadata(items);

    var apply_mutex = std.atomic.Mutex.unlocked;
    var entry = index_manager_mod.IndexManager.DenseIndex{
        .apply_mutex = &apply_mutex,
        .config = .{ .name = "dense", .kind = .dense_vector, .config_json = "{}" },
        .field_name = @constCast("embedding"),
        .dims = dims,
        .metric = .l2_squared,
        .external = false,
        .chunk_name = null,
        .embedding_name = null,
        .index = index,
    };
    index_owned = false;
    defer entry.index.close();

    const route = denseSearchRoute(true, candidate_count, candidate_count * 100, dims, result_count, 32, 64, false, false);
    try std.testing.expect(route.exact_native_filter);
    try std.testing.expectEqualStrings("exact_storage_work_lower_builtin", route.reason);

    const VectorLoadCounter = struct {
        count: usize = 0,
        cancel_after: usize = 0,
        cancellation: ?*std.atomic.Value(bool) = null,

        fn onLoad(ctx_ptr: ?*anyopaque, _: *hbc_mod.HBCIndex, _: u64) void {
            const self: *@This() = @ptrCast(@alignCast(ctx_ptr.?));
            self.count += 1;
            if (self.cancel_after > 0 and self.count >= self.cancel_after) {
                self.cancellation.?.store(true, .release);
            }
        }
    };
    var counter = VectorLoadCounter{};
    hbc_mod.setTestGetVectorViewOrScratchHook(&counter, VectorLoadCounter.onLoad);
    defer hbc_mod.setTestGetVectorViewOrScratchHook(null, null);

    var query = [_]f32{0} ** dims;
    query[0] = @floatFromInt(candidate_count);
    var outcome = try exactScoreNativeDenseFilter(alloc, &entry, .{
        .query = &query,
        .k = result_count,
        .filter_ids = filter_ids,
    });
    defer outcome.results.deinit();

    try std.testing.expectEqual(@as(u64, candidate_count), outcome.vectors_scored);
    try std.testing.expectEqual(candidate_count, counter.count);
    const hits = outcome.results.getHits();
    try std.testing.expectEqual(result_count, hits.len);
    for (hits, 0..) |hit, rank| {
        try std.testing.expectEqual(@as(u64, @intCast(candidate_count - rank)), hit.vector_id);
    }

    var cancellation = std.atomic.Value(bool).init(false);
    counter = .{
        .cancel_after = exact_native_filter_cancellation_stride,
        .cancellation = &cancellation,
    };
    try std.testing.expectError(error.Cancelled, exactScoreNativeDenseFilter(alloc, &entry, .{
        .query = &query,
        .k = result_count,
        .filter_ids = filter_ids,
        .cancellation = vectorindex_mod.CancellationToken.fromAtomic(&cancellation),
    }));
    try std.testing.expectEqual(exact_native_filter_cancellation_stride, counter.count);
}

test "one percent native filter routes through integrated dense search exactly" {
    const alloc = std.testing.allocator;
    const active_count: usize = 110_000;
    const candidate_count: usize = active_count / 100;
    const dims: usize = 2;
    const result_count: usize = 10;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/integrated-selective-exact", .{tmp.sub_path});
    defer alloc.free(path);
    const path_z = try alloc.dupeZ(u8, path);
    defer alloc.free(path_z);

    var index = try hbc_mod.HBCIndex.open(alloc, path_z.ptr, .{
        .dims = dims,
        .leaf_size = 128,
        .branching_factor = 16,
    });
    var index_owned = true;
    defer if (index_owned) index.close();

    const vectors = try alloc.alloc(f32, active_count * dims);
    defer alloc.free(vectors);
    @memset(vectors, 0);
    const items = try alloc.alloc(hbc_mod.BatchInsertItem, active_count);
    defer alloc.free(items);
    const filter_ids = try alloc.alloc(u64, candidate_count);
    defer alloc.free(filter_ids);
    for (items, 0..) |*item, i| {
        const vector_id: u64 = @intCast(i + 1);
        const vector = vectors[i * dims ..][0..dims];
        vector[0] = @floatFromInt(vector_id);
        item.* = .{ .vector_id = vector_id, .vector = vector, .metadata = "doc" };
        if (i >= active_count - candidate_count) filter_ids[i - (active_count - candidate_count)] = vector_id;
    }
    try index.bulkBuildWithMetadata(items);

    var apply_mutex = std.atomic.Mutex.unlocked;
    var entry = index_manager_mod.IndexManager.DenseIndex{
        .apply_mutex = &apply_mutex,
        .config = .{ .name = "dense", .kind = .dense_vector, .config_json = "{}" },
        .field_name = @constCast("embedding"),
        .dims = dims,
        .metric = .l2_squared,
        .external = false,
        .chunk_name = null,
        .embedding_name = null,
        .index = index,
    };
    index_owned = false;
    defer entry.index.close();

    const Harness = struct {
        entry: *index_manager_mod.IndexManager.DenseIndex,

        fn self(ctx: ?*anyopaque) *@This() {
            return @ptrCast(@alignCast(ctx.?));
        }
        fn textIndex(_: ?*anyopaque, _: ?[]const u8) anyerror!?*index_manager_mod.IndexManager.TextIndex {
            return null;
        }
        fn denseIndex(ctx: ?*anyopaque, _: ?[]const u8) anyerror!?*index_manager_mod.IndexManager.DenseIndex {
            return self(ctx).entry;
        }
        fn unexpectedDocKey(_: ?*anyopaque, _: []const u8, _: u64) anyerror!?[]u8 {
            return error.UnexpectedTestCall;
        }
        fn unexpectedVectorId(_: ?*anyopaque, _: []const u8, _: []const u8) anyerror!?u64 {
            return error.UnexpectedTestCall;
        }
        fn unexpectedLoad(_: ?*anyopaque, _: Allocator, _: types.SearchRequest, _: []const u8) anyerror![]u8 {
            return error.UnexpectedTestCall;
        }
        fn unexpectedHbc(_: ?*anyopaque, _: *index_manager_mod.IndexManager.DenseIndex, _: vectorindex_mod.SearchRequest) anyerror!vectorindex_mod.SearchResults {
            return error.UnexpectedHbcRoute;
        }
        fn unexpectedHbcProfiled(_: ?*anyopaque, _: *index_manager_mod.IndexManager.DenseIndex, _: vectorindex_mod.SearchRequest) anyerror!vectorindex_mod.ProfiledSearchResults {
            return error.UnexpectedHbcRoute;
        }
        fn postprocess(_: ?*anyopaque, _: Allocator, _: types.SearchRequest, raw: types.SearchResult, _: bool) anyerror!types.SearchResult {
            return raw;
        }
    };
    var harness = Harness{ .entry = &entry };
    const executor = DenseSearchExecutor{
        .ctx = &harness,
        .text_index_entry = Harness.textIndex,
        .dense_index = Harness.denseIndex,
        .lookup_doc_key = Harness.unexpectedDocKey,
        .lookup_vector_id = Harness.unexpectedVectorId,
        .load_projected_document = Harness.unexpectedLoad,
        .hbc_search = Harness.unexpectedHbc,
        .hbc_search_profiled = Harness.unexpectedHbcProfiled,
        .postprocess = Harness.postprocess,
    };

    var query = [_]f32{ 0, 0 };
    query[0] = @floatFromInt(active_count);
    var profiled = try searchDenseProfiled(alloc, .{
        .index_name = "dense",
        .limit = result_count,
        .include_stored = false,
        .profile = true,
        .filter_ids = filter_ids,
    }, .{
        .vector = &query,
        .k = result_count,
    }, executor);
    defer profiled.result.deinit();

    try std.testing.expectEqualStrings("exact_native_filter", profiled.profile.search_route);
    try std.testing.expectEqualStrings("exact_prior_work_lower", profiled.profile.route_reason);
    try std.testing.expectEqual(@as(u64, candidate_count), profiled.profile.hbc_exact_vectors_scored);
    try std.testing.expectEqual(result_count, profiled.result.hits.len);
    try std.testing.expectEqualStrings("exact", profiled.result.sort_profile.?.exactness);
}

fn countActiveDenseVectorIdsAlloc(
    alloc: Allocator,
    entry: *index_manager_mod.IndexManager.DenseIndex,
    vector_ids: []const u64,
) !u32 {
    if (vector_ids.len == 0) return 0;

    var sorted = try alloc.dupe(u64, vector_ids);
    defer alloc.free(sorted);
    std.mem.sort(u64, sorted, {}, u64LessThan);
    const unique = sorted[0..uniqueSortedU64(sorted)];

    const metadata = try alloc.alloc(?[]const u8, unique.len);
    defer alloc.free(metadata);
    @memset(metadata, null);

    var txn = try entry.index.beginReadTxn();
    defer txn.abort();
    try entry.index.getMetadataManySortedInTxn(&txn, unique, metadata);

    var count: u32 = 0;
    for (metadata) |maybe_metadata| {
        if (maybe_metadata != null) count +|= 1;
    }
    return count;
}

fn benchQueryProfileEvery() ?u64 {
    const cached = bench_query_profile_every_cache.load(.monotonic);
    if (cached != bench_query_profile_unknown) {
        return if (cached == bench_query_profile_disabled) null else cached;
    }
    const every = benchQueryProfileEveryUncached() orelse {
        bench_query_profile_every_cache.store(bench_query_profile_disabled, .monotonic);
        return null;
    };
    if (every >= bench_query_profile_disabled) {
        bench_query_profile_every_cache.store(bench_query_profile_disabled, .monotonic);
        return null;
    }
    bench_query_profile_every_cache.store(every, .monotonic);
    return every;
}

fn benchQueryProfileEveryUncached() ?u64 {
    const raw_z = getenv("ANTFLY_BENCH_QUERY_PROFILE_EVERY") orelse {
        const enabled = getenv("ANTFLY_BENCH_QUERY_PROFILE") orelse return null;
        if (std.mem.eql(u8, enabled, "0") or
            std.ascii.eqlIgnoreCase(enabled, "false") or
            std.ascii.eqlIgnoreCase(enabled, "no"))
        {
            return null;
        }
        return 100;
    };
    const raw = raw_z;
    if (raw.len == 0) return null;
    return std.fmt.parseUnsigned(u64, raw, 10) catch null;
}

fn lookupDenseHitDocOrdinal(
    alloc: Allocator,
    req: types.SearchRequest,
    executor: DenseSearchExecutor,
    doc_key: []const u8,
) !?doc_set.DocOrdinal {
    if (!denseHitPageNeedsDocOrdinals(req)) return null;
    const lookup = executor.lookup_doc_ordinal orelse return null;
    return try lookup(executor.ctx, alloc, doc_key, req.identity_read_generation);
}

fn loadMissingProjectedDenseHitDocuments(
    alloc: Allocator,
    req: types.SearchRequest,
    executor: DenseSearchExecutor,
    hits: []types.SearchHit,
) !ProjectedSourceLoadProfile {
    const start_ns = platform_time.monotonicNs();
    var profile = ProjectedSourceLoadProfile{};
    try checkSearchRequestDeadline(req);
    for (hits, 0..) |*hit, i| {
        if (hit.stored_data != null) continue;
        if (i % 1024 == 0) try checkSearchRequestDeadline(req);
        hit.stored_data = try loadProjectedDenseDocumentWithProfile(alloc, req, executor, hit.id, &profile);
    }
    profile.total_ns = platform_time.monotonicNs() - start_ns;
    return profile;
}

fn loadProjectedDenseDocumentWithProfile(
    alloc: Allocator,
    req: types.SearchRequest,
    executor: DenseSearchExecutor,
    id: []const u8,
    profile: *ProjectedSourceLoadProfile,
) ![]u8 {
    try checkSearchRequestDeadline(req);
    const load_start = platform_time.monotonicNs();
    profile.requested_count += 1;
    const data = try executor.load_projected_document(executor.ctx, alloc, req, id);
    const load_ns = platform_time.monotonicNs() - load_start;
    profile.loaded_count += 1;
    profile.batch_count += 1;
    profile.total_ns +|= load_ns;
    return data;
}

fn lookupDenseHitDocOrdinals(
    alloc: Allocator,
    req: types.SearchRequest,
    executor: DenseSearchExecutor,
    vector_ids: []const u64,
    hits: []types.SearchHit,
) !void {
    if (!denseHitPageNeedsDocOrdinals(req) or hits.len == 0) return;
    if (executor.lookup_doc_ordinals_for_vector_ids) |lookup_for_vector_ids| {
        if (req.index_name) |index_name| {
            const ordinals = try lookup_for_vector_ids(executor.ctx, alloc, index_name, vector_ids, req.identity_read_generation);
            defer alloc.free(ordinals);
            if (ordinals.len != hits.len) return error.InvalidDocIdentity;
            var missing_count: usize = 0;
            for (hits, 0..) |*hit, i| {
                hit.doc_ordinal = ordinals[i];
                if (ordinals[i] == null) missing_count += 1;
            }
            if (missing_count == 0) return;
        }
    }
    if (executor.lookup_doc_ordinals) |lookup_many| {
        var doc_ids = try std.ArrayListUnmanaged([]const u8).initCapacity(alloc, hits.len);
        defer doc_ids.deinit(alloc);
        var hit_indexes = try std.ArrayListUnmanaged(usize).initCapacity(alloc, hits.len);
        defer hit_indexes.deinit(alloc);
        for (hits, 0..) |hit, i| {
            if (hit.doc_ordinal != null) continue;
            doc_ids.appendAssumeCapacity(hit.id);
            hit_indexes.appendAssumeCapacity(i);
        }
        if (doc_ids.items.len == 0) return;
        const ordinals = try lookup_many(executor.ctx, alloc, doc_ids.items, req.identity_read_generation);
        defer alloc.free(ordinals);
        if (ordinals.len != doc_ids.items.len) return error.InvalidDocIdentity;
        for (hit_indexes.items, 0..) |hit_index, i| hits[hit_index].doc_ordinal = ordinals[i];
        return;
    }
    for (hits) |*hit| {
        if (hit.doc_ordinal != null) continue;
        hit.doc_ordinal = try lookupDenseHitDocOrdinal(alloc, req, executor, hit.id);
    }
}

fn denseHitPageNeedsDocOrdinals(req: types.SearchRequest) bool {
    return req.resolved_doc_filter != null or
        req.graph_queries.len != 0 or
        req.filter_doc_ids_positive or
        req.filter_doc_ids.len != 0 or
        req.exclude_doc_ids.len != 0 or
        hasStoredPatternFilters(req);
}

fn nsToUs(ns: u64) u64 {
    return ns / std.time.ns_per_us;
}

fn logBenchDenseQueryProfile(
    req: types.SearchRequest,
    dense: types.DenseKnnQuery,
    index_stats: vectorindex_mod.IndexStats,
    profile: *const DenseSearchProfile,
) void {
    const estimated_leaves = estimateLeafCount(index_stats);
    std.log.info(
        "antfly_bench_dense_query index={s} primary_text={s} has_filter={} has_exclusion={} k={d} limit={d} offset={d} effort={d:.3} nodes={d} active={d} estimated_leaves={d} leaf_size={d} branching={d} search_width={d} epsilon={d:.3} native_filter_candidates={d} route={s} route_reason={s} total_us={d} index_lookup_us={d} constraint_us={d} hbc_us={d} doc_key_us={d} doc_ordinal_us={d} load_projected_us={d} postprocess_us={d} raw_hits={d} returned_hits={d}",
        .{
            req.index_name orelse "",
            req.primary_text_index_name orelse "",
            req.filter_text != null or req.filter_query_json.len > 0,
            req.exclusion_text != null or req.exclusion_query_json.len > 0,
            dense.k,
            req.limit,
            req.offset,
            req.search_effort orelse @as(f32, -1.0),
            index_stats.node_count,
            index_stats.active_count,
            estimated_leaves,
            index_stats.leaf_size,
            index_stats.branching_factor,
            profile.resolved_search_width,
            profile.resolved_epsilon,
            profile.native_filter_candidate_count,
            profile.search_route,
            profile.route_reason,
            nsToUs(profile.total_ns),
            nsToUs(profile.index_lookup_ns),
            nsToUs(profile.constraint_ns),
            nsToUs(profile.hbc_search_ns),
            nsToUs(profile.doc_key_resolve_ns),
            nsToUs(profile.doc_ordinal_lookup_ns),
            nsToUs(profile.load_projected_document_ns),
            nsToUs(profile.postprocess_ns),
            profile.raw_hit_count,
            profile.returned_hit_count,
        },
    );
    std.log.info(
        "antfly_bench_dense_query_hbc index={s} nodes_visited={d} leaves={d} approx_vectors={d} exact_vectors={d} payload_stale={d} payload_missing={d} reranked={d} approx_candidates={d} rerank_candidates={d} ambiguous_top_k={d} ambiguous_boundary={d} distance_over_hits={d} distance_under_hits={d} full_rerank={any} top_k_count={d} min_distance_gap={d:.6} min_interval_gap={d:.6} rerank_vector_load_us={d} rerank_metadata_us={d} rerank_artifact_key_us={d} rerank_artifact_read_us={d} rerank_artifact_decode_us={d} rerank_artifact_distance_us={d} rerank_lsm_cache_hits={d} rerank_lsm_cache_misses={d} rerank_distance_us={d} inline_meta={d} fetched_meta={d} lookup_doc_key={d}",
        .{
            req.index_name orelse "",
            profile.hbc_nodes_visited,
            profile.hbc_leaves_explored,
            profile.hbc_approx_vectors_scored,
            profile.hbc_exact_vectors_scored,
            profile.hbc_leaf_payload_stale,
            profile.hbc_leaf_payload_missing,
            profile.hbc_reranked_vectors,
            profile.hbc_approx_candidate_count,
            profile.hbc_rerank_candidate_count,
            profile.hbc_ambiguous_top_k_pairs,
            profile.hbc_ambiguous_boundary_pairs,
            profile.hbc_ambiguous_distance_over_hits,
            profile.hbc_ambiguous_distance_under_hits,
            profile.hbc_full_rerank_due_to_threshold,
            profile.hbc_top_k_count,
            profile.hbc_min_distance_gap_top_k,
            profile.hbc_min_interval_gap_top_k,
            nsToUs(profile.hbc_rerank_vector_load_ns),
            nsToUs(profile.hbc_rerank_metadata_lookup_ns),
            nsToUs(profile.hbc_rerank_artifact_key_ns),
            nsToUs(profile.hbc_rerank_artifact_read_ns),
            nsToUs(profile.hbc_rerank_artifact_decode_ns),
            nsToUs(profile.hbc_rerank_artifact_distance_ns),
            profile.hbc_rerank_lsm_cache_hits,
            profile.hbc_rerank_lsm_cache_misses,
            nsToUs(profile.hbc_rerank_distance_ns),
            profile.inline_metadata_hits,
            profile.fetched_metadata_hits,
            profile.lookup_doc_key_hits,
        },
    );
    if (profile.hbc_filter_candidates > 0 or profile.hbc_filter_metadata_batches > 0) {
        std.log.info(
            "antfly_bench_dense_query_filter index={s} candidates={d} rejected={d} metadata_batches={d} metadata_batch_us={d}",
            .{
                req.index_name orelse "",
                profile.hbc_filter_candidates,
                profile.hbc_filter_rejected,
                profile.hbc_filter_metadata_batches,
                nsToUs(profile.hbc_filter_metadata_batch_ns),
            },
        );
    }
}

fn mapDebugHit(hit: vectorindex_mod.DebugHit) DenseSearchProfile.DebugHit {
    return .{
        .id = hit.id,
        .distance = hit.distance,
        .error_bound = hit.error_bound,
        .lower_bound = hit.lower_bound,
        .upper_bound = hit.upper_bound,
    };
}

fn mapDebugPair(pair: vectorindex_mod.DebugPair) DenseSearchProfile.DebugPair {
    return .{
        .left = mapDebugHit(pair.left),
        .right = mapDebugHit(pair.right),
        .distance_gap = pair.distance_gap,
        .interval_gap = pair.interval_gap,
        .overlaps = pair.overlaps,
    };
}

pub fn normalizedSearchEffort(effort: ?f32) ?f32 {
    const value = effort orelse return null;
    if (std.math.isNan(value)) return null;
    if (value < 0) return 0;
    if (value > 1) return 1;
    return value;
}

pub fn resolvedSearchEffort(effort: ?f32) f32 {
    return normalizedSearchEffort(effort) orelse default_balanced_search_effort;
}

fn estimateLeafCount(stats: vectorindex_mod.IndexStats) u32 {
    if (stats.active_count == 0) return 0;
    const leaf_size = @max(stats.leaf_size, 1);
    const estimated = (stats.active_count + leaf_size - 1) / leaf_size;
    return @intCast(@min(estimated, @as(u64, std.math.maxInt(u32))));
}

// Search policy: effort 0..1 maps to a leaf-visit budget (search width), a
// dynamic-pruning epsilon, and a rerank candidate multiplier. The width floor
// scales with how many leaves are needed to cover k oversampled results, not
// with k itself, and the ramp between floor and ceiling is geometric so the
// knob behaves sensibly across index sizes. Epsilon stays small enough that
// the SPANN-style "skip leaves whose centroid is (1+eps) x the best" pruning
// actually fires. The constants can be overridden through environment
// variables (read once per process) for offline tuning.
const SearchPolicy = struct {
    epsilon_base: f32 = 0.90,
    epsilon_span: f32 = 1.10,
    width_k_factor: f32 = 4.0,
    width_min_leaves: u32 = 4,
    // Fraction of the leaf ceiling visited at balanced (0.5) effort. On the
    // 50K OpenAI case, recall at the default effort tracks this anchor; the
    // current HBC tree needs most of its leaves for ~0.98 recall, so the
    // default anchor sits high and the low-effort range is where the policy
    // saves work.
    width_mid_fraction: f32 = 0.70,
    // Absolute ceiling on the balanced-effort anchor so the default leaf
    // budget does not grow linearly with corpus size (matches the legacy
    // behavior at the 1M scale; no effect at 50K-scale trees).
    width_mid_cap: f32 = 2048.0,
    rerank_factor_base: f32 = 6.0,
    rerank_factor_span: f32 = 6.0,
};

var search_policy: SearchPolicy = .{};
var search_policy_loaded = std.atomic.Value(bool).init(false);

fn ensureSearchPolicyLoaded() void {
    if (search_policy_loaded.load(.acquire)) return;
    // Benign race: concurrent first callers recompute identical values from
    // the environment before either publishes the flag.
    loadSearchPolicyEnv();
    search_policy_loaded.store(true, .release);
}

fn searchPolicyEnvF32(name: [*:0]const u8, default_value: f32) f32 {
    const raw = getenv(name) orelse return default_value;
    return std.fmt.parseFloat(f32, raw) catch default_value;
}

fn loadSearchPolicyEnv() void {
    search_policy.epsilon_base = searchPolicyEnvF32("ANTFLY_SEARCH_EPSILON_BASE", search_policy.epsilon_base);
    search_policy.epsilon_span = searchPolicyEnvF32("ANTFLY_SEARCH_EPSILON_SPAN", search_policy.epsilon_span);
    search_policy.width_k_factor = searchPolicyEnvF32("ANTFLY_SEARCH_WIDTH_K_FACTOR", search_policy.width_k_factor);
    search_policy.width_mid_fraction = searchPolicyEnvF32("ANTFLY_SEARCH_WIDTH_MID_FRACTION", search_policy.width_mid_fraction);
    search_policy.width_mid_cap = searchPolicyEnvF32("ANTFLY_SEARCH_WIDTH_MID_CAP", search_policy.width_mid_cap);
    search_policy.rerank_factor_base = searchPolicyEnvF32("ANTFLY_SEARCH_RERANK_BASE", search_policy.rerank_factor_base);
    search_policy.rerank_factor_span = searchPolicyEnvF32("ANTFLY_SEARCH_RERANK_SPAN", search_policy.rerank_factor_span);
}

pub fn resolveSearchWidth(k: u32, effort: f32, stats: vectorindex_mod.IndexStats) u32 {
    ensureSearchPolicyLoaded();
    const leaf_size = @max(stats.leaf_size, 1);
    const estimated_leaf_count = estimateLeafCount(stats);
    const legacy_max_width = @max(@max(k, @as(u32, 64)) * 20, @as(u32, 4096));
    const max_width = if (estimated_leaf_count > 0)
        estimated_leaf_count
    else if (stats.node_count > legacy_max_width and stats.node_count <= std.math.maxInt(u32))
        @as(u32, @intCast(stats.node_count))
    else
        legacy_max_width;

    const k_leaves_u64 = std.math.divCeil(u64, @as(u64, @intFromFloat(@max(1.0, @ceil(@as(f32, @floatFromInt(k)) * search_policy.width_k_factor)))), leaf_size) catch 1;
    const k_leaves: u32 = @intCast(@min(k_leaves_u64, @as(u64, std.math.maxInt(u32))));
    const min_width = @min(max_width, @max(k_leaves, search_policy.width_min_leaves));
    if (min_width >= max_width) return max_width;
    if (effort <= 0) return min_width;
    if (effort >= 1) return max_width;

    // Two geometric segments anchored at width_mid_fraction x ceiling for the
    // balanced effort, so the default recall stays calibrated while the floor
    // and the low-effort range scale with k instead of the corpus.
    const min_f = @as(f32, @floatFromInt(min_width));
    const max_f = @as(f32, @floatFromInt(max_width));
    const mid_f = @min(@min(max_f, search_policy.width_mid_cap), @max(min_f, max_f * search_policy.width_mid_fraction));
    const width_f = if (effort <= 0.5)
        min_f * std.math.pow(f32, mid_f / min_f, effort * 2.0)
    else
        mid_f * std.math.pow(f32, max_f / mid_f, (effort - 0.5) * 2.0);
    const width: u32 = @intFromFloat(@min(width_f, max_f));
    return @max(min_width, @min(width, max_width));
}

pub fn resolveSearchEpsilon(effort: f32) f32 {
    ensureSearchPolicyLoaded();
    return search_policy.epsilon_base + (effort * search_policy.epsilon_span);
}

pub fn resolveRerankFactor(effort: f32) usize {
    ensureSearchPolicyLoaded();
    const factor = search_policy.rerank_factor_base + (effort * search_policy.rerank_factor_span);
    return @max(1, @as(usize, @intFromFloat(@round(factor))));
}

fn sparseHitParentOrdinal(
    alloc: Allocator,
    executor: SparseSearchExecutor,
    hit_doc_id: []const u8,
    generation: ?u64,
) !?doc_set.DocOrdinal {
    const lookup = executor.lookup_doc_ordinal orelse return null;
    if (!internal_keys.isChunkArtifactRecordKey(hit_doc_id)) return null;
    const parent_doc_id = (try internal_keys.decodeDocumentComponentAlloc(alloc, hit_doc_id)) orelse return null;
    defer alloc.free(parent_doc_id);
    return try lookup(executor.ctx, alloc, parent_doc_id, generation);
}

fn sparseHitOrdinal(
    alloc: Allocator,
    executor: SparseSearchExecutor,
    hit_doc_id: []const u8,
    generation: ?u64,
) !?doc_set.DocOrdinal {
    const lookup = executor.lookup_doc_ordinal orelse return null;
    return try lookup(executor.ctx, alloc, hit_doc_id, generation);
}

pub fn searchSparse(
    alloc: Allocator,
    req: types.SearchRequest,
    sparse: types.SparseKnnQuery,
    executor: SparseSearchExecutor,
) !types.SearchResult {
    resetLastSortRejectionDiagnostic();
    try checkSearchRequestDeadline(req);
    try rejectApproximateSortPageOptions(req);
    const bench_query_profile = shouldLogBenchQueryProfile();
    const collect_sort_profile = bench_query_profile or req.profile;
    const collect_total_timing = bench_query_profile or collect_sort_profile;
    const total_start_ns = if (collect_total_timing) platform_time.monotonicNs() else 0;
    var constraint_ns: u64 = 0;
    var index_search_ns: u64 = 0;
    var hit_build_ns: u64 = 0;
    var postprocess_ns: u64 = 0;
    var page_ns: u64 = 0;
    var projected_source_profile = ProjectedSourceLoadProfile{};
    const entry = (try executor.sparse_index(executor.ctx, req.index_name)) orelse return error.IndexNotFound;
    const chunk_backed = entry.chunk_name != null;
    const group_chunk_parents = shouldGroupChunkParents(req, chunk_backed);
    const paging = componentPaging(req);
    const constraint_start_ns = if (bench_query_profile) platform_time.monotonicNs() else 0;
    var native_constraints = try deriveNativeDocIdConstraintsAlloc(alloc, req, .{
        .ctx = executor.ctx,
        .text_index_entry = executor.text_index_entry,
        .resolve_doc_set_doc_ids = executor.resolve_doc_set_doc_ids,
        .resolve_doc_ids_to_doc_set = executor.resolve_doc_ids_to_doc_set,
        .live_filter_doc_set = executor.live_filter_doc_set,
        .nonvisible_doc_set = executor.nonvisible_doc_set,
        .lookup_doc_nums_for_ordinals = executor.lookup_doc_nums_for_ordinals,
        .doc_num_index_name = req.index_name orelse entry.config.name,
        .require_doc_num_projection_mapper = true,
        .project_ordinals_to_doc_ids = false,
        .apply_live_all_docs = true,
    });
    if (bench_query_profile) constraint_ns = platform_time.monotonicNs() - constraint_start_ns;
    defer native_constraints.deinit(alloc);
    const unresolved_stored_filters =
        (req.filter_query_json.len > 0 and !native_constraints.filter_query_json_resolved) or
        (req.exclusion_query_json.len > 0 and !native_constraints.exclusion_query_json_resolved);
    const postprocess_req = requestWithoutResolvedStoredFilters(
        req,
        native_constraints.filter_query_json_resolved,
        native_constraints.exclusion_query_json_resolved,
    );
    const full_candidate_window = group_chunk_parents or unresolved_stored_filters;
    const bounded_sparse_candidate_count: u64 = if (native_constraints.positive_filter)
        @as(u64, native_constraints.filter_doc_ids.len) +| @as(u64, native_constraints.filter_doc_nums.len)
    else
        entry.index.next_doc_num;
    const bounded_candidate_count = boundedU32(bounded_sparse_candidate_count);
    const candidate_ceiling = if (group_chunk_parents)
        @min(bounded_candidate_count, groupedCandidateBudget())
    else
        bounded_candidate_count;
    var candidate_window: u32 = if (full_candidate_window)
        initialAdaptiveCandidateWindow(candidate_ceiling, paging)
    else
        scoreOrderCandidateWindowK(sparse.k, paging);
    const query = sparse_mod.SparseVector{
        .indices = sparse.indices,
        .values = sparse.values,
    };
    if (native_constraints.positive_filter and native_constraints.filter_doc_ids.len == 0 and native_constraints.filter_doc_nums.len == 0) {
        const total_ns = if (collect_sort_profile) platform_time.monotonicNs() - total_start_ns else 0;
        return .{
            .alloc = alloc,
            .hits = &.{},
            .total_hits = 0,
            .sort_profile = vectorScoreTopKSortProfile(req, collect_sort_profile, .exact, 0, 0, total_ns),
            .graph_results = &.{},
        };
    }
    const sparse_doc_nums_are_ordinals =
        !chunk_backed and
        native_constraints.positive_filter and
        native_constraints.filter_doc_nums.len > 0 and
        native_constraints.filter_doc_ids.len == 0;

    while (true) {
        const effective_k = candidate_window;
        const index_search_start_ns = if (bench_query_profile) platform_time.monotonicNs() else 0;
        const raw_hits = try entry.index.searchConstrained(alloc, &query, effective_k, .{
            .filter_doc_ids = native_constraints.filter_doc_ids,
            .exclude_doc_ids = native_constraints.exclude_doc_ids,
            .filter_doc_nums = native_constraints.filter_doc_nums,
            .exclude_doc_nums = native_constraints.exclude_doc_nums,
            .cancellation = req.cancellation,
        });
        defer sparse_mod.SparseIndex.freeResults(alloc, raw_hits);
        try checkSearchRequestDeadline(req);
        if (bench_query_profile) index_search_ns += platform_time.monotonicNs() - index_search_start_ns;

        const window_relation = scoreOrderWindowTotalHitsRelation(effective_k, bounded_sparse_candidate_count, raw_hits.len);
        const candidate_window_incomplete = window_relation == .gte;
        const candidate_ceiling_reached = candidate_window >= candidate_ceiling;
        const candidate_tail_score: ?f32 = if (raw_hits.len > 0)
            raw_hits[raw_hits.len - 1].score
        else
            null;
        const start: u32 = if (full_candidate_window) 0 else @min(paging.offset, @as(u32, @intCast(raw_hits.len)));
        const end: u32 = if (full_candidate_window) @intCast(raw_hits.len) else @min(start +| paging.limit, @as(u32, @intCast(raw_hits.len)));

        var hits = try alloc.alloc(types.SearchHit, end - start);
        var initialized: usize = 0;
        var owns_hits = true;
        errdefer {
            if (owns_hits) {
                for (hits[0..initialized]) |*hit| hit.deinit(alloc);
                alloc.free(hits);
            }
        }

        var batch_doc_ordinals: []?doc_set.DocOrdinal = &.{};
        defer if (batch_doc_ordinals.len > 0) alloc.free(batch_doc_ordinals);
        if (!chunk_backed and !sparse_doc_nums_are_ordinals) {
            if (executor.lookup_doc_ordinals) |lookup_many| {
                const selected = raw_hits[@intCast(start)..@intCast(end)];
                if (selected.len > 0) {
                    const doc_ids = try alloc.alloc([]const u8, selected.len);
                    defer alloc.free(doc_ids);
                    for (selected, 0..) |hit, i| doc_ids[i] = hit.doc_id;
                    batch_doc_ordinals = try lookup_many(executor.ctx, alloc, doc_ids, req.identity_read_generation);
                    if (batch_doc_ordinals.len != selected.len) return error.InvalidDocIdentity;
                }
            }
        }

        const hit_build_start_ns = if (bench_query_profile) platform_time.monotonicNs() else 0;
        for (raw_hits[@intCast(start)..@intCast(end)], 0..) |hit, i| {
            hits[i] = .{
                .id = try alloc.dupe(u8, hit.doc_id),
                .doc_ordinal = if (chunk_backed)
                    try sparseHitParentOrdinal(alloc, executor, hit.doc_id, req.identity_read_generation)
                else if (sparse_doc_nums_are_ordinals and hit.doc_num != null)
                    hit.doc_num.?
                else if (batch_doc_ordinals.len > 0)
                    batch_doc_ordinals[i]
                else
                    try sparseHitOrdinal(alloc, executor, hit.doc_id, req.identity_read_generation),
                .score = hit.score,
                .stored_data = null,
            };
            initialized += 1;
        }
        if (bench_query_profile) hit_build_ns += platform_time.monotonicNs() - hit_build_start_ns;

        owns_hits = false;
        var candidate_postprocess_req = postprocess_req;
        if (full_candidate_window) {
            candidate_postprocess_req.offset = 0;
            candidate_postprocess_req.limit = candidate_window;
        }
        const postprocess_start_ns = if (bench_query_profile) platform_time.monotonicNs() else 0;
        var result = try executor.postprocess(executor.ctx, alloc, candidate_postprocess_req, .{
            .alloc = alloc,
            .hits = hits,
            .total_hits = @intCast(raw_hits.len),
            .total_hits_relation = window_relation,
            .graph_results = &.{},
        }, chunk_backed);
        if (bench_query_profile) postprocess_ns += platform_time.monotonicNs() - postprocess_start_ns;
        errdefer result.deinit();

        const visible_candidate_count: u32 = @intCast(@min(result.hits.len, @as(usize, std.math.maxInt(u32))));
        const needs_more_grouped_candidates = group_chunk_parents and !groupedResultHasStableRequestedPage(
            paging,
            result,
            candidate_tail_score,
            !candidate_window_incomplete,
        );
        const needs_more_visible_candidates = unresolved_stored_filters and visible_candidate_count < pagingCandidateWindow(paging);
        if (full_candidate_window and
            candidate_window_incomplete and
            !candidate_ceiling_reached and
            (needs_more_grouped_candidates or needs_more_visible_candidates))
        {
            result.deinit();
            const grown_window = growAdaptiveCandidateWindow(candidate_window, candidate_ceiling, pagingCandidateWindow(paging));
            if (grown_window == candidate_window) return error.InvalidQueryRequest;
            candidate_window = grown_window;
            continue;
        }
        if (group_chunk_parents) {
            try enforceGroupedPageBoundaryAtCandidateCeiling(
                paging,
                result,
                candidate_tail_score,
                !candidate_window_incomplete,
                candidate_ceiling_reached,
            );
        }
        if (candidate_window_incomplete) result.total_hits_relation = .gte;
        if (full_candidate_window) {
            const page_start_ns = if (bench_query_profile) platform_time.monotonicNs() else 0;
            result = try pageSearchResultInPlace(alloc, result, paging);
            if (bench_query_profile) page_ns += platform_time.monotonicNs() - page_start_ns;
        }
        if (postprocess_req.include_stored and !(chunk_backed and group_chunk_parents)) {
            projected_source_profile = try loadMissingProjectedSparseHitDocuments(alloc, postprocess_req, executor, result.hits);
            if (bench_query_profile) hit_build_ns += projected_source_profile.total_ns;
        }
        if (collect_sort_profile) {
            result.sort_profile = vectorScoreTopKSortProfile(req, collect_sort_profile, .exact, raw_hits.len, result.hits.len, platform_time.monotonicNs() - total_start_ns);
            applyProjectedSourceLoadProfileToSortProfile(&result, projected_source_profile);
        }
        try decorateVectorScoreOrderIfRequested(&result, req);
        if (bench_query_profile) {
            std.log.info(
                "antfly_bench_sparse_query total_us={d} constraint_us={d} index_search_us={d} hit_build_us={d} postprocess_us={d} page_us={d} raw_hits={d} returned_hits={d} filter_doc_nums={d} exclude_doc_nums={d}",
                .{
                    nsToUs(platform_time.monotonicNs() - total_start_ns),
                    nsToUs(constraint_ns),
                    nsToUs(index_search_ns),
                    nsToUs(hit_build_ns),
                    nsToUs(postprocess_ns),
                    nsToUs(page_ns),
                    raw_hits.len,
                    result.hits.len,
                    native_constraints.filter_doc_nums.len,
                    native_constraints.exclude_doc_nums.len,
                },
            );
        }
        return result;
    }
}

fn loadMissingProjectedSparseHitDocuments(
    alloc: Allocator,
    req: types.SearchRequest,
    executor: SparseSearchExecutor,
    hits: []types.SearchHit,
) !ProjectedSourceLoadProfile {
    const start_ns = platform_time.monotonicNs();
    var profile = ProjectedSourceLoadProfile{};
    try checkSearchRequestDeadline(req);
    var missing_count: usize = 0;
    for (hits) |hit| {
        if (hit.stored_data == null) missing_count += 1;
    }
    profile.requested_count = missing_count;
    if (missing_count == 0) {
        profile.total_ns = platform_time.monotonicNs() - start_ns;
        return profile;
    }

    if (executor.load_projected_documents) |load_many| {
        try checkSearchRequestDeadline(req);
        const keys = try alloc.alloc([]const u8, missing_count);
        defer alloc.free(keys);
        var key_count: usize = 0;
        for (hits) |hit| {
            if (hit.stored_data != null) continue;
            keys[key_count] = hit.id;
            key_count += 1;
        }

        var loaded = try load_many(executor.ctx, alloc, req, keys);
        profile.batch_count += 1;
        defer freeOptionalOwnedBytes(alloc, loaded);
        if (loaded.len != keys.len) return error.InvalidSearchResult;

        var loaded_index: usize = 0;
        for (hits, 0..) |*hit, i| {
            if (hit.stored_data != null) continue;
            if (i % 1024 == 0) try checkSearchRequestDeadline(req);
            const stored = loaded[loaded_index] orelse return error.StoredDocMissing;
            hit.stored_data = stored;
            loaded[loaded_index] = null;
            profile.loaded_count += 1;
            loaded_index += 1;
        }
        profile.total_ns = platform_time.monotonicNs() - start_ns;
        return profile;
    }

    for (hits, 0..) |*hit, i| {
        if (hit.stored_data != null) continue;
        if (i % 1024 == 0) try checkSearchRequestDeadline(req);
        hit.stored_data = try executor.load_projected_document(executor.ctx, alloc, req, hit.id);
        profile.loaded_count += 1;
        profile.batch_count += 1;
    }
    profile.total_ns = platform_time.monotonicNs() - start_ns;
    return profile;
}

fn freeOptionalOwnedBytes(alloc: Allocator, values: []?[]u8) void {
    for (values) |value| {
        if (value) |bytes| alloc.free(bytes);
    }
    alloc.free(values);
}

const ProjectedSourceLoadProfile = struct {
    requested_count: usize = 0,
    loaded_count: usize = 0,
    batch_count: usize = 0,
    total_ns: u64 = 0,
};

fn logBenchProjectedSourceLoadProfile(
    req: types.SearchRequest,
    plan: SortExecutionPlan,
    source: []const u8,
    profile: ProjectedSourceLoadProfile,
) void {
    if (!shouldLogBenchQueryProfile()) return;
    std.log.info(
        "antfly_bench_projected_source_load source={s} total_us={d} requested={d} loaded={d} batches={d} order_fields={d} cursor={s} plan={s} source_load={s}",
        .{
            source,
            nsToUs(profile.total_ns),
            profile.requested_count,
            profile.loaded_count,
            profile.batch_count,
            req.order_by.len,
            sortCursorMode(req),
            sortExecutionPlanKindName(plan.kind),
            sortPlanSourceLoadName(sortExecutionPlanSourceLoadForRequest(plan, req)),
        },
    );
}

fn applyProjectedSourceLoadProfileToSortProfile(
    result: *types.SearchResult,
    source_profile: ProjectedSourceLoadProfile,
) void {
    if (result.sort_profile) |*sort_profile| {
        sort_profile.projected_source_load_us +|= nsToUs(source_profile.total_ns);
        sort_profile.projected_source_load_count +|= @intCast(source_profile.loaded_count);
    }
}

fn loadMissingProjectedMatchAllHitDocuments(
    alloc: Allocator,
    req: types.SearchRequest,
    executor: MatchAllExecutor,
    hits: []types.SearchHit,
) !ProjectedSourceLoadProfile {
    const start_ns = platform_time.monotonicNs();
    var profile = ProjectedSourceLoadProfile{};
    errdefer profile.total_ns = platform_time.monotonicNs() - start_ns;

    try checkSearchRequestDeadline(req);
    var missing_count: usize = 0;
    for (hits) |hit| {
        if (hit.stored_data == null) missing_count += 1;
    }
    profile.requested_count = missing_count;
    if (missing_count == 0) {
        profile.total_ns = platform_time.monotonicNs() - start_ns;
        return profile;
    }

    if (executor.load_projected_documents) |load_many| {
        try checkSearchRequestDeadline(req);
        const keys = try alloc.alloc([]const u8, missing_count);
        defer alloc.free(keys);
        var key_count: usize = 0;
        for (hits) |hit| {
            if (hit.stored_data != null) continue;
            keys[key_count] = hit.id;
            key_count += 1;
        }

        var loaded = try load_many(executor.ctx, alloc, req, keys);
        profile.batch_count += 1;
        defer freeOptionalOwnedBytes(alloc, loaded);
        if (loaded.len != keys.len) return error.InvalidSearchResult;

        var loaded_index: usize = 0;
        for (hits, 0..) |*hit, i| {
            if (hit.stored_data != null) continue;
            if (i % 1024 == 0) try checkSearchRequestDeadline(req);
            const stored = loaded[loaded_index] orelse return error.StoredDocMissing;
            hit.stored_data = stored;
            loaded[loaded_index] = null;
            profile.loaded_count += 1;
            loaded_index += 1;
        }
        profile.total_ns = platform_time.monotonicNs() - start_ns;
        return profile;
    }

    for (hits, 0..) |*hit, i| {
        if (hit.stored_data != null) continue;
        if (i % 1024 == 0) try checkSearchRequestDeadline(req);
        hit.stored_data = try executor.load_projected_document(executor.ctx, alloc, req, hit.id);
        profile.loaded_count += 1;
        profile.batch_count += 1;
    }
    profile.total_ns = platform_time.monotonicNs() - start_ns;
    return profile;
}

fn loadMissingProjectedTextHitDocuments(
    alloc: Allocator,
    req: types.SearchRequest,
    executor: SearchTextQueryExecutor,
    hits: []types.SearchHit,
) !ProjectedSourceLoadProfile {
    const start_ns = platform_time.monotonicNs();
    var profile = ProjectedSourceLoadProfile{};
    try checkSearchRequestDeadline(req);
    for (hits, 0..) |*hit, i| {
        if (hit.stored_data != null) continue;
        if (i % 1024 == 0) try checkSearchRequestDeadline(req);
        profile.requested_count += 1;
        const stored = (try executor.load_stored(executor.ctx, alloc, hit.id)) orelse return error.StoredDocMissing;
        defer alloc.free(stored);
        hit.stored_data = try executor.project_stored_search(executor.ctx, alloc, req, hit.id, stored);
        profile.loaded_count += 1;
        profile.batch_count += 1;
    }
    profile.total_ns = platform_time.monotonicNs() - start_ns;
    return profile;
}

fn requestNeedsNativeSortValues(req: types.SearchRequest) bool {
    for (req.order_by) |field| {
        if (sortFieldNeedsNativeValue(field)) return true;
    }
    return false;
}

fn requestHasScoreSort(req: types.SearchRequest) bool {
    for (req.order_by) |field| {
        if (sortFieldIsScore(field)) return true;
    }
    return false;
}

fn textQueryIsScoreBearing(query: types.TextQuery) bool {
    return switch (query) {
        .phrase,
        .multi_phrase,
        .term,
        .match,
        .multi_match_bool_prefix,
        .match_phrase,
        .fuzzy,
        .prefix,
        .wildcard,
        .regexp,
        => true,
        .bool_query => |bool_query| textBoolQueryIsScoreBearing(bool_query),
        .match_none,
        .match_all,
        .numeric_range,
        .date_range,
        .term_range,
        .doc_id,
        .bool_field,
        .geo_distance,
        .geo_bbox,
        .ip_range,
        .geo_shape,
        => false,
    };
}

fn textBoolQueryIsScoreBearing(query: types.TextBoolQuery) bool {
    for (query.must) |child| {
        if (textQueryIsScoreBearing(child)) return true;
    }
    for (query.should) |child| {
        if (textQueryIsScoreBearing(child)) return true;
    }
    return false;
}

pub fn searchRequestHasScoreBearingTextSource(req: types.SearchRequest) bool {
    if (req.full_text) |query| {
        if (textQueryIsScoreBearing(query)) return true;
    }
    for (req.full_text_queries) |query| {
        if (textQueryIsScoreBearing(query.query)) return true;
    }
    return false;
}

pub fn searchRequestHasScoreBearingVectorSource(req: types.SearchRequest) bool {
    return req.dense != null or
        req.sparse != null or
        req.dense_queries.len > 0 or
        req.sparse_queries.len > 0;
}

pub fn searchRequestHasScoreBearingSource(req: types.SearchRequest) bool {
    return searchRequestHasScoreBearingTextSource(req) or searchRequestHasScoreBearingVectorSource(req);
}

fn validateScoreSortHasScoreBearingTextSource(req: types.SearchRequest) !void {
    if (requestHasScoreSort(req) and !searchRequestHasScoreBearingTextSource(req)) {
        logNativeSortPlanRejection(
            "_score",
            nativeSortPlanRejectionReasonName(.non_score_bearing_source),
            nativeSortPlanRejectionDetailName(.non_score_bearing_source),
        );
        return error.UnsupportedQueryRequest;
    }
}

fn validateMatchAllSortDoesNotUseScore(req: types.SearchRequest) !void {
    if (requestHasScoreSort(req)) {
        logNativeSortPlanRejection(
            "_score",
            nativeSortPlanRejectionReasonName(.non_score_bearing_source),
            nativeSortPlanRejectionDetailName(.non_score_bearing_source),
        );
        return error.UnsupportedQueryRequest;
    }
}

test "score sort source detection rejects non-scoring text queries" {
    const score_order = [_]types.SortField{.{ .field = "_score", .desc = true }};
    const range_only = [_]types.TextQuery{
        .{ .numeric_range = .{ .field = "rank", .min = 1 } },
        .{ .term_range = .{ .field = "title", .min = "a", .max = "z" } },
    };
    const match_child = [_]types.TextQuery{.{ .match = .{ .field = "body", .text = "alpha" } }};

    try std.testing.expectError(error.UnsupportedQueryRequest, validateScoreSortHasScoreBearingTextSource(.{
        .order_by = &score_order,
        .full_text = .{ .match_all = {} },
    }));
    try std.testing.expectError(error.UnsupportedQueryRequest, validateScoreSortHasScoreBearingTextSource(.{
        .order_by = &score_order,
        .full_text = .{ .bool_query = .{ .must = &range_only } },
    }));
    try validateScoreSortHasScoreBearingTextSource(.{
        .order_by = &score_order,
        .full_text = .{ .bool_query = .{ .should = &match_child } },
    });
}

test "vector score order helper is limited to internal score tuple decoration" {
    const score_order = [_]types.SortField{.{ .field = "_score", .desc = true }};
    const effective_score_order = [_]types.SortField{
        .{ .field = "_score", .desc = true },
        .{ .field = "_id", .desc = false },
    };
    const ascending_score_order = [_]types.SortField{.{ .field = "_score", .desc = false }};
    const field_order = [_]types.SortField{.{ .field = "created_at", .desc = true }};
    const score_cursor = [_]std.json.Value{
        .{ .float = 0.5 },
        .{ .string = "doc:a" },
    };
    const vector = [_]f32{ 0.1, 0.2 };
    const named_dense = [_]types.NamedDenseQuery{.{
        .name = "semantic",
        .index_name = "semantic_idx",
        .query = .{ .vector = &vector, .k = 10 },
    }};

    try std.testing.expect(searchRequestHasScoreBearingSource(.{
        .order_by = &score_order,
        .dense = .{ .vector = &vector, .k = 10 },
    }));
    try std.testing.expect(searchRequestHasScoreBearingSource(.{
        .order_by = &score_order,
        .dense_queries = &named_dense,
    }));
    try std.testing.expect(!searchRequestHasScoreBearingSource(.{
        .order_by = &score_order,
        .full_text = .{ .match_all = {} },
    }));
    try std.testing.expect(requestHasVectorScoreOrderOnly(.{ .order_by = &effective_score_order }));
    try std.testing.expect(!requestHasVectorScoreOrderOnly(.{ .order_by = &ascending_score_order }));
    try std.testing.expect(!requestHasVectorScoreOrderOnly(.{ .order_by = &field_order }));
    try std.testing.expect(!requestHasVectorScoreOrderOnly(.{
        .order_by = &effective_score_order,
        .search_after = &score_cursor,
    }));
}

fn typedDocValuesTypeMatchesMappedSortField(
    value_type: typed_dv.ValueType,
    mapping: runtime_schema_mod.FieldMapping,
) bool {
    return switch (mapping.field_type) {
        .keyword, .link => value_type == .bytes_val,
        .numeric => value_type == .u64_val or value_type == .i64_val or value_type == .f64_val or value_type == .numeric_val,
        .boolean => value_type == .bool_val,
        .datetime => value_type == .u64_val,
        else => false,
    };
}

const TypedDocValuesCoverageStatus = typed_dv_coverage.Status;

const TypedDocValuesCoverage = struct {
    status: TypedDocValuesCoverageStatus,
    value_type: ?typed_dv.ValueType = null,
};

fn typedDocValuesCoverageStatusName(status: TypedDocValuesCoverageStatus) []const u8 {
    return typed_dv_coverage.statusName(status);
}

fn typedDocValuesCoverageRejectionReason(status: TypedDocValuesCoverageStatus) ?NativeSortPlanRejectionReason {
    return switch (status) {
        .covered => null,
        .missing_doc_values_section,
        .malformed_doc_values_section,
        .doc_values_kind_mismatch,
        .invalid_doc_value_doc_id,
        .duplicate_doc_value_doc_id,
        => .missing_doc_values_capability,
        .sparse_live_doc_values => .missing_null_policy,
    };
}

test "typed doc values coverage status names are stable for diagnostics" {
    try std.testing.expectEqualStrings("covered", typedDocValuesCoverageStatusName(.covered));
    try std.testing.expectEqualStrings("missing_doc_values_section", typedDocValuesCoverageStatusName(.missing_doc_values_section));
    try std.testing.expectEqualStrings("malformed_doc_values_section", typedDocValuesCoverageStatusName(.malformed_doc_values_section));
    try std.testing.expectEqualStrings("doc_values_kind_mismatch", typedDocValuesCoverageStatusName(.doc_values_kind_mismatch));
    try std.testing.expectEqualStrings("sparse_live_doc_values", typedDocValuesCoverageStatusName(.sparse_live_doc_values));
    try std.testing.expectEqualStrings("invalid_doc_value_doc_id", typedDocValuesCoverageStatusName(.invalid_doc_value_doc_id));
    try std.testing.expectEqualStrings("duplicate_doc_value_doc_id", typedDocValuesCoverageStatusName(.duplicate_doc_value_doc_id));
}

test "typed doc values coverage rejection reasons distinguish missing policy from coverage" {
    try std.testing.expect(typedDocValuesCoverageRejectionReason(.covered) == null);
    try std.testing.expectEqual(
        NativeSortPlanRejectionReason.missing_doc_values_capability,
        typedDocValuesCoverageRejectionReason(.missing_doc_values_section).?,
    );
    try std.testing.expectEqual(
        NativeSortPlanRejectionReason.missing_doc_values_capability,
        typedDocValuesCoverageRejectionReason(.malformed_doc_values_section).?,
    );
    try std.testing.expectEqual(
        NativeSortPlanRejectionReason.missing_doc_values_capability,
        typedDocValuesCoverageRejectionReason(.doc_values_kind_mismatch).?,
    );
    try std.testing.expectEqual(
        NativeSortPlanRejectionReason.missing_null_policy,
        typedDocValuesCoverageRejectionReason(.sparse_live_doc_values).?,
    );
    try std.testing.expectEqual(
        NativeSortPlanRejectionReason.missing_doc_values_capability,
        typedDocValuesCoverageRejectionReason(.invalid_doc_value_doc_id).?,
    );
    try std.testing.expectEqual(
        NativeSortPlanRejectionReason.missing_doc_values_capability,
        typedDocValuesCoverageRejectionReason(.duplicate_doc_value_doc_id).?,
    );
}

fn logNativeSortPlanRejection(field: []const u8, reason: []const u8, detail: []const u8) void {
    recordSortRejectionDiagnostic(field, reason, detail);
    if (!shouldLogBenchQueryProfile()) return;
    std.log.info(
        "antfly_bench_sort_plan_reject field={s} reason={s} detail={s}",
        .{ field, reason, detail },
    );
}

fn snapshotTypedDocValuesCoverageDetailsForMapping(
    snapshot: *const index_mod.IndexSnapshot,
    field: []const u8,
    mapping: runtime_schema_mod.FieldMapping,
) !TypedDocValuesCoverage {
    return snapshotTypedDocValuesCoverageDetailsForMappingWithValidation(snapshot, field, mapping, null);
}

fn snapshotTypedDocValuesCoverageDetailsForMappingWithValidation(
    snapshot: *const index_mod.IndexSnapshot,
    field: []const u8,
    mapping: runtime_schema_mod.FieldMapping,
    validation: ?index_mod.CoverageValidation,
) !TypedDocValuesCoverage {
    var expected_value_type: ?typed_dv.ValueType = null;
    for (snapshot.segments) |*segment| {
        if (segment.liveDocCount() == 0) continue;
        const cached = (segment.typedDocValuesCoverageWithValidation(field, validation) catch |err| switch (err) {
            // Search requests use the historical double-l spelling at this
            // layer; keep that public contract while the shared token remains
            // transport-neutral.
            error.Canceled => return error.Cancelled,
            else => return err,
        }) orelse return .{ .status = .missing_doc_values_section };
        const value_type = cached.value_type orelse return .{ .status = cached.status };
        if (!typedDocValuesTypeMatchesMappedSortField(value_type, mapping)) return .{ .status = .doc_values_kind_mismatch };
        if (expected_value_type) |expected| {
            const both_numeric = mapping.field_type == .numeric and
                typedDocValuesTypeMatchesMappedSortField(expected, mapping) and
                typedDocValuesTypeMatchesMappedSortField(value_type, mapping);
            if (value_type != expected and !both_numeric) return .{ .status = .doc_values_kind_mismatch };
            if (value_type != expected and both_numeric) expected_value_type = .numeric_val;
        } else {
            expected_value_type = value_type;
        }
        if (cached.status != .covered) return .{ .status = cached.status, .value_type = expected_value_type };
    }
    return .{ .status = .covered, .value_type = expected_value_type };
}

fn snapshotTypedDocValuesCoverageForMapping(
    snapshot: *const index_mod.IndexSnapshot,
    field: []const u8,
    mapping: runtime_schema_mod.FieldMapping,
) !TypedDocValuesCoverageStatus {
    return (try snapshotTypedDocValuesCoverageDetailsForMapping(snapshot, field, mapping)).status;
}

fn snapshotGeoPointDocValuesCoverage(
    snapshot: *const index_mod.IndexSnapshot,
    field: []const u8,
) !TypedDocValuesCoverageStatus {
    for (snapshot.segments) |*segment| {
        if (segment.liveDocCount() == 0) continue;
        const cached = (try segment.typedDocValuesCoverage(field)) orelse return .missing_doc_values_section;
        const value_type = cached.value_type orelse return cached.status;
        if (value_type != .geo_point) return .doc_values_kind_mismatch;
        if (cached.status != .covered) return cached.status;
    }
    return .covered;
}

fn sortFieldMapping(schema: runtime_schema_mod.TableSchema, field: []const u8) ?runtime_schema_mod.FieldMapping {
    return runtime_schema_mod.resolveDeclaredFieldType(schema, field);
}

const NativeSortPlanRejectionReason = enum {
    missing_runtime_mapping,
    unmapped_field,
    non_scalar_field,
    non_sortable_field,
    missing_doc_values_capability,
    invalid_cursor_arity,
    invalid_cursor_type,
    invalid_doc_value_type,
    missing_null_policy,
    missing_native_filter_coverage,
    approximate_candidate_source,
    non_score_bearing_source,
    invalid_score_value,
};

fn nativeSortPlanRejectionReasonName(reason: NativeSortPlanRejectionReason) []const u8 {
    return switch (reason) {
        .missing_runtime_mapping => "missing_runtime_mapping",
        .unmapped_field => "unmapped_sort_field",
        .non_scalar_field => "non_sortable_sort_field",
        .non_sortable_field => "non_sortable_sort_field",
        .missing_doc_values_capability => "missing_doc_values_coverage",
        .invalid_cursor_arity => "invalid_cursor_arity",
        .invalid_cursor_type => "invalid_cursor_type",
        .invalid_doc_value_type => "invalid_doc_value_type",
        .missing_null_policy => "missing_null_policy",
        .missing_native_filter_coverage => "missing_native_filter_coverage",
        .approximate_candidate_source => "approximate_candidate_source",
        .non_score_bearing_source => "non_score_bearing_source",
        .invalid_score_value => "invalid_score_value",
    };
}

fn nativeSortPlanRejectionDetailName(reason: NativeSortPlanRejectionReason) []const u8 {
    return switch (reason) {
        .missing_runtime_mapping => "missing_runtime_mapping",
        .unmapped_field => "unmapped_field",
        .non_scalar_field => "non_scalar_field",
        .non_sortable_field => "non_sortable_field",
        .missing_doc_values_capability => "missing_doc_values_capability",
        .invalid_cursor_arity => "invalid_cursor_arity",
        .invalid_cursor_type => "invalid_cursor_type",
        .invalid_doc_value_type => "invalid_doc_value_type",
        .missing_null_policy => "missing_null_policy",
        .missing_native_filter_coverage => "missing_native_filter_coverage",
        .approximate_candidate_source => "approximate_candidate_source",
        .non_score_bearing_source => "non_score_bearing_source",
        .invalid_score_value => "invalid_score_value",
    };
}

