    }, snapshot, schema);

    var hits = try alloc.alloc(types.SearchHit, 2);
    hits[0] = .{ .id = try alloc.dupe(u8, "doc:beta"), .native_text_doc_id = 0, .score = 1.0 };
    hits[1] = .{ .id = try alloc.dupe(u8, "doc:acme"), .native_text_doc_id = 1, .score = 1.0 };
