    const snapshot = writer.snapshot();
    const native_sort_ctx = TextDocValueSortContext{ .snapshot = snapshot };
    const templates = [_]runtime_schema_mod.DynamicTemplate{.{
        .name = "created_at",
        .path_match = "created_at",
